INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u4-C1','kor',1,1,'u4',1,'낱말이 필요한 까닭 — 이름(낱말)을 모르면 「저거·그거」로만 말하게 되어 뜻이 전해지지 않음을 알고, 물건·장소·사람·움직임을 나타내는 말이 모두 낱말임을 알기',ARRAY['2국02-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u4-C2','kor',1,1,'u4',3,'몸과 몸으로 하는 일 — 눈·코·입·귀 같은 얼굴 부분부터 팔·다리까지 몸을 나타내는 낱말을 알고, 몸의 곳과 그곳으로 하는 일(눈-보다·귀-듣다·코-맡다)을 바르게 잇기',ARRAY['2국02-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u4-C3','kor',1,1,'u4',3,'가족을 부르는 말 — 관계에 따라 부르는 말(아빠의 엄마 → 할머니, 엄마의 언니나 여동생 → 이모, 여자아이가 나이 많은 남자 형제 → 오빠)을 알고, 가족과 가족 밖 사람(친구·선생님·이웃)을 가르기',ARRAY['2국02-01']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u4-C4','kor',1,1,'u4',5,'음식 낱말과 꾸며 주는 말 — 음식을 나타내는 낱말을 알고, 맛·모양·크기를 자세히 하는 꾸며 주는 말(매운·긴·네모난·차가운)을 꾸밈 받는 낱말 앞에 어울리게 넣기 — 칭찬하는 말만 꾸며 주는 말이 아님',ARRAY['2국02-01']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u4-C5','kor',1,1,'u4',7,'학교와 이웃 낱말 — 학교·동네에서 볼 수 있는 곳의 이름을 알고, 장소와 그곳에서 하는 일(우체국-편지를 보내요·소방서-불을 꺼요)을 바르게 짝 짓기',ARRAY['2국02-01']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u4-C6','kor',1,1,'u4',7,'주제로 묶고 나누기 — 몸·가족·음식·학교·동네·사람처럼 주제를 세워 낱말을 묶고, 주제에 맞지 않는 낱말을 가려내며, 학교에도 동네에도 있는 낱말(도서관)은 둘 다에 넣을 수 있음을 알기',ARRAY['2국02-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u4-C7','kor',1,1,'u4',9,'이야기 속 낱말 찾고 문장으로 말하기 — 이야기를 끝까지 듣고 나온 낱말(장소·물건)을 차례대로 찾으며, 찾은 낱말을 넣어 뜻에 맞는 문장으로 말하기',ARRAY['2국02-01']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u4-C8','kor',1,1,'u4',11,'말놀이로 낱말 익히기 — 초성 퀴즈(초성 칸 수 = 글자 수), 「학교에 가면 ~도 있고」 이어 말하기(앞 말 모두 + 새 낱말 하나), 글자판에서 가로·세로로 숨은 낱말 찾기',ARRAY['2국02-01']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-1-u4-C9','kor',1,1,'u4',13,'공부할 때 쓰는 낱말 — 있다·없다(반대), 읽다·쓰다(눈으로 보며 소리 내기와 손으로 적기), 차례(순서·내 순번)처럼 교실에서 자주 쓰는 낱말의 뜻을 알고 알맞게 쓰기',ARRAY['2국02-01']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X01','kor',1,'u4',ARRAY['K1-1-u4-C1']::text[],'「저거·그거」라고만 해도 뜻이 전해진다고 여기거나, 낱말을 손에 잡히는 물건 이름으로만 좁게 생각한다','듣는 사람이 눈을 감고 들어도 알 수 있게 — 「저거」 자리에 이름(낱말)을 넣어 다시 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X02','kor',1,'u4',ARRAY['K1-1-u4-C2','K1-1-u4-C6']::text[],'몸을 나타내는 낱말을 팔·다리로만 여기거나, 몸에 걸치는 것(모자·신발)을 몸 낱말로 섞는다','머리끝부터 발끝까지 손으로 짚으며 이름 말하기 — 눈·코·입·귀도 몸, 모자·옷은 걸치는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X03','kor',1,'u4',ARRAY['K1-1-u4-C2']::text[],'몸의 곳과 그곳으로 하는 일을 잘못 잇는다(귀로 보다)','그 일을 직접 해 보며 몸의 어디가 움직이는지 느끼기 — 들을 때는 귀, 볼 때는 눈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X04','kor',1,'u4',ARRAY['K1-1-u4-C3']::text[],'관계와 다른 말로 가족을 부른다(여자아이가 나이 많은 남자 형제를 「형」이라 함, 이모·고모 혼동)','「누구의 누구인가」를 먼저 말해 보기 — 엄마 쪽이면 이모, 아빠 쪽이면 고모') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X05','kor',1,'u4',ARRAY['K1-1-u4-C3','K1-1-u4-C6']::text[],'가족을 부르는 말과 가족 밖 사람(친구·선생님·의사·이웃)을 섞는다','「우리 가족을 부르는 말인가, 밖에서 만나는 사람인가」 두 칸으로 나눠 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X06','kor',1,'u4',ARRAY['K1-1-u4-C4','K1-1-u4-C5','K1-1-u4-C7']::text[],'그림·설명·이야기를 끝까지 보지 않고 비슷한 낱말을 고른다(빵 ↔ 빵집, 치과 ↔ 병원, 소방관 ↔ 소방서)','낱말의 끝 글자까지 손가락으로 짚어 읽고 「사람? 장소? 물건?」을 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X07','kor',1,'u4',ARRAY['K1-1-u4-C4']::text[],'꾸며 주는 말은 「맛있는·예쁜」 같은 칭찬하는 말뿐이라고 여긴다','「작은·네모난·매운」처럼 모양·크기·맛을 자세히 하는 말도 꾸며 주는 말 — 무엇을 더 자세히 해 주는지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X08','kor',1,'u4',ARRAY['K1-1-u4-C4']::text[],'꾸며 주는 말을 꾸밈 받는 낱말 뒤에 쓰거나(사과 빨간) 무엇이 무엇을 꾸미는지 바꿔 생각한다','꾸며 주는 말은 늘 앞 — 「빨간 사과」처럼 읽어 보고 어색하면 자리 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X09','kor',1,'u4',ARRAY['K1-1-u4-C4']::text[],'낱말과 어울리지 않는 꾸며 주는 말을 넣는다(뜨거운 얼음, 네모난 국수)','꾸며 주는 말을 넣은 뒤 그 모습을 머릿속에 그려 보기 — 그림이 이상하면 다른 말로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X10','kor',1,'u4',ARRAY['K1-1-u4-C5']::text[],'장소(또는 사람)와 그곳에서 하는 일을 잘못 잇는다(우체국에서 빵을 사요)','「그곳에 가면 무엇을 하지?」를 떠올려 장소와 일을 한 쌍으로 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X11','kor',1,'u4',ARRAY['K1-1-u4-C5','K1-1-u4-C6']::text[],'학교에서 볼 수 있는 곳과 동네에서 볼 수 있는 곳을 가르지 못하거나, 동네를 우리 집 안으로만 좁히고, 둘 다 되는 낱말(도서관)을 한쪽에만 넣는다','「학교 · 동네 · 둘 다」 세 칸 표를 그려 넣어 보기 — 동네는 집 둘레의 가게·길·공원까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X12','kor',1,'u4',ARRAY['K1-1-u4-C6']::text[],'주제와 상관없는 낱말을 묶음에 넣거나 묶는 기준을 세우지 못한다','묶음 이름(주제)을 먼저 크게 말하고, 낱말마다 「이 주제에 맞나?」 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X13','kor',1,'u4',ARRAY['K1-1-u4-C7']::text[],'이야기를 끝까지 듣지 않아 나온 낱말을 놓치거나 나오지 않은 낱말을 말한다','이야기를 들으며 장소가 나올 때마다 손가락 하나씩 꼽기 — 차례도 함께 기억하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X14','kor',1,'u4',ARRAY['K1-1-u4-C7']::text[],'낱말을 넣어 만든 문장의 뜻이 맞지 않는다(신호등에서 빵을 사요)','만든 문장을 소리 내어 읽고 「정말 그곳에서 그 일을 할까?」 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X15','kor',1,'u4',ARRAY['K1-1-u4-C8']::text[],'이어 말하기 틀(「학교에 가면 ~도 있고」)에 맞지 않게 말하거나 앞 사람이 말한 낱말을 빠뜨린다','앞 친구가 말한 낱말을 손가락으로 꼽으며 그대로 말한 뒤 새 낱말 하나만 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X16','kor',1,'u4',ARRAY['K1-1-u4-C8']::text[],'초성 수와 글자 수, 글자판을 읽는 방향(가로 →·세로 ↓)을 헷갈린다','초성 칸 하나 = 글자 하나, 글자판은 왼쪽에서 오른쪽·위에서 아래로만 이어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-1-u4-X17','kor',1,'u4',ARRAY['K1-1-u4-C9']::text[],'공부할 때 쓰는 낱말의 뜻을 헷갈린다(있다 ↔ 없다, 읽다 ↔ 쓰다, 「차례」를 아무 때나로)','낱말을 몸으로 해 보기 — 읽다는 눈과 입, 쓰다는 손, 차례는 줄을 서서 내 순서를 기다리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_basic#1','kor',1,1,'u4','L01','g1_1_kor_u4_L01_basic','lesson_basic','K1-1-u4-C1',1,'mc','auto','친구가 「저거 주세요.」라고만 했어요. 무엇을 달라는지 알기 어려운 까닭은 무엇인가요?',ARRAY['K1-1-u4-X01']::text[],true,'{"seq":1,"concept":"K1-1-u4-C1","difficulty":1,"kind":"mc","stem":"친구가 「저거 주세요.」라고만 했어요. 무엇을 달라는지 알기 어려운 까닭은 무엇인가요?","options":[{"t":"물건의 이름(낱말)을 말하지 않아서","correct":true},{"t":"「주세요」를 빼고 말해서","mis":"K1-1-u4-X01"},{"t":"목소리가 너무 커서","mis":"K1-1-u4-X01"}],"explanation":["「저거」만으로는 무엇인지 알 수 없어요.","「주세요」나 목소리 크기는 까닭이 아니에요.","물건의 이름을 넣어 말해야 뜻이 전해져요."],"variant_rule":{"alt":[{"stem":"동생이 「그거 어디 있어?」라고만 물었어요. 무엇을 찾는지 알기 어려운 까닭은 무엇인가요?","options":[{"t":"찾는 물건의 이름(낱말)을 말하지 않아서","correct":true},{"t":"「어디」라는 말을 넣어서","mis":"K1-1-u4-X01"},{"t":"너무 천천히 말해서","mis":"K1-1-u4-X01"}],"explanation":["「그거」만으로는 무엇인지 알 수 없어요.","「어디」나 말 빠르기는 까닭이 아니에요.","찾는 물건의 이름을 넣어 물어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_basic#2','kor',1,1,'u4','L01','g1_1_kor_u4_L01_basic','lesson_basic','K1-1-u4-C1',1,'ox','auto','물건 이름을 몰라도 「저거」라고만 하면 언제나 뜻이 잘 전해져요.',ARRAY['K1-1-u4-X01']::text[],true,'{"seq":2,"concept":"K1-1-u4-C1","difficulty":1,"kind":"ox","stem":"물건 이름을 몰라도 「저거」라고만 하면 언제나 뜻이 잘 전해져요.","answer":"X","reason_options":[{"t":"「저거」는 무엇을 가리키는지 듣는 사람이 알 수 없을 때가 많으니까","correct":true},{"t":"손으로 가리키면 언제나 알아들으니까","mis":"K1-1-u4-X01"}],"mis":"K1-1-u4-X01","explanation":["멀리 있거나 여러 개가 있으면 「저거」로는 몰라요.","이름을 말하면 눈을 감고 들어도 알 수 있어요.","그래서 낱말을 많이 알아야 해요."],"variant_rule":{"alt":[{"stem":"물건 이름을 정확하게 말하면 듣는 사람이 무엇인지 바로 알 수 있어요.","answer":"O","reason_options":[{"t":"낱말은 그 물건 하나를 콕 집어 알려 주니까","correct":true},{"t":"큰 소리로 말해야만 알아들으니까","mis":"K1-1-u4-X01"}],"explanation":["「연필」이라고 하면 바로 연필을 떠올려요.","소리 크기가 아니라 낱말이 뜻을 전해요.","이름을 넣어 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_basic#3','kor',1,1,'u4','L01','g1_1_kor_u4_L01_basic','lesson_basic','K1-1-u4-C1',1,'mc','auto','그림을 보고 「저거」를 알맞은 낱말로 바꾸어 말한 것은 어느 것인가요?',ARRAY['K1-1-u4-X01']::text[],true,'{"seq":3,"concept":"K1-1-u4-C1","difficulty":1,"kind":"mc","stem":"그림을 보고 「저거」를 알맞은 낱말로 바꾸어 말한 것은 어느 것인가요?","options":[{"t":"「사과 먹고 싶어요.」","correct":true},{"t":"「저것 먹고 싶어요.」","mis":"K1-1-u4-X01"},{"t":"「그거 먹고 싶어요.」","mis":"K1-1-u4-X01"}],"explanation":["그림은 「사과」예요.","「저것」·「그거」도 이름이 아니에요.","「저거」 자리에 이름을 넣어요."],"asset":{"type":"scene","icon":"🍎","text":"저거 먹고 싶어요."},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림을 보고 「저거」를 알맞은 낱말로 바꾸어 말한 것은 어느 것인가요?","options":[{"t":"「연필 빌려줄래?」","correct":true},{"t":"「이거 빌려줄래?」","mis":"K1-1-u4-X01"},{"t":"「저기 빌려줄래?」","mis":"K1-1-u4-X01"}],"explanation":["그림은 「연필」이에요.","「이거」·「저기」도 이름이 아니에요.","「저거」 자리에 이름을 넣어요."],"asset":{"type":"scene","icon":"✏️","text":"저거 빌려줄래?"}},{"stem":"이번에는 다른 보기예요. 그림을 보고 「저거」를 알맞은 낱말로 바꾸어 말한 것은 어느 것인가요?","options":[{"t":"「버스 타고 가요.」","correct":true},{"t":"「그거 타고 가요.」","mis":"K1-1-u4-X01"},{"t":"「저쪽 타고 가요.」","mis":"K1-1-u4-X01"}],"explanation":["그림은 「버스」예요.","「그거」·「저쪽」도 이름이 아니에요.","「저거」 자리에 이름을 넣어요."],"asset":{"type":"scene","icon":"🚌","text":"저거 타고 가요."}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_basic#4','kor',1,1,'u4','L01','g1_1_kor_u4_L01_basic','lesson_basic','K1-1-u4-C2',1,'mc','auto','몸을 나타내는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X02','K1-1-u4-X12']::text[],true,'{"seq":4,"concept":"K1-1-u4-C2","difficulty":1,"kind":"mc","stem":"몸을 나타내는 낱말은 어느 것인가요?","options":[{"t":"손","correct":true},{"t":"모자","mis":"K1-1-u4-X02"},{"t":"김밥","mis":"K1-1-u4-X12"}],"explanation":["「손」은 몸을 나타내는 낱말이에요.","「모자」·「김밥」은 몸을 나타내는 낱말이 아니에요.","낱말이 무엇을 나타내는지 떠올려 묶음을 정해요."],"variant_rule":{"wcat":{"ask":"pick","cats":["body"],"mis":{"near":"X02","other":"X12"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_basic#5','kor',1,1,'u4','L01','g1_1_kor_u4_L01_basic','lesson_basic','K1-1-u4-C1',2,'mc','auto','낱말을 많이 알면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u4-X01']::text[],false,'{"seq":5,"concept":"K1-1-u4-C1","difficulty":2,"kind":"mc","stem":"낱말을 많이 알면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"내 생각을 정확하게 말하고 쓸 수 있어요","correct":true},{"t":"말을 짧게 「저거」로만 해도 돼요","mis":"K1-1-u4-X01"},{"t":"물건 이름만 알면 되고 장소 이름은 몰라도 돼요","mis":"K1-1-u4-X01"}],"explanation":["낱말을 알면 하고 싶은 말을 콕 집어 말할 수 있어요.","「저거」로는 뜻이 잘 전해지지 않고, 장소 이름도 낱말이에요.","낱말이 많을수록 말과 글이 또렷해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_basic#6','kor',1,1,'u4','L01','g1_1_kor_u4_L01_basic','lesson_basic','K1-1-u4-C1',2,'match','auto','「저거」 대신 넣을 낱말을 이으세요.','{}'::text[],true,'{"seq":6,"concept":"K1-1-u4-C1","difficulty":2,"kind":"match","stem":"「저거」 대신 넣을 낱말을 이으세요.","pairs":[{"l":"🚌 저거를 타요.","r":"버스"},{"l":"☂️ 저거를 펴요.","r":"우산"},{"l":"🎒 저거를 메요.","r":"가방"}],"mis":"K1-1-u4-X01","explanation":["🚌 버스, ☂️ 우산, 🎒 가방.","그림을 보고 이름을 떠올려요.","이름을 넣으면 뜻이 바로 전해져요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 「저거」 대신 넣을 낱말을 이으세요.","pairs":[{"l":"🧦 저거를 신어요.","r":"양말"},{"l":"🎈 저거를 불어요.","r":"풍선"},{"l":"🚲 저거를 타요.","r":"자전거"}],"explanation":["🧦 양말, 🎈 풍선, 🚲 자전거.","그림을 보고 이름을 떠올려요.","이름을 넣으면 뜻이 바로 전해져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_basic#7','kor',1,1,'u4','L01','g1_1_kor_u4_L01_basic','lesson_basic','K1-1-u4-C1',2,'error','auto','하린이가 엄마께 남긴 쪽지예요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_basic#8','kor',1,1,'u4','L01','g1_1_kor_u4_L01_basic','lesson_basic','K1-1-u4-C6',2,'mc','auto','음식을 나타내는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X12']::text[],true,'{"seq":8,"concept":"K1-1-u4-C6","difficulty":2,"kind":"mc","stem":"음식을 나타내는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"접시","correct":true},{"t":"국수","mis":"K1-1-u4-X12"},{"t":"김치","mis":"K1-1-u4-X12"}],"explanation":["「접시」는 음식을 나타내는 낱말이 아니에요.","「국수」·「김치」는 음식을 나타내는 낱말이에요.","묶음마다 무엇을 모았는지 먼저 떠올리고 하나씩 견주어요."],"variant_rule":{"wcat":{"ask":"odd","cats":["food"],"mis":{"in":"X12","near":"X12"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_basic#9','kor',1,1,'u4','L01','g1_1_kor_u4_L01_basic','lesson_basic','K1-1-u4-C2',2,'mc','auto','몸을 나타내는 낱말만 모은 것은 어느 것인가요?',ARRAY['K1-1-u4-X02']::text[],true,'{"seq":9,"concept":"K1-1-u4-C2","difficulty":2,"kind":"mc","stem":"몸을 나타내는 낱말만 모은 것은 어느 것인가요?","options":[{"t":"눈 · 코 · 입","correct":true},{"t":"손 · 발 · 모자","mis":"K1-1-u4-X02"},{"t":"팔 · 다리 · 신발","mis":"K1-1-u4-X02"}],"explanation":["눈·코·입은 모두 얼굴에 있는 몸의 곳이에요.","모자·신발은 몸에 걸치는 것이에요.","얼굴 부분도 몸을 나타내는 낱말이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몸을 나타내는 낱말만 모은 것은 어느 것인가요?","options":[{"t":"머리 · 어깨 · 무릎","correct":true},{"t":"머리 · 어깨 · 장갑","mis":"K1-1-u4-X02"},{"t":"양말 · 어깨 · 무릎","mis":"K1-1-u4-X02"}],"explanation":["머리·어깨·무릎은 모두 몸의 곳이에요.","장갑·양말은 몸에 끼우거나 신는 것이에요.","몸에 걸치는 것과 몸을 나눠요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_basic#10','kor',1,1,'u4','L01','g1_1_kor_u4_L01_basic','lesson_basic','K1-1-u4-C1',3,'mc','auto','가게에서 「저기 저거 두 개 주세요.」라고 했더니 주인이 다른 빵을 주었어요. 어떻게 말했어야 할까요?',ARRAY['K1-1-u4-X01']::text[],true,'{"seq":10,"concept":"K1-1-u4-C1","difficulty":3,"kind":"mc","stem":"가게에서 「저기 저거 두 개 주세요.」라고 했더니 주인이 다른 빵을 주었어요. 어떻게 말했어야 할까요?","options":[{"t":"「크림빵 두 개 주세요.」","correct":true},{"t":"「저기 저거 두 개 주세요!」 하고 더 크게","mis":"K1-1-u4-X01"},{"t":"「저거 말고 저거요.」","mis":"K1-1-u4-X01"}],"explanation":["빵 이름을 넣어야 주인이 바로 알아요.","더 크게 말하거나 「저거」를 되풀이해도 몰라요.","낱말을 넣어 콕 집어 말해요."],"variant_rule":{"alt":[{"stem":"문구점에서 「그거 하나 주세요.」라고 했더니 주인이 다른 공책을 주었어요. 어떻게 말했어야 할까요?","options":[{"t":"「줄 공책 하나 주세요.」","correct":true},{"t":"「그거 하나 주세요!」 하고 더 크게","mis":"K1-1-u4-X01"},{"t":"「그거 말고 그거요.」","mis":"K1-1-u4-X01"}],"explanation":["공책 이름을 넣어야 주인이 바로 알아요.","더 크게 말하거나 「그거」를 되풀이해도 몰라요.","낱말을 넣어 콕 집어 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_challenge#1','kor',1,1,'u4','L01','g1_1_kor_u4_L01_challenge','lesson_challenge','K1-1-u4-C2',2,'mc','auto','「귀」로 하는 일을 나타내는 말은 어느 것인가요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":1,"concept":"K1-1-u4-C2","difficulty":2,"kind":"mc","stem":"「귀」로 하는 일을 나타내는 말은 어느 것인가요?","options":[{"t":"듣다","correct":true},{"t":"보다","mis":"K1-1-u4-X03"},{"t":"걷다","mis":"K1-1-u4-X03"}],"explanation":["「귀」로 하는 일은 「듣다」예요.","「보다」·「걷다」는 몸의 다른 곳으로 하는 일이에요.","몸의 그곳을 직접 움직여 보며 무엇을 하는지 떠올려요."],"variant_rule":{"wlink":{"ask":"body","mis":{"link":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_challenge#2','kor',1,1,'u4','L01','g1_1_kor_u4_L01_challenge','lesson_challenge','K1-1-u4-C1',2,'mc','auto','낱말에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K1-1-u4-X01']::text[],false,'{"seq":2,"concept":"K1-1-u4-C1","difficulty":2,"kind":"mc","stem":"낱말에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"물건뿐 아니라 장소·사람·움직임을 나타내는 말도 낱말이에요","correct":true},{"t":"손으로 만질 수 있는 물건 이름만 낱말이에요","mis":"K1-1-u4-X01"},{"t":"「저거」·「그거」도 이름이니까 낱말 대신 써도 돼요","mis":"K1-1-u4-X01"}],"explanation":["교실·선생님·달리다도 모두 낱말이에요.","물건 이름만 낱말인 것은 아니에요.","「저거」는 이름 대신 가리키는 말이라 뜻이 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_challenge#3','kor',1,1,'u4','L01','g1_1_kor_u4_L01_challenge','lesson_challenge','K1-1-u4-C1',3,'mc','auto','지안이가 공원에서 「저기 저거 봐!」라고 했어요. 친구는 하늘의 새를 보았지만, 지안이는 나무 위 다람쥐를 가리켰어요. 친구가 다른 것을 본 까닭은 무엇인가요?',ARRAY['K1-1-u4-X13']::text[],false,'{"seq":3,"concept":"K1-1-u4-C1","difficulty":3,"kind":"mc","stem":"지안이가 공원에서 「저기 저거 봐!」라고 했어요. 친구는 하늘의 새를 보았지만, 지안이는 나무 위 다람쥐를 가리켰어요. 친구가 다른 것을 본 까닭은 무엇인가요?","options":[{"t":"지안이가 「다람쥐」라는 낱말을 말하지 않아서","correct":true},{"t":"친구가 하늘만 좋아해서","mis":"K1-1-u4-X13"},{"t":"새가 다람쥐보다 커서","mis":"K1-1-u4-X13"}],"explanation":["「저거」로는 새인지 다람쥐인지 알 수 없어요.","친구 마음이나 크기 때문이 아니에요.","「저기 나무 위 다람쥐 봐!」라고 말하면 돼요."],"asset":{"type":"scene","icon":"🐿️🌳🐦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_challenge#4','kor',1,1,'u4','L01','g1_1_kor_u4_L01_challenge','lesson_challenge','K1-1-u4-C2',3,'error','auto','준우가 「몸을 나타내는 낱말은 손·발·팔·다리뿐이에요.」라고 말했어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u4-X02','K1-1-u4-X12']::text[],false,'{"seq":4,"concept":"K1-1-u4-C2","difficulty":3,"kind":"error","stem":"준우가 「몸을 나타내는 낱말은 손·발·팔·다리뿐이에요.」라고 말했어요. 무엇이 잘못되었나요?","options":[{"t":"눈·코·입·귀처럼 얼굴 부분도 몸을 나타내는 낱말이에요","correct":true,"mis_target":"K1-1-u4-X02"},{"t":"「다리」는 건너는 다리라서 빼야 해요","mis":"K1-1-u4-X12"},{"t":"손과 발은 몸이 아니에요","mis":"K1-1-u4-X02"}],"explanation":["몸은 머리끝부터 발끝까지 모두예요.","「다리」는 몸의 곳이고, 손·발도 몸이에요.","얼굴부터 발끝까지 짚으며 이름을 말해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_challenge#5','kor',1,1,'u4','L01','g1_1_kor_u4_L01_challenge','lesson_challenge','K1-1-u4-C6',3,'mc','auto','가족을 부르는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X05']::text[],true,'{"seq":5,"concept":"K1-1-u4-C6","difficulty":3,"kind":"mc","stem":"가족을 부르는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"친구","correct":true},{"t":"이모","mis":"K1-1-u4-X05"},{"t":"삼촌","mis":"K1-1-u4-X05"}],"explanation":["「친구」는 가족을 부르는 낱말이 아니에요.","「이모」·「삼촌」은 가족을 부르는 낱말이에요.","묶음마다 무엇을 모았는지 먼저 떠올리고 하나씩 견주어요."],"variant_rule":{"wcat":{"ask":"odd","cats":["family"],"mis":{"in":"X05","near":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_challenge#6','kor',1,1,'u4','L01','g1_1_kor_u4_L01_challenge','lesson_challenge','K1-1-u4-C1',3,'mc','auto','「비가 와서 (     )을 썼어요.」 빈칸에 넣어 뜻이 잘 전해지는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X01','K1-1-u4-X14']::text[],true,'{"seq":6,"concept":"K1-1-u4-C1","difficulty":3,"kind":"mc","stem":"「비가 와서 (     )을 썼어요.」 빈칸에 넣어 뜻이 잘 전해지는 낱말은 어느 것인가요?","options":[{"t":"우산","correct":true},{"t":"그것","mis":"K1-1-u4-X01"},{"t":"양말","mis":"K1-1-u4-X14"}],"explanation":["비가 올 때 쓰는 것은 「우산」이에요.","「그것」은 이름이 아니고, 양말은 쓰는 것이 아니에요.","빈칸에 이름을 넣어 소리 내어 읽어 봐요."],"variant_rule":{"alt":[{"stem":"「배가 고파서 (     )을 먹었어요.」 빈칸에 넣어 뜻이 잘 전해지는 낱말은 어느 것인가요?","options":[{"t":"김밥","correct":true},{"t":"저것","mis":"K1-1-u4-X01"},{"t":"가방","mis":"K1-1-u4-X14"}],"explanation":["먹는 것은 「김밥」이에요.","「저것」은 이름이 아니고, 가방은 먹지 않아요.","빈칸에 이름을 넣어 읽어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_challenge#7','kor',1,1,'u4','L01','g1_1_kor_u4_L01_challenge','lesson_challenge','K1-1-u4-C1',3,'mc','auto','동생이 「그거, 그거!」 하며 울어요. 동생이 무엇을 바라는지 알아보려면 어떻게 하면 좋을까요?',ARRAY['K1-1-u4-X01']::text[],false,'{"seq":7,"concept":"K1-1-u4-C1","difficulty":3,"kind":"mc","stem":"동생이 「그거, 그거!」 하며 울어요. 동생이 무엇을 바라는지 알아보려면 어떻게 하면 좋을까요?","options":[{"t":"무엇이 필요한지 이름으로 말해 보라고 차분히 물어봐요","correct":true},{"t":"「그거」를 더 크게 말하라고 해요","mis":"K1-1-u4-X01"},{"t":"아무거나 집어서 건네줘요","mis":"K1-1-u4-X01"}],"explanation":["이름을 들으면 무엇을 바라는지 바로 알아요.","「그거」를 크게 말해도 무엇인지는 몰라요.","이름을 모르면 생김새를 말해 보게 해요."],"asset":{"type":"scene","icon":"🧸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_challenge#8','kor',1,1,'u4','L01','g1_1_kor_u4_L01_challenge','lesson_challenge','K1-1-u4-C1',4,'mc','auto','민호와 선생님이 나눈 말이에요. 민호가 한 번에 뜻을 전하려면 어떻게 말해야 했나요?',ARRAY['K1-1-u4-X01']::text[],false,'{"seq":8,"concept":"K1-1-u4-C1","difficulty":4,"kind":"mc","stem":"민호와 선생님이 나눈 말이에요. 민호가 한 번에 뜻을 전하려면 어떻게 말해야 했나요?","options":[{"t":"「크레파스 어디 있어요?」처럼 물건 이름을 넣어서","correct":true},{"t":"「그거 어디 있어요?」를 여러 번 말해서","mis":"K1-1-u4-X01"},{"t":"「그림 그리는 거요.」라고만 말해서","mis":"K1-1-u4-X01"}],"explanation":["물건 이름을 넣으면 한 번에 알아들어요.","같은 말을 되풀이하면 선생님은 계속 되물어야 해요.","「그림 그리는 거」는 색연필·물감일 수도 있어요."],"asset":{"type":"speech","turns":[{"who":"민호","text":"선생님, 그거 어디 있어요?"},{"who":"선생님","text":"무엇 말이니?"},{"who":"민호","text":"그거요, 그림 그리는 거."},{"who":"선생님","text":"색연필? 크레파스? 물감?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_challenge#9','kor',1,1,'u4','L01','g1_1_kor_u4_L01_challenge','lesson_challenge','K1-1-u4-C1',4,'essay','teacher','그림을 보고 「저거 타고 공원에 가요.」를 낱말을 넣어 고쳐 쓰고, 낱말이 필요한 까닭을 말해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-1-u4-C1","difficulty":4,"kind":"essay","stem":"그림을 보고 「저거 타고 공원에 가요.」를 낱말을 넣어 고쳐 쓰고, 낱말이 필요한 까닭을 말해 보세요.","answer_guide":{"answer":"예: 「자전거 타고 공원에 가요.」 — 낱말을 말해야 듣는 사람이 무엇을 타는지 바로 알 수 있어요.","scoring_points":["「저거」를 그림에 맞는 낱말(자전거)로 바꾸었는가","고친 문장이 뜻에 맞는가","듣는 사람이 바로 알 수 있다는 까닭을 말했는가"]},"explanation":["「저거」 → 「자전거」.","고친 문장을 소리 내어 읽어 봐요.","낱말은 뜻을 콕 집어 전해 줘요."],"asset":{"type":"scene","icon":"🚲"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L01_challenge#10','kor',1,1,'u4','L01','g1_1_kor_u4_L01_challenge','lesson_challenge','K1-1-u4-C2',4,'mc','auto','몸을 나타내는 낱말이 들어 있지 않은 문장은 어느 것인가요?',ARRAY['K1-1-u4-X02']::text[],true,'{"seq":10,"concept":"K1-1-u4-C2","difficulty":4,"kind":"mc","stem":"몸을 나타내는 낱말이 들어 있지 않은 문장은 어느 것인가요?","options":[{"t":"「모자를 쓰고 나가요.」","correct":true},{"t":"「손을 깨끗이 씻어요.」","mis":"K1-1-u4-X02"},{"t":"「눈을 감고 쉬어요.」","mis":"K1-1-u4-X02"}],"explanation":["「모자」는 몸에 쓰는 것이지 몸이 아니에요.","「손」·「눈」은 몸을 나타내는 낱말이에요.","문장마다 몸의 곳이 있는지 찾아봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몸을 나타내는 낱말이 들어 있지 않은 문장은 어느 것인가요?","options":[{"t":"「신발을 신고 달려요.」","correct":true},{"t":"「귀를 기울여 들어요.」","mis":"K1-1-u4-X02"},{"t":"「어깨를 쭉 펴요.」","mis":"K1-1-u4-X02"}],"explanation":["「신발」은 발에 신는 것이지 몸이 아니에요.","「귀」·「어깨」는 몸을 나타내는 낱말이에요.","몸과 몸에 걸치는 것을 나눠요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_basic#1','kor',1,1,'u4','L03','g1_1_kor_u4_L03_basic','lesson_basic','K1-1-u4-C2',1,'mc','auto','「눈」으로 하는 일을 나타내는 말은 어느 것인가요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":1,"concept":"K1-1-u4-C2","difficulty":1,"kind":"mc","stem":"「눈」으로 하는 일을 나타내는 말은 어느 것인가요?","options":[{"t":"보다","correct":true},{"t":"듣다","mis":"K1-1-u4-X03"},{"t":"걷다","mis":"K1-1-u4-X03"}],"explanation":["「눈」으로 하는 일은 「보다」예요.","「듣다」·「걷다」는 몸의 다른 곳으로 하는 일이에요.","몸의 그곳을 직접 움직여 보며 무엇을 하는지 떠올려요."],"variant_rule":{"wlink":{"ask":"body","mis":{"link":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_basic#2','kor',1,1,'u4','L03','g1_1_kor_u4_L03_basic','lesson_basic','K1-1-u4-C2',1,'mc','auto','몸을 나타내는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X02','K1-1-u4-X12']::text[],true,'{"seq":2,"concept":"K1-1-u4-C2","difficulty":1,"kind":"mc","stem":"몸을 나타내는 낱말은 어느 것인가요?","options":[{"t":"코","correct":true},{"t":"양말","mis":"K1-1-u4-X02"},{"t":"라면","mis":"K1-1-u4-X12"}],"explanation":["「코」는 몸을 나타내는 낱말이에요.","「양말」·「라면」은 몸을 나타내는 낱말이 아니에요.","낱말이 무엇을 나타내는지 떠올려 묶음을 정해요."],"variant_rule":{"wcat":{"ask":"pick","cats":["body"],"mis":{"near":"X02","other":"X12"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_basic#3','kor',1,1,'u4','L03','g1_1_kor_u4_L03_basic','lesson_basic','K1-1-u4-C3',1,'mc','auto','아빠의 엄마를 부르는 말은 어느 것인가요?',ARRAY['K1-1-u4-X04']::text[],true,'{"seq":3,"concept":"K1-1-u4-C3","difficulty":1,"kind":"mc","stem":"아빠의 엄마를 부르는 말은 어느 것인가요?","options":[{"t":"할머니","correct":true},{"t":"이모","mis":"K1-1-u4-X04"},{"t":"누나","mis":"K1-1-u4-X04"}],"explanation":["아빠의 엄마는 「할머니」예요.","이모는 엄마의 언니나 여동생, 누나는 남자아이의 나이 많은 여자 형제예요.","「누구의 누구인가」를 먼저 떠올려요."],"variant_rule":{"alt":[{"stem":"아빠의 아빠를 부르는 말은 어느 것인가요?","options":[{"t":"할아버지","correct":true},{"t":"삼촌","mis":"K1-1-u4-X04"},{"t":"오빠","mis":"K1-1-u4-X04"}],"explanation":["아빠의 아빠는 「할아버지」예요.","삼촌·오빠는 다른 관계예요.","「누구의 누구인가」를 먼저 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_basic#4','kor',1,1,'u4','L03','g1_1_kor_u4_L03_basic','lesson_basic','K1-1-u4-C2',1,'ox','auto','「귀」는 몸을 나타내는 낱말이에요.',ARRAY['K1-1-u4-X02']::text[],true,'{"seq":4,"concept":"K1-1-u4-C2","difficulty":1,"kind":"ox","stem":"「귀」는 몸을 나타내는 낱말이에요.","answer":"O","reason_options":[{"t":"귀는 얼굴 옆에 있는 몸의 한 곳이니까","correct":true},{"t":"팔과 다리만 몸이니까","mis":"K1-1-u4-X02"}],"mis":"K1-1-u4-X02","explanation":["귀는 소리를 듣는 몸의 곳이에요.","얼굴 부분도 몸이에요.","머리끝부터 발끝까지 모두 몸이에요."],"variant_rule":{"alt":[{"stem":"「신발」은 몸을 나타내는 낱말이에요.","answer":"X","reason_options":[{"t":"신발은 발에 신는 물건이지 몸이 아니니까","correct":true},{"t":"발에 붙어 있으니 몸이니까","mis":"K1-1-u4-X02"}],"explanation":["신발은 몸에 걸치는 물건이에요.","몸을 나타내는 낱말은 「발」이에요.","몸과 몸에 걸치는 것을 나눠요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_basic#5','kor',1,1,'u4','L03','g1_1_kor_u4_L03_basic','lesson_basic','K1-1-u4-C2',2,'mc','auto','「냄새를 맡다」는 몸의 어느 곳으로 하는 일인가요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":5,"concept":"K1-1-u4-C2","difficulty":2,"kind":"mc","stem":"「냄새를 맡다」는 몸의 어느 곳으로 하는 일인가요?","options":[{"t":"코","correct":true},{"t":"귀","mis":"K1-1-u4-X03"},{"t":"손","mis":"K1-1-u4-X03"}],"explanation":["「냄새를 맡다」는 「코」로 하는 일이에요.","「귀」·「손」은 다른 일을 해요.","그 일을 할 때 몸의 어디가 바빠지는지 떠올려요."],"variant_rule":{"wlink":{"ask":"bodyr","mis":{"link":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_basic#6','kor',1,1,'u4','L03','g1_1_kor_u4_L03_basic','lesson_basic','K1-1-u4-C3',2,'mc','auto','남자아이가 자기보다 나이가 많은 여자 형제를 부르는 말은 어느 것인가요?',ARRAY['K1-1-u4-X04']::text[],true,'{"seq":6,"concept":"K1-1-u4-C3","difficulty":2,"kind":"mc","stem":"남자아이가 자기보다 나이가 많은 여자 형제를 부르는 말은 어느 것인가요?","options":[{"t":"누나","correct":true},{"t":"언니","mis":"K1-1-u4-X04"},{"t":"이모","mis":"K1-1-u4-X04"}],"explanation":["남자아이는 「누나」라고 불러요.","「언니」는 여자아이가 부르는 말, 이모는 엄마의 언니나 여동생이에요.","부르는 사람이 누구인지도 살펴요."],"variant_rule":{"alt":[{"stem":"여자아이가 자기보다 나이가 많은 여자 형제를 부르는 말은 어느 것인가요?","options":[{"t":"언니","correct":true},{"t":"누나","mis":"K1-1-u4-X04"},{"t":"고모","mis":"K1-1-u4-X04"}],"explanation":["여자아이는 「언니」라고 불러요.","「누나」는 남자아이가 부르는 말, 고모는 아빠의 누나나 여동생이에요.","부르는 사람이 누구인지도 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_basic#7','kor',1,1,'u4','L03','g1_1_kor_u4_L03_basic','lesson_basic','K1-1-u4-C3',2,'mc','auto','가족을 부르는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X05','K1-1-u4-X12']::text[],true,'{"seq":7,"concept":"K1-1-u4-C3","difficulty":2,"kind":"mc","stem":"가족을 부르는 낱말은 어느 것인가요?","options":[{"t":"할아버지","correct":true},{"t":"의사","mis":"K1-1-u4-X05"},{"t":"어깨","mis":"K1-1-u4-X12"}],"explanation":["「할아버지」는 가족을 부르는 낱말이에요.","「의사」·「어깨」는 가족을 부르는 낱말이 아니에요.","낱말이 무엇을 나타내는지 떠올려 묶음을 정해요."],"variant_rule":{"wcat":{"ask":"pick","cats":["family"],"mis":{"near":"X05","other":"X12"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_basic#8','kor',1,1,'u4','L03','g1_1_kor_u4_L03_basic','lesson_basic','K1-1-u4-C2',2,'match','auto','몸의 곳과 그곳으로 하는 일을 이으세요.','{}'::text[],true,'{"seq":8,"concept":"K1-1-u4-C2","difficulty":2,"kind":"match","stem":"몸의 곳과 그곳으로 하는 일을 이으세요.","pairs":[{"l":"눈","r":"보다"},{"l":"귀","r":"듣다"},{"l":"발","r":"걷다"}],"mis":"K1-1-u4-X03","explanation":["눈-보다, 귀-듣다, 발-걷다.","직접 해 보며 몸의 어디가 움직이는지 느껴요.","몸과 하는 일은 짝이 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몸의 곳과 그곳으로 하는 일을 이으세요.","pairs":[{"l":"코","r":"냄새를 맡다"},{"l":"손","r":"잡다"},{"l":"입","r":"먹다"}],"explanation":["코-냄새를 맡다, 손-잡다, 입-먹다.","직접 해 보며 느껴요.","몸과 하는 일은 짝이 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_basic#9','kor',1,1,'u4','L03','g1_1_kor_u4_L03_basic','lesson_basic','K1-1-u4-C3',2,'mc','auto','엄마의 언니나 여동생을 부르는 말은 어느 것인가요?',ARRAY['K1-1-u4-X04']::text[],true,'{"seq":9,"concept":"K1-1-u4-C3","difficulty":2,"kind":"mc","stem":"엄마의 언니나 여동생을 부르는 말은 어느 것인가요?","options":[{"t":"이모","correct":true},{"t":"고모","mis":"K1-1-u4-X04"},{"t":"할머니","mis":"K1-1-u4-X04"}],"explanation":["엄마 쪽은 「이모」예요.","「고모」는 아빠의 누나나 여동생이에요.","엄마 쪽인지 아빠 쪽인지 먼저 살펴요."],"variant_rule":{"alt":[{"stem":"아빠의 누나나 여동생을 부르는 말은 어느 것인가요?","options":[{"t":"고모","correct":true},{"t":"이모","mis":"K1-1-u4-X04"},{"t":"언니","mis":"K1-1-u4-X04"}],"explanation":["아빠 쪽은 「고모」예요.","「이모」는 엄마의 언니나 여동생이에요.","엄마 쪽인지 아빠 쪽인지 먼저 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_basic#10','kor',1,1,'u4','L03','g1_1_kor_u4_L03_basic','lesson_basic','K1-1-u4-C2',3,'mc','auto','「노래를 들으며 박자에 맞춰 손뼉을 쳐요.」 이 일을 할 때 쓰는 몸의 두 곳은 어디인가요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":10,"concept":"K1-1-u4-C2","difficulty":3,"kind":"mc","stem":"「노래를 들으며 박자에 맞춰 손뼉을 쳐요.」 이 일을 할 때 쓰는 몸의 두 곳은 어디인가요?","options":[{"t":"귀와 손","correct":true},{"t":"눈과 발","mis":"K1-1-u4-X03"},{"t":"코와 입","mis":"K1-1-u4-X03"}],"explanation":["노래는 귀로 듣고, 손뼉은 손으로 쳐요.","눈·발·코·입은 이 일에서 바쁘지 않아요.","문장 속 하는 일마다 몸의 곳을 짝 지어요."],"variant_rule":{"alt":[{"stem":"「공을 보고 힘껏 차요.」 이 일을 할 때 쓰는 몸의 두 곳은 어디인가요?","options":[{"t":"눈과 발","correct":true},{"t":"귀와 손","mis":"K1-1-u4-X03"},{"t":"코와 입","mis":"K1-1-u4-X03"}],"explanation":["공은 눈으로 보고, 발로 차요.","귀·손·코·입은 이 일에서 바쁘지 않아요.","하는 일마다 몸의 곳을 짝 지어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_challenge#1','kor',1,1,'u4','L03','g1_1_kor_u4_L03_challenge','lesson_challenge','K1-1-u4-C3',2,'mc','auto','여자아이가 자기보다 나이가 많은 남자 형제를 부르는 말은 어느 것인가요?',ARRAY['K1-1-u4-X04']::text[],true,'{"seq":1,"concept":"K1-1-u4-C3","difficulty":2,"kind":"mc","stem":"여자아이가 자기보다 나이가 많은 남자 형제를 부르는 말은 어느 것인가요?","options":[{"t":"오빠","correct":true},{"t":"형","mis":"K1-1-u4-X04"},{"t":"삼촌","mis":"K1-1-u4-X04"}],"explanation":["여자아이는 「오빠」라고 불러요.","「형」은 남자아이가 부르는 말이에요.","부르는 사람이 누구인지 살펴요."],"variant_rule":{"alt":[{"stem":"남자아이가 자기보다 나이가 많은 남자 형제를 부르는 말은 어느 것인가요?","options":[{"t":"형","correct":true},{"t":"오빠","mis":"K1-1-u4-X04"},{"t":"삼촌","mis":"K1-1-u4-X04"}],"explanation":["남자아이는 「형」이라고 불러요.","「오빠」는 여자아이가 부르는 말이에요.","부르는 사람이 누구인지 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_challenge#2','kor',1,1,'u4','L03','g1_1_kor_u4_L03_challenge','lesson_challenge','K1-1-u4-C2',2,'mc','auto','「잡다」는 몸의 어느 곳으로 하는 일인가요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":2,"concept":"K1-1-u4-C2","difficulty":2,"kind":"mc","stem":"「잡다」는 몸의 어느 곳으로 하는 일인가요?","options":[{"t":"손","correct":true},{"t":"발","mis":"K1-1-u4-X03"},{"t":"눈","mis":"K1-1-u4-X03"}],"explanation":["「잡다」는 「손」으로 하는 일이에요.","「발」·「눈」은 다른 일을 해요.","그 일을 할 때 몸의 어디가 바빠지는지 떠올려요."],"variant_rule":{"wlink":{"ask":"bodyr","mis":{"link":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_challenge#3','kor',1,1,'u4','L03','g1_1_kor_u4_L03_challenge','lesson_challenge','K1-1-u4-C3',3,'mc','auto','「고모」는 누구를 부르는 말인가요?',ARRAY['K1-1-u4-X04','K1-1-u4-X05']::text[],false,'{"seq":3,"concept":"K1-1-u4-C3","difficulty":3,"kind":"mc","stem":"「고모」는 누구를 부르는 말인가요?","options":[{"t":"아빠의 누나나 여동생","correct":true},{"t":"엄마의 언니나 여동생","mis":"K1-1-u4-X04"},{"t":"아빠의 친구","mis":"K1-1-u4-X05"}],"explanation":["고모는 아빠 쪽 여자 형제예요.","엄마의 언니나 여동생은 「이모」예요.","아빠의 친구는 가족을 부르는 말로 부르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_challenge#4','kor',1,1,'u4','L03','g1_1_kor_u4_L03_challenge','lesson_challenge','K1-1-u4-C3',3,'error','auto','은솔이는 여자아이예요. 집에서 나이 많은 남자 형제에게 「형, 같이 놀자!」라고 불렀어요. 무엇이 잘못되었나요?',ARRAY['K1-1-u4-X04']::text[],true,'{"seq":4,"concept":"K1-1-u4-C3","difficulty":3,"kind":"error","stem":"은솔이는 여자아이예요. 집에서 나이 많은 남자 형제에게 「형, 같이 놀자!」라고 불렀어요. 무엇이 잘못되었나요?","options":[{"t":"여자아이는 나이 많은 남자 형제를 「오빠」라고 불러야 해요","correct":true,"mis_target":"K1-1-u4-X04"},{"t":"「동생」이라고 불러야 해요","mis":"K1-1-u4-X04"},{"t":"고칠 곳이 없어요","mis":"K1-1-u4-X04"}],"explanation":["여자아이가 부르는 말은 「오빠」예요.","「형」은 남자아이가 부르는 말, 「동생」은 나보다 어린 사람이에요.","부르는 사람이 누구인지 먼저 살펴요."],"variant_rule":{"alt":[{"stem":"도윤이는 남자아이예요. 나이 많은 여자 형제에게 「언니, 같이 가!」라고 불렀어요. 무엇이 잘못되었나요?","options":[{"t":"남자아이는 나이 많은 여자 형제를 「누나」라고 불러야 해요","correct":true,"mis_target":"K1-1-u4-X04"},{"t":"「이모」라고 불러야 해요","mis":"K1-1-u4-X04"},{"t":"고칠 곳이 없어요","mis":"K1-1-u4-X04"}],"explanation":["남자아이가 부르는 말은 「누나」예요.","「언니」는 여자아이가 부르는 말이에요.","부르는 사람이 누구인지 먼저 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_challenge#5','kor',1,1,'u4','L03','g1_1_kor_u4_L03_challenge','lesson_challenge','K1-1-u4-C3',3,'ox','auto','「친구」와 「선생님」도 가족을 부르는 말이에요.',ARRAY['K1-1-u4-X05']::text[],false,'{"seq":5,"concept":"K1-1-u4-C3","difficulty":3,"kind":"ox","stem":"「친구」와 「선생님」도 가족을 부르는 말이에요.","answer":"X","reason_options":[{"t":"친구와 선생님은 가족 밖에서 만나는 사람이니까","correct":true},{"t":"자주 만나는 사람은 모두 가족이니까","mis":"K1-1-u4-X05"}],"mis":"K1-1-u4-X05","explanation":["가족을 부르는 말은 엄마·아빠·할머니·이모 같은 말이에요.","친구·선생님은 고마운 사람이지만 가족은 아니에요.","가족과 밖에서 만나는 사람을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_challenge#6','kor',1,1,'u4','L03','g1_1_kor_u4_L03_challenge','lesson_challenge','K1-1-u4-C3',3,'mc','auto','가족을 부르는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X05']::text[],true,'{"seq":6,"concept":"K1-1-u4-C3","difficulty":3,"kind":"mc","stem":"가족을 부르는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"이웃","correct":true},{"t":"고모","mis":"K1-1-u4-X05"},{"t":"할머니","mis":"K1-1-u4-X05"}],"explanation":["「이웃」은 가족을 부르는 낱말이 아니에요.","「고모」·「할머니」는 가족을 부르는 낱말이에요.","묶음마다 무엇을 모았는지 먼저 떠올리고 하나씩 견주어요."],"variant_rule":{"wcat":{"ask":"odd","cats":["family"],"mis":{"in":"X05","near":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_challenge#7','kor',1,1,'u4','L03','g1_1_kor_u4_L03_challenge','lesson_challenge','K1-1-u4-C2',3,'mc','auto','수수께끼예요. 「나는 얼굴 가운데에 있어요. 꽃 냄새를 맡아요.」 나는 누구일까요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":7,"concept":"K1-1-u4-C2","difficulty":3,"kind":"mc","stem":"수수께끼예요. 「나는 얼굴 가운데에 있어요. 꽃 냄새를 맡아요.」 나는 누구일까요?","options":[{"t":"코","correct":true},{"t":"입","mis":"K1-1-u4-X03"},{"t":"이마","mis":"K1-1-u4-X03"}],"explanation":["냄새를 맡는 곳은 「코」예요.","입은 먹고 말하는 곳, 이마는 얼굴 위쪽이에요.","설명을 끝까지 듣고 하는 일로 찾아요."],"variant_rule":{"alt":[{"stem":"수수께끼예요. 「나는 얼굴 양옆에 있어요. 새소리를 들어요.」 나는 누구일까요?","options":[{"t":"귀","correct":true},{"t":"눈","mis":"K1-1-u4-X03"},{"t":"어깨","mis":"K1-1-u4-X03"}],"explanation":["소리를 듣는 곳은 「귀」예요.","눈은 보는 곳, 어깨는 팔 위쪽이에요.","설명을 끝까지 듣고 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_challenge#8','kor',1,1,'u4','L03','g1_1_kor_u4_L03_challenge','lesson_challenge','K1-1-u4-C2',4,'mc','auto','몸의 곳과 하는 일이 맞지 않는 문장은 어느 것인가요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":8,"concept":"K1-1-u4-C2","difficulty":4,"kind":"mc","stem":"몸의 곳과 하는 일이 맞지 않는 문장은 어느 것인가요?","options":[{"t":"「귀로 그림을 봐요.」","correct":true},{"t":"「입으로 밥을 먹어요.」","mis":"K1-1-u4-X03"},{"t":"「발로 공을 차요.」","mis":"K1-1-u4-X03"}],"explanation":["그림은 눈으로 봐요 — 「눈으로 그림을 봐요.」","입으로 먹기·발로 차기는 맞는 짝이에요.","문장을 소리 내어 읽고 몸으로 해 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 몸의 곳과 하는 일이 맞지 않는 문장은 어느 것인가요?","options":[{"t":"「코로 노래를 들어요.」","correct":true},{"t":"「눈으로 책을 읽어요.」","mis":"K1-1-u4-X03"},{"t":"「손으로 연필을 잡아요.」","mis":"K1-1-u4-X03"}],"explanation":["노래는 귀로 들어요 — 「귀로 노래를 들어요.」","눈으로 읽기·손으로 잡기는 맞는 짝이에요.","몸으로 해 보며 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_challenge#9','kor',1,1,'u4','L03','g1_1_kor_u4_L03_challenge','lesson_challenge','K1-1-u4-C3',4,'mc','auto','도윤이는 남자아이이고, 누나가 한 명 있어요. 누나가 보기에 도윤이는 누구인가요?',ARRAY['K1-1-u4-X04']::text[],true,'{"seq":9,"concept":"K1-1-u4-C3","difficulty":4,"kind":"mc","stem":"도윤이는 남자아이이고, 누나가 한 명 있어요. 누나가 보기에 도윤이는 누구인가요?","options":[{"t":"동생","correct":true},{"t":"오빠","mis":"K1-1-u4-X04"},{"t":"형","mis":"K1-1-u4-X04"}],"explanation":["누나보다 어리니 도윤이는 누나의 「동생」이에요.","오빠·형은 나보다 나이 많은 남자 형제를 부르는 말이에요.","누가 누구를 부르는지 자리를 바꿔 생각해요."],"variant_rule":{"alt":[{"stem":"하린이는 여자아이이고, 이모가 한 명 있어요. 이모가 보기에 하린이의 엄마는 누구인가요?","options":[{"t":"언니나 여동생","correct":true},{"t":"고모","mis":"K1-1-u4-X04"},{"t":"딸","mis":"K1-1-u4-X04"}],"explanation":["이모는 엄마의 언니나 여동생이니, 이모에게 엄마는 언니나 여동생이에요.","고모는 아빠 쪽 사람이에요.","누가 누구를 부르는지 자리를 바꿔 생각해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L03_challenge#10','kor',1,1,'u4','L03','g1_1_kor_u4_L03_challenge','lesson_challenge','K1-1-u4-C2',4,'essay','teacher','몸을 나타내는 낱말 두 개를 골라, 그곳으로 하는 일을 넣어 문장으로 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u4-C2","difficulty":4,"kind":"essay","stem":"몸을 나타내는 낱말 두 개를 골라, 그곳으로 하는 일을 넣어 문장으로 말해 보세요.","answer_guide":{"answer":"예: 「눈으로 하늘을 봐요.」 「귀로 새소리를 들어요.」","scoring_points":["몸을 나타내는 낱말 두 개를 바르게 골랐는가","몸의 곳과 하는 일이 맞게 짝 지어졌는가","뜻이 통하는 문장으로 말했는가"]},"explanation":["몸 낱말 두 개.","몸과 하는 일의 짝.","문장으로 말하기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_basic#1','kor',1,1,'u4','L05','g1_1_kor_u4_L05_basic','lesson_basic','K1-1-u4-C4',1,'mc','auto','음식을 나타내는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X12']::text[],true,'{"seq":1,"concept":"K1-1-u4-C4","difficulty":1,"kind":"mc","stem":"음식을 나타내는 낱말은 어느 것인가요?","options":[{"t":"김밥","correct":true},{"t":"컵","mis":"K1-1-u4-X12"},{"t":"빵집","mis":"K1-1-u4-X12"}],"explanation":["「김밥」은 음식을 나타내는 낱말이에요.","「컵」·「빵집」은 음식을 나타내는 낱말이 아니에요.","낱말이 무엇을 나타내는지 떠올려 묶음을 정해요."],"variant_rule":{"wcat":{"ask":"pick","cats":["food"],"mis":{"near":"X12","other":"X12"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_basic#2','kor',1,1,'u4','L05','g1_1_kor_u4_L05_basic','lesson_basic','K1-1-u4-C4',1,'mc','auto','「얼음」에 어울리는 꾸며 주는 말은 어느 것인가요?',ARRAY['K1-1-u4-X09']::text[],true,'{"seq":2,"concept":"K1-1-u4-C4","difficulty":1,"kind":"mc","stem":"「얼음」에 어울리는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"차가운","correct":true},{"t":"뜨거운","mis":"K1-1-u4-X09"},{"t":"매운","mis":"K1-1-u4-X09"}],"explanation":["얼음은 「차가운 얼음」이에요.","뜨겁거나 매운 얼음은 없어요.","꾸민 모습을 머릿속에 그려 봐요."],"variant_rule":{"alt":[{"stem":"「솜사탕」에 어울리는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"달콤한","correct":true},{"t":"짠","mis":"K1-1-u4-X09"},{"t":"딱딱한","mis":"K1-1-u4-X09"}],"explanation":["솜사탕은 「달콤한 솜사탕」이에요.","짜거나 딱딱한 솜사탕은 없어요.","꾸민 모습을 그려 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_basic#3','kor',1,1,'u4','L05','g1_1_kor_u4_L05_basic','lesson_basic','K1-1-u4-C4',1,'mc','auto','꾸며 주는 말을 바르게 넣은 것은 어느 것인가요?',ARRAY['K1-1-u4-X08','K1-1-u4-X09']::text[],true,'{"seq":3,"concept":"K1-1-u4-C4","difficulty":1,"kind":"mc","stem":"꾸며 주는 말을 바르게 넣은 것은 어느 것인가요?","options":[{"t":"빨간 사과","correct":true},{"t":"사과 빨간","mis":"K1-1-u4-X08"},{"t":"뜨거운 사과","mis":"K1-1-u4-X09"}],"explanation":["꾸며 주는 말은 꾸밈 받는 낱말 앞에 와요 — 「빨간 사과」.","「사과 빨간」은 자리가 바뀌었고, 「뜨거운 사과」는 어울리지 않아요.","앞에 넣고 소리 내어 읽어 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 꾸며 주는 말을 바르게 넣은 것은 어느 것인가요?","options":[{"t":"긴 국수","correct":true},{"t":"국수 긴","mis":"K1-1-u4-X08"},{"t":"네모난 국수","mis":"K1-1-u4-X09"}],"explanation":["「긴 국수」 — 꾸며 주는 말은 앞에.","「국수 긴」은 자리가 바뀌었고, 네모난 국수는 어울리지 않아요.","앞에 넣고 읽어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_basic#4','kor',1,1,'u4','L05','g1_1_kor_u4_L05_basic','lesson_basic','K1-1-u4-C4',1,'ox','auto','「맛있는·예쁜」처럼 칭찬하는 말만 꾸며 주는 말이에요.',ARRAY['K1-1-u4-X07']::text[],false,'{"seq":4,"concept":"K1-1-u4-C4","difficulty":1,"kind":"ox","stem":"「맛있는·예쁜」처럼 칭찬하는 말만 꾸며 주는 말이에요.","answer":"X","reason_options":[{"t":"「작은·네모난·매운」처럼 모양·크기·맛을 자세히 하는 말도 꾸며 주는 말이니까","correct":true},{"t":"꾸며 주는 말은 좋은 말이어야 하니까","mis":"K1-1-u4-X07"}],"mis":"K1-1-u4-X07","explanation":["꾸며 주는 말은 낱말을 더 자세히 해 주는 말이에요.","칭찬이 아니어도 돼요 — 「작은 떡」도 꾸며 주는 말.","무엇을 자세히 해 주는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_basic#5','kor',1,1,'u4','L05','g1_1_kor_u4_L05_basic','lesson_basic','K1-1-u4-C4',2,'mc','auto','「(     ) 국수」 빈칸에 가장 어울리는 꾸며 주는 말은 어느 것인가요?',ARRAY['K1-1-u4-X09']::text[],true,'{"seq":5,"concept":"K1-1-u4-C4","difficulty":2,"kind":"mc","stem":"「(     ) 국수」 빈칸에 가장 어울리는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"긴","correct":true},{"t":"네모난","mis":"K1-1-u4-X09"},{"t":"딱딱한","mis":"K1-1-u4-X09"}],"explanation":["국수는 가늘고 길어요 — 「긴 국수」.","네모나거나 딱딱한 국수는 어울리지 않아요.","국수 모습을 떠올려요."],"variant_rule":{"alt":[{"stem":"「(     ) 두부」 빈칸에 가장 어울리는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"네모난","correct":true},{"t":"긴","mis":"K1-1-u4-X09"},{"t":"뾰족한","mis":"K1-1-u4-X09"}],"explanation":["두부는 네모 모양이에요 — 「네모난 두부」.","길거나 뾰족한 두부는 어울리지 않아요.","두부 모습을 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_basic#6','kor',1,1,'u4','L05','g1_1_kor_u4_L05_basic','lesson_basic','K1-1-u4-C4',2,'match','auto','음식과 어울리는 꾸며 주는 말을 이으세요.','{}'::text[],true,'{"seq":6,"concept":"K1-1-u4-C4","difficulty":2,"kind":"match","stem":"음식과 어울리는 꾸며 주는 말을 이으세요.","pairs":[{"l":"김치","r":"매운"},{"l":"사탕","r":"달콤한"},{"l":"국","r":"뜨거운"}],"mis":"K1-1-u4-X09","explanation":["매운 김치, 달콤한 사탕, 뜨거운 국.","맛과 온도를 떠올려요.","어울리는 짝을 찾아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 음식과 어울리는 꾸며 주는 말을 이으세요.","pairs":[{"l":"우유","r":"하얀"},{"l":"수박","r":"커다란"},{"l":"라면","r":"꼬불꼬불한"}],"explanation":["하얀 우유, 커다란 수박, 꼬불꼬불한 라면.","색깔·크기·모양을 떠올려요.","어울리는 짝을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_basic#7','kor',1,1,'u4','L05','g1_1_kor_u4_L05_basic','lesson_basic','K1-1-u4-C4',2,'mc','auto','「작은 김밥」에서 꾸며 주는 말은 어느 것인가요?',ARRAY['K1-1-u4-X08']::text[],true,'{"seq":7,"concept":"K1-1-u4-C4","difficulty":2,"kind":"mc","stem":"「작은 김밥」에서 꾸며 주는 말은 어느 것인가요?","options":[{"t":"작은","correct":true},{"t":"김밥","mis":"K1-1-u4-X08"},{"t":"작은 김밥","mis":"K1-1-u4-X08"}],"explanation":["「작은」이 김밥의 크기를 자세히 해 줘요.","「김밥」은 꾸밈을 받는 낱말이에요.","앞에서 꾸미는 말을 찾아요."],"variant_rule":{"alt":[{"stem":"「달콤한 감」에서 꾸며 주는 말은 어느 것인가요?","options":[{"t":"달콤한","correct":true},{"t":"감","mis":"K1-1-u4-X08"},{"t":"달콤한 감","mis":"K1-1-u4-X08"}],"explanation":["「달콤한」이 감의 맛을 자세히 해 줘요.","「감」은 꾸밈을 받는 낱말이에요.","앞에서 꾸미는 말을 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_basic#8','kor',1,1,'u4','L05','g1_1_kor_u4_L05_basic','lesson_basic','K1-1-u4-C4',2,'mc','auto','다음 가운데 꾸며 주는 말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X07']::text[],false,'{"seq":8,"concept":"K1-1-u4-C4","difficulty":2,"kind":"mc","stem":"다음 가운데 꾸며 주는 말이 아닌 것은 어느 것인가요?","options":[{"t":"피자","correct":true},{"t":"네모난","mis":"K1-1-u4-X07"},{"t":"매운","mis":"K1-1-u4-X07"}],"explanation":["「피자」는 음식을 나타내는 낱말이에요.","「네모난」·「매운」은 모양·맛을 자세히 하는 꾸며 주는 말이에요.","칭찬이 아니어도 꾸며 주는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_basic#9','kor',1,1,'u4','L05','g1_1_kor_u4_L05_basic','lesson_basic','K1-1-u4-C4',2,'mc','auto','음식을 나타내는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X12']::text[],true,'{"seq":9,"concept":"K1-1-u4-C4","difficulty":2,"kind":"mc","stem":"음식을 나타내는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"냄비","correct":true},{"t":"떡","mis":"K1-1-u4-X12"},{"t":"두부","mis":"K1-1-u4-X12"}],"explanation":["「냄비」는 음식을 나타내는 낱말이 아니에요.","「떡」·「두부」는 음식을 나타내는 낱말이에요.","묶음마다 무엇을 모았는지 먼저 떠올리고 하나씩 견주어요."],"variant_rule":{"wcat":{"ask":"odd","cats":["food"],"mis":{"in":"X12","near":"X12"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_basic#10','kor',1,1,'u4','L05','g1_1_kor_u4_L05_basic','lesson_basic','K1-1-u4-C4',3,'mc','auto','「피자 뜨거운 먹었어요.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K1-1-u4-X08']::text[],true,'{"seq":10,"concept":"K1-1-u4-C4","difficulty":3,"kind":"mc","stem":"「피자 뜨거운 먹었어요.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"「뜨거운 피자를 먹었어요.」","correct":true},{"t":"「피자를 뜨거운 먹었어요.」","mis":"K1-1-u4-X08"},{"t":"「피자 뜨거운을 먹었어요.」","mis":"K1-1-u4-X08"}],"explanation":["꾸며 주는 말 「뜨거운」은 「피자」 앞에 와요.","다른 두 문장은 꾸며 주는 말이 뒤에 있어요.","고친 문장을 소리 내어 읽어 봐요."],"variant_rule":{"alt":[{"stem":"「우유 차가운 마셨어요.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"「차가운 우유를 마셨어요.」","correct":true},{"t":"「우유를 차가운 마셨어요.」","mis":"K1-1-u4-X08"},{"t":"「우유 차가운을 마셨어요.」","mis":"K1-1-u4-X08"}],"explanation":["「차가운」은 「우유」 앞에 와요.","다른 두 문장은 꾸며 주는 말이 뒤에 있어요.","고친 문장을 읽어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_challenge#1','kor',1,1,'u4','L05','g1_1_kor_u4_L05_challenge','lesson_challenge','K1-1-u4-C4',2,'mc','auto','그림의 음식에 어울리지 않는 꾸며 주는 말은 어느 것인가요?',ARRAY['K1-1-u4-X09']::text[],true,'{"seq":1,"concept":"K1-1-u4-C4","difficulty":2,"kind":"mc","stem":"그림의 음식에 어울리지 않는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"뜨거운","correct":true},{"t":"차가운","mis":"K1-1-u4-X09"},{"t":"달콤한","mis":"K1-1-u4-X09"}],"explanation":["아이스크림은 뜨겁지 않아요.","「차가운」·「달콤한」은 아이스크림에 어울려요.","그림을 보고 모습과 맛을 떠올려요."],"asset":{"type":"scene","icon":"🍦","text":"아이스크림"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림의 음식에 어울리지 않는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"네모난","correct":true},{"t":"동그란","mis":"K1-1-u4-X09"},{"t":"빨간","mis":"K1-1-u4-X09"}],"explanation":["사과는 네모나지 않아요.","「동그란」·「빨간」은 사과에 어울려요.","그림을 보고 떠올려요."],"asset":{"type":"scene","icon":"🍎","text":"사과"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_challenge#2','kor',1,1,'u4','L05','g1_1_kor_u4_L05_challenge','lesson_challenge','K1-1-u4-C4',2,'mc','auto','음식 낱말 앞에 꾸며 주는 말을 넣으면 좋은 점은 무엇인가요?',ARRAY['K1-1-u4-X07']::text[],false,'{"seq":2,"concept":"K1-1-u4-C4","difficulty":2,"kind":"mc","stem":"음식 낱말 앞에 꾸며 주는 말을 넣으면 좋은 점은 무엇인가요?","options":[{"t":"음식의 맛·모양·크기를 더 자세히 알 수 있어요","correct":true},{"t":"문장이 짧아져요","mis":"K1-1-u4-X07"},{"t":"어떤 말이든 칭찬하는 말이 돼요","mis":"K1-1-u4-X07"}],"explanation":["「매운 김치」라고 하면 맛까지 알 수 있어요.","문장이 짧아지거나 칭찬이 되는 것은 아니에요.","꾸며 주는 말은 자세히 해 주는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
