INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_challenge#4','kor',1,1,'u4','L05','g1_1_kor_u4_L05_challenge','lesson_challenge','K1-1-u4-C4',3,'mc','auto','꾸며 주는 말 두 개를 넣어 음식을 자세히 말한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u4-X08','K1-1-u4-X09']::text[],true,'{"seq":4,"concept":"K1-1-u4-C4","difficulty":3,"kind":"mc","stem":"꾸며 주는 말 두 개를 넣어 음식을 자세히 말한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「동그랗고 달콤한 사탕」","correct":true},{"t":"「사탕 동그랗고 달콤한」","mis":"K1-1-u4-X08"},{"t":"「동그랗고 매운 사탕」","mis":"K1-1-u4-X09"}],"explanation":["모양(동그랗고)과 맛(달콤한)을 사탕 앞에 넣었어요.","뒤에 넣거나 매운 사탕은 알맞지 않아요.","두 개를 넣어도 모두 앞에 와요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 꾸며 주는 말 두 개를 넣어 음식을 자세히 말한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「길고 따뜻한 국수」","correct":true},{"t":"「국수 길고 따뜻한」","mis":"K1-1-u4-X08"},{"t":"「길고 네모난 국수」","mis":"K1-1-u4-X09"}],"explanation":["모양(길고)과 온도(따뜻한)를 국수 앞에 넣었어요.","뒤에 넣거나 네모난 국수는 알맞지 않아요.","두 개 모두 앞에 와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_challenge#5','kor',1,1,'u4','L05','g1_1_kor_u4_L05_challenge','lesson_challenge','K1-1-u4-C4',3,'ox','auto','「네모난 두부」의 「네모난」도 꾸며 주는 말이에요.',ARRAY['K1-1-u4-X07']::text[],false,'{"seq":5,"concept":"K1-1-u4-C4","difficulty":3,"kind":"ox","stem":"「네모난 두부」의 「네모난」도 꾸며 주는 말이에요.","answer":"O","reason_options":[{"t":"「네모난」이 두부의 모양을 자세히 해 주니까","correct":true},{"t":"칭찬하는 말만 꾸며 주는 말이니까","mis":"K1-1-u4-X07"}],"mis":"K1-1-u4-X07","explanation":["모양을 알려 주는 말도 꾸며 주는 말이에요.","칭찬이 아니어도 돼요.","무엇을 자세히 해 주는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_challenge#6','kor',1,1,'u4','L05','g1_1_kor_u4_L05_challenge','lesson_challenge','K1-1-u4-C4',3,'mc','auto','하린이의 글에서 「국수」를 꾸며 주는 말을 모두 고른 것은 어느 것인가요?',ARRAY['K1-1-u4-X06','K1-1-u4-X13']::text[],false,'{"seq":6,"concept":"K1-1-u4-C4","difficulty":3,"kind":"mc","stem":"하린이의 글에서 「국수」를 꾸며 주는 말을 모두 고른 것은 어느 것인가요?","options":[{"t":"「길고」 · 「따뜻한」","correct":true},{"t":"「따뜻한」 · 「시원한」","mis":"K1-1-u4-X06"},{"t":"「길고」만","mis":"K1-1-u4-X13"}],"explanation":["「길고 따뜻한 국수」 — 두 말이 국수를 꾸며요.","「시원한」은 수박을 꾸며요.","글을 끝까지 읽고 무엇을 꾸미는지 살펴요."],"asset":{"type":"passage","lines":["저녁에 할머니께서 국수를 만들어 주셨어요.","길고 따뜻한 국수였어요.","나는 시원한 수박도 먹었어요."]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_challenge#7','kor',1,1,'u4','L05','g1_1_kor_u4_L05_challenge','lesson_challenge','K1-1-u4-C4',3,'mc','auto','음식을 나타내는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X12']::text[],true,'{"seq":7,"concept":"K1-1-u4-C4","difficulty":3,"kind":"mc","stem":"음식을 나타내는 낱말은 어느 것인가요?","options":[{"t":"라면","correct":true},{"t":"젓가락","mis":"K1-1-u4-X12"},{"t":"은행","mis":"K1-1-u4-X12"}],"explanation":["「라면」은 음식을 나타내는 낱말이에요.","「젓가락」·「은행」은 음식을 나타내는 낱말이 아니에요.","낱말이 무엇을 나타내는지 떠올려 묶음을 정해요."],"variant_rule":{"wcat":{"ask":"pick","cats":["food"],"mis":{"near":"X12","other":"X12"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_challenge#8','kor',1,1,'u4','L05','g1_1_kor_u4_L05_challenge','lesson_challenge','K1-1-u4-C4',4,'mc','auto','같은 꾸며 주는 말 「뜨거운」이 어울리는 음식끼리 모은 것은 어느 것인가요?',ARRAY['K1-1-u4-X09']::text[],true,'{"seq":8,"concept":"K1-1-u4-C4","difficulty":4,"kind":"mc","stem":"같은 꾸며 주는 말 「뜨거운」이 어울리는 음식끼리 모은 것은 어느 것인가요?","options":[{"t":"국 · 라면","correct":true},{"t":"아이스크림 · 라면","mis":"K1-1-u4-X09"},{"t":"수박 · 국","mis":"K1-1-u4-X09"}],"explanation":["국과 라면은 뜨겁게 먹어요.","아이스크림·수박은 차갑게 먹어요.","음식마다 꾸민 모습을 그려 봐요."],"variant_rule":{"alt":[{"stem":"같은 꾸며 주는 말 「달콤한」이 어울리는 음식끼리 모은 것은 어느 것인가요?","options":[{"t":"사탕 · 꿀","correct":true},{"t":"김치 · 꿀","mis":"K1-1-u4-X09"},{"t":"사탕 · 고추","mis":"K1-1-u4-X09"}],"explanation":["사탕과 꿀은 달아요.","김치·고추는 매워요.","음식마다 맛을 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_challenge#9','kor',1,1,'u4','L05','g1_1_kor_u4_L05_challenge','lesson_challenge','K1-1-u4-C4',4,'mc','auto','식당 차림표에 「매운 떡볶이」와 「순한 떡볶이」가 있어요. 매운 것을 못 먹는 동생에게 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u4-X06','K1-1-u4-X07']::text[],false,'{"seq":9,"concept":"K1-1-u4-C4","difficulty":4,"kind":"mc","stem":"식당 차림표에 「매운 떡볶이」와 「순한 떡볶이」가 있어요. 매운 것을 못 먹는 동생에게 알맞은 것은 어느 것인가요?","options":[{"t":"순한 떡볶이","correct":true},{"t":"매운 떡볶이","mis":"K1-1-u4-X06"},{"t":"둘 다 같은 떡볶이라 아무거나","mis":"K1-1-u4-X07"}],"explanation":["「순한」은 맵지 않다는 뜻이에요.","「매운」을 끝까지 읽지 않으면 잘못 골라요.","꾸며 주는 말이 달라지면 음식도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L05_challenge#10','kor',1,1,'u4','L05','g1_1_kor_u4_L05_challenge','lesson_challenge','K1-1-u4-C4',4,'essay','teacher','좋아하는 음식 하나를 골라, 칭찬하는 말이 아닌 꾸며 주는 말을 하나 이상 넣어 소개해 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u4-C4","difficulty":4,"kind":"essay","stem":"좋아하는 음식 하나를 골라, 칭찬하는 말이 아닌 꾸며 주는 말을 하나 이상 넣어 소개해 보세요.","answer_guide":{"answer":"예: 「나는 동그랗고 하얀 떡을 좋아해요.」","scoring_points":["음식을 나타내는 낱말을 넣었는가","칭찬이 아닌 꾸며 주는 말(모양·색깔·맛)을 넣었는가","꾸며 주는 말을 음식 낱말 앞에 넣었는가"]},"explanation":["음식 낱말.","모양·색깔·맛을 자세히.","꾸며 주는 말은 앞에."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_basic#1','kor',1,1,'u4','L07','g1_1_kor_u4_L07_basic','lesson_basic','K1-1-u4-C5',1,'mc','auto','학교에서 볼 수 있는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X11']::text[],true,'{"seq":1,"concept":"K1-1-u4-C5","difficulty":1,"kind":"mc","stem":"학교에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"칠판","correct":true},{"t":"침대","mis":"K1-1-u4-X11"},{"t":"우체국","mis":"K1-1-u4-X11"}],"explanation":["「칠판」은 학교에서 볼 수 있는 낱말이에요.","「침대」·「우체국」은 학교에서 볼 수 있는 낱말이 아니에요.","낱말이 무엇을 나타내는지 떠올려 묶음을 정해요."],"variant_rule":{"wcat":{"ask":"pick","cats":["school"],"mis":{"near":"X11","other":"X11"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_basic#2','kor',1,1,'u4','L07','g1_1_kor_u4_L07_basic','lesson_basic','K1-1-u4-C5',1,'mc','auto','「빵집」에서 하는 일은 어느 것인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":2,"concept":"K1-1-u4-C5","difficulty":1,"kind":"mc","stem":"「빵집」에서 하는 일은 어느 것인가요?","options":[{"t":"빵을 사요","correct":true},{"t":"편지를 보내요","mis":"K1-1-u4-X10"},{"t":"돈을 맡겨요","mis":"K1-1-u4-X10"}],"explanation":["「빵집」에서는 빵을 사요.","「편지를 보내요」·「돈을 맡겨요」는 다른 곳에서 하는 일이에요.","장소 이름과 그곳에서 하는 일을 짝 지어 떠올려요."],"variant_rule":{"wlink":{"ask":"place","mis":{"link":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_basic#3','kor',1,1,'u4','L07','g1_1_kor_u4_L07_basic','lesson_basic','K1-1-u4-C5',1,'mc','auto','그림의 차가 머무는 곳은 어디인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":3,"concept":"K1-1-u4-C5","difficulty":1,"kind":"mc","stem":"그림의 차가 머무는 곳은 어디인가요?","options":[{"t":"소방서","correct":true},{"t":"은행","mis":"K1-1-u4-X10"},{"t":"꽃집","mis":"K1-1-u4-X10"}],"explanation":["소방차는 「소방서」에 있어요.","은행·꽃집에는 소방차가 없어요.","그림을 보고 어울리는 곳을 떠올려요."],"asset":{"type":"scene","icon":"🚒"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림의 차가 머무는 곳은 어디인가요?","options":[{"t":"경찰서","correct":true},{"t":"빵집","mis":"K1-1-u4-X10"},{"t":"미용실","mis":"K1-1-u4-X10"}],"explanation":["경찰차는 「경찰서」에 있어요.","빵집·미용실에는 경찰차가 없어요.","그림을 보고 떠올려요."],"asset":{"type":"scene","icon":"🚓"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_basic#4','kor',1,1,'u4','L07','g1_1_kor_u4_L07_basic','lesson_basic','K1-1-u4-C6',1,'ox','auto','「도서관」은 학교에도 있고 동네에도 있을 수 있어요.',ARRAY['K1-1-u4-X11']::text[],true,'{"seq":4,"concept":"K1-1-u4-C6","difficulty":1,"kind":"ox","stem":"「도서관」은 학교에도 있고 동네에도 있을 수 있어요.","answer":"O","reason_options":[{"t":"학교 안 도서관도, 동네 도서관도 있으니까","correct":true},{"t":"낱말은 한 묶음에만 들어가야 하니까","mis":"K1-1-u4-X11"}],"mis":"K1-1-u4-X11","explanation":["도서관은 학교에도 동네에도 있어요.","둘 다에 넣어도 돼요.","「둘 다」 칸을 만들어 보세요."],"variant_rule":{"alt":[{"stem":"「화장실」은 학교에도 있고 동네 가게나 공원에도 있을 수 있어요.","answer":"O","reason_options":[{"t":"학교에도 공원에도 화장실이 있으니까","correct":true},{"t":"낱말은 한 묶음에만 들어가야 하니까","mis":"K1-1-u4-X11"}],"explanation":["화장실은 여러 곳에 있어요.","둘 다에 넣어도 돼요.","「둘 다」 칸을 만들어 보세요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_basic#5','kor',1,1,'u4','L07','g1_1_kor_u4_L07_basic','lesson_basic','K1-1-u4-C5',2,'mc','auto','「편지를 보내요」 — 이 일을 하는 곳은 어디인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":5,"concept":"K1-1-u4-C5","difficulty":2,"kind":"mc","stem":"「편지를 보내요」 — 이 일을 하는 곳은 어디인가요?","options":[{"t":"우체국","correct":true},{"t":"꽃집","mis":"K1-1-u4-X10"},{"t":"빵집","mis":"K1-1-u4-X10"}],"explanation":["「우체국」에서 편지를 보내요.","「꽃집」·「빵집」은 하는 일이 달라요.","그 일을 하러 어디에 가는지 떠올려요."],"variant_rule":{"wlink":{"ask":"placer","mis":{"link":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_basic#6','kor',1,1,'u4','L07','g1_1_kor_u4_L07_basic','lesson_basic','K1-1-u4-C5',2,'mc','auto','동네에서 볼 수 있는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X11']::text[],true,'{"seq":6,"concept":"K1-1-u4-C5","difficulty":2,"kind":"mc","stem":"동네에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"약국","correct":true},{"t":"거실","mis":"K1-1-u4-X11"},{"t":"교실","mis":"K1-1-u4-X11"}],"explanation":["「약국」은 동네에서 볼 수 있는 낱말이에요.","「거실」·「교실」은 동네에서 볼 수 있는 낱말이 아니에요.","낱말이 무엇을 나타내는지 떠올려 묶음을 정해요."],"variant_rule":{"wcat":{"ask":"pick","cats":["town"],"mis":{"near":"X11","other":"X11"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_basic#7','kor',1,1,'u4','L07','g1_1_kor_u4_L07_basic','lesson_basic','K1-1-u4-C5',2,'match','auto','장소와 그곳에서 하는 일을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"K1-1-u4-C5","difficulty":2,"kind":"match","stem":"장소와 그곳에서 하는 일을 이으세요.","pairs":[{"l":"은행","r":"돈을 맡겨요"},{"l":"꽃집","r":"꽃을 사요"},{"l":"급식실","r":"점심을 먹어요"}],"mis":"K1-1-u4-X10","explanation":["은행-돈을 맡겨요, 꽃집-꽃을 사요, 급식실-점심을 먹어요.","「그곳에 가면 무엇을 하지?」 떠올려요.","장소와 일은 짝이 있어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 장소와 그곳에서 하는 일을 이으세요.","pairs":[{"l":"우체국","r":"편지를 보내요"},{"l":"도서관","r":"책을 빌려요"},{"l":"빵집","r":"빵을 사요"}],"explanation":["우체국-편지, 도서관-책, 빵집-빵.","「그곳에 가면 무엇을 하지?」 떠올려요.","장소와 일은 짝이 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_basic#8','kor',1,1,'u4','L07','g1_1_kor_u4_L07_basic','lesson_basic','K1-1-u4-C6',2,'mc','auto','학교에서 볼 수 있는 낱말끼리 모은 것은 어느 것인가요?',ARRAY['K1-1-u4-X11','K1-1-u4-X12']::text[],true,'{"seq":8,"concept":"K1-1-u4-C6","difficulty":2,"kind":"mc","stem":"학교에서 볼 수 있는 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"칠판 · 교실 · 사물함","correct":true},{"t":"칠판 · 은행 · 사물함","mis":"K1-1-u4-X11"},{"t":"교실 · 침대 · 교과서","mis":"K1-1-u4-X12"}],"explanation":["칠판·교실·사물함은 모두 학교에 있어요.","은행은 동네에, 침대는 집에 있어요.","묶음 이름을 먼저 말하고 하나씩 견줘요."],"variant_rule":{"alt":[{"stem":"동네에서 볼 수 있는 낱말끼리 모은 것은 어느 것인가요?","options":[{"t":"빵집 · 시장 · 미용실","correct":true},{"t":"빵집 · 교탁 · 미용실","mis":"K1-1-u4-X11"},{"t":"시장 · 부엌 · 은행","mis":"K1-1-u4-X11"}],"explanation":["빵집·시장·미용실은 모두 동네에 있어요.","교탁은 교실에, 부엌은 우리 집 안에 있어요.","묶음 이름을 먼저 말해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_basic#9','kor',1,1,'u4','L07','g1_1_kor_u4_L07_basic','lesson_basic','K1-1-u4-C6',2,'mc','auto','학교에서 볼 수 있는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X11']::text[],true,'{"seq":9,"concept":"K1-1-u4-C6","difficulty":2,"kind":"mc","stem":"학교에서 볼 수 있는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"소파","correct":true},{"t":"교문","mis":"K1-1-u4-X11"},{"t":"강당","mis":"K1-1-u4-X11"}],"explanation":["「소파」는 학교에서 볼 수 있는 낱말이 아니에요.","「교문」·「강당」은 학교에서 볼 수 있는 낱말이에요.","묶음마다 무엇을 모았는지 먼저 떠올리고 하나씩 견주어요."],"variant_rule":{"wcat":{"ask":"odd","cats":["school"],"mis":{"in":"X11","near":"X11"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_basic#10','kor',1,1,'u4','L07','g1_1_kor_u4_L07_basic','lesson_basic','K1-1-u4-C6',3,'mc','auto','「병원 · 약국 · 치과」를 한 묶음으로 묶는 이름으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u4-X12','K1-1-u4-X11']::text[],true,'{"seq":10,"concept":"K1-1-u4-C6","difficulty":3,"kind":"mc","stem":"「병원 · 약국 · 치과」를 한 묶음으로 묶는 이름으로 알맞은 것은 어느 것인가요?","options":[{"t":"아플 때 가는 곳","correct":true},{"t":"먹을 것을 사는 곳","mis":"K1-1-u4-X12"},{"t":"학교 안에 있는 곳","mis":"K1-1-u4-X11"}],"explanation":["세 곳 모두 아프거나 다쳤을 때 가요.","먹을 것을 사거나 학교 안에 있는 곳이 아니에요.","공통점을 찾아 묶음 이름을 지어요."],"variant_rule":{"alt":[{"stem":"「빵집 · 꽃집 · 시장」을 한 묶음으로 묶는 이름으로 알맞은 것은 어느 것인가요?","options":[{"t":"물건을 사는 곳","correct":true},{"t":"아플 때 가는 곳","mis":"K1-1-u4-X12"},{"t":"학교 안에 있는 곳","mis":"K1-1-u4-X11"}],"explanation":["세 곳 모두 물건을 사러 가요.","아플 때 가거나 학교 안에 있는 곳이 아니에요.","공통점을 찾아 이름을 지어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_challenge#1','kor',1,1,'u4','L07','g1_1_kor_u4_L07_challenge','lesson_challenge','K1-1-u4-C5',2,'mc','auto','「은행」에서 하는 일은 어느 것인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":1,"concept":"K1-1-u4-C5","difficulty":2,"kind":"mc","stem":"「은행」에서 하는 일은 어느 것인가요?","options":[{"t":"돈을 맡겨요","correct":true},{"t":"꽃을 사요","mis":"K1-1-u4-X10"},{"t":"불을 끄러 출동해요","mis":"K1-1-u4-X10"}],"explanation":["「은행」에서는 돈을 맡겨요.","「꽃을 사요」·「불을 끄러 출동해요」는 다른 곳에서 하는 일이에요.","장소 이름과 그곳에서 하는 일을 짝 지어 떠올려요."],"variant_rule":{"wlink":{"ask":"place","mis":{"link":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_challenge#2','kor',1,1,'u4','L07','g1_1_kor_u4_L07_challenge','lesson_challenge','K1-1-u4-C6',2,'mc','auto','「동네」에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K1-1-u4-X11']::text[],false,'{"seq":2,"concept":"K1-1-u4-C6","difficulty":2,"kind":"mc","stem":"「동네」에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"집 둘레의 가게·길·공원도 모두 동네예요","correct":true},{"t":"동네는 우리 집 안만 말해요","mis":"K1-1-u4-X11"},{"t":"동네에는 가게가 하나도 없어요","mis":"K1-1-u4-X11"}],"explanation":["동네는 우리 집과 그 둘레를 모두 말해요.","우리 집 안만 동네인 것이 아니에요.","집을 나서면 보이는 곳을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_challenge#3','kor',1,1,'u4','L07','g1_1_kor_u4_L07_challenge','lesson_challenge','K1-1-u4-C6',3,'error','auto','시우가 학교에서 볼 수 있는 낱말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_challenge#4','kor',1,1,'u4','L07','g1_1_kor_u4_L07_challenge','lesson_challenge','K1-1-u4-C6',3,'mc','auto','동네에서 볼 수 있는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X11']::text[],true,'{"seq":4,"concept":"K1-1-u4-C6","difficulty":3,"kind":"mc","stem":"동네에서 볼 수 있는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"안방","correct":true},{"t":"꽃집","mis":"K1-1-u4-X11"},{"t":"시장","mis":"K1-1-u4-X11"}],"explanation":["「안방」은 동네에서 볼 수 있는 낱말이 아니에요.","「꽃집」·「시장」은 동네에서 볼 수 있는 낱말이에요.","묶음마다 무엇을 모았는지 먼저 떠올리고 하나씩 견주어요."],"variant_rule":{"wcat":{"ask":"odd","cats":["town"],"mis":{"in":"X11","near":"X11"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_challenge#5','kor',1,1,'u4','L07','g1_1_kor_u4_L07_challenge','lesson_challenge','K1-1-u4-C5',3,'mc','auto','수수께끼예요. 「책을 빌려 조용히 읽을 수 있어요. 학교에도 있고 동네에도 있어요.」 어디일까요?',ARRAY['K1-1-u4-X06','K1-1-u4-X11']::text[],true,'{"seq":5,"concept":"K1-1-u4-C5","difficulty":3,"kind":"mc","stem":"수수께끼예요. 「책을 빌려 조용히 읽을 수 있어요. 학교에도 있고 동네에도 있어요.」 어디일까요?","options":[{"t":"도서관","correct":true},{"t":"서점","mis":"K1-1-u4-X06"},{"t":"교실","mis":"K1-1-u4-X11"}],"explanation":["책을 빌리는 곳은 「도서관」이에요.","서점은 책을 사는 곳, 교실은 동네에 없어요.","설명을 끝까지 듣고 찾아요."],"variant_rule":{"alt":[{"stem":"수수께끼예요. 「아픈 이를 치료해 줘요. 이를 닦는 방법도 알려 줘요.」 어디일까요?","options":[{"t":"치과","correct":true},{"t":"병원","mis":"K1-1-u4-X06"},{"t":"약국","mis":"K1-1-u4-X06"}],"explanation":["이를 치료하는 곳은 「치과」예요.","병원·약국과 비슷하지만 이를 보는 곳은 치과예요.","설명을 끝까지 듣고 찾아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_challenge#6','kor',1,1,'u4','L07','g1_1_kor_u4_L07_challenge','lesson_challenge','K1-1-u4-C6',3,'mc','auto','「학교 · 동네 · 둘 다」 표를 만들었어요. 「도서관」은 어느 칸에 넣으면 좋을까요?',ARRAY['K1-1-u4-X11']::text[],true,'{"seq":6,"concept":"K1-1-u4-C6","difficulty":3,"kind":"mc","stem":"「학교 · 동네 · 둘 다」 표를 만들었어요. 「도서관」은 어느 칸에 넣으면 좋을까요?","options":[{"t":"둘 다","correct":true},{"t":"학교만","mis":"K1-1-u4-X11"},{"t":"동네만","mis":"K1-1-u4-X11"}],"explanation":["도서관은 학교에도 동네에도 있어요.","한 칸에만 넣으면 다른 곳을 놓쳐요.","둘 다 되는 낱말도 있어요."],"variant_rule":{"alt":[{"stem":"「학교 · 동네 · 둘 다」 표를 만들었어요. 「교탁」은 어느 칸에 넣으면 좋을까요?","options":[{"t":"학교만","correct":true},{"t":"동네만","mis":"K1-1-u4-X11"},{"t":"둘 다","mis":"K1-1-u4-X11"}],"explanation":["교탁은 교실 앞에 있는 선생님 책상이에요.","동네 가게에는 교탁이 없어요.","어디에서 볼 수 있는지 떠올려요."]},{"stem":"「학교 · 동네 · 둘 다」 표를 만들었어요. 「미용실」은 어느 칸에 넣으면 좋을까요?","options":[{"t":"동네만","correct":true},{"t":"학교만","mis":"K1-1-u4-X11"},{"t":"둘 다","mis":"K1-1-u4-X11"}],"explanation":["미용실은 동네에서 머리를 자르는 곳이에요.","학교에는 미용실이 없어요.","어디에서 볼 수 있는지 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_challenge#7','kor',1,1,'u4','L07','g1_1_kor_u4_L07_challenge','lesson_challenge','K1-1-u4-C5',3,'mc','auto','「불을 끄러 출동해요」 — 이 일을 하는 곳은 어디인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":7,"concept":"K1-1-u4-C5","difficulty":3,"kind":"mc","stem":"「불을 끄러 출동해요」 — 이 일을 하는 곳은 어디인가요?","options":[{"t":"소방서","correct":true},{"t":"우체국","mis":"K1-1-u4-X10"},{"t":"은행","mis":"K1-1-u4-X10"}],"explanation":["「소방서」에서 불을 끄러 출동해요.","「우체국」·「은행」은 하는 일이 달라요.","그 일을 하러 어디에 가는지 떠올려요."],"variant_rule":{"wlink":{"ask":"placer","mis":{"link":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_challenge#8','kor',1,1,'u4','L07','g1_1_kor_u4_L07_challenge','lesson_challenge','K1-1-u4-C5',4,'mc','auto','「우체국에서 빵을 사요.」를 장소와 하는 일이 맞게 고친 것은 어느 것인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":8,"concept":"K1-1-u4-C5","difficulty":4,"kind":"mc","stem":"「우체국에서 빵을 사요.」를 장소와 하는 일이 맞게 고친 것은 어느 것인가요?","options":[{"t":"「빵집에서 빵을 사요.」","correct":true},{"t":"「우체국에서 꽃을 사요.」","mis":"K1-1-u4-X10"},{"t":"「빵집에서 편지를 보내요.」","mis":"K1-1-u4-X10"}],"explanation":["빵은 빵집에서 사요.","다른 두 문장도 장소와 하는 일이 어긋나요.","고친 뒤 「정말 그곳에서 할까?」 확인해요."],"variant_rule":{"alt":[{"stem":"「은행에서 꽃을 사요.」를 장소와 하는 일이 맞게 고친 것은 어느 것인가요?","options":[{"t":"「꽃집에서 꽃을 사요.」","correct":true},{"t":"「은행에서 빵을 사요.」","mis":"K1-1-u4-X10"},{"t":"「꽃집에서 돈을 맡겨요.」","mis":"K1-1-u4-X10"}],"explanation":["꽃은 꽃집에서 사요.","다른 두 문장도 어긋나요.","고친 뒤 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_challenge#9','kor',1,1,'u4','L07','g1_1_kor_u4_L07_challenge','lesson_challenge','K1-1-u4-C6',4,'mc','auto','「빵집 · 급식실 · 꽃집 · 교실」을 두 묶음으로 똑같이 나누려고 해요. 알맞은 기준은 어느 것인가요?',ARRAY['K1-1-u4-X12']::text[],false,'{"seq":9,"concept":"K1-1-u4-C6","difficulty":4,"kind":"mc","stem":"「빵집 · 급식실 · 꽃집 · 교실」을 두 묶음으로 똑같이 나누려고 해요. 알맞은 기준은 어느 것인가요?","options":[{"t":"학교 안에 있는 곳과 동네에 있는 곳","correct":true},{"t":"받침이 있는 낱말과 없는 낱말","mis":"K1-1-u4-X12"},{"t":"두 글자 낱말과 세 글자 낱말","mis":"K1-1-u4-X12"}],"explanation":["급식실·교실은 학교, 빵집·꽃집은 동네 — 둘씩 나뉘어요.","네 낱말 모두 받침이 있고, 세 글자는 「급식실」 하나뿐이라 둘씩 안 나뉘어요.","기준을 세운 뒤 정말 나뉘는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L07_challenge#10','kor',1,1,'u4','L07','g1_1_kor_u4_L07_challenge','lesson_challenge','K1-1-u4-C5',4,'essay','teacher','동네에서 볼 수 있는 곳 두 곳을 골라, 그곳에서 하는 일을 넣어 문장으로 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u4-C5","difficulty":4,"kind":"essay","stem":"동네에서 볼 수 있는 곳 두 곳을 골라, 그곳에서 하는 일을 넣어 문장으로 말해 보세요.","answer_guide":{"answer":"예: 「우체국에서 편지를 보내요.」 「꽃집에서 꽃을 사요.」","scoring_points":["동네에서 볼 수 있는 곳을 두 곳 골랐는가","장소와 하는 일이 맞게 짝 지어졌는가","뜻이 통하는 문장으로 말했는가"]},"explanation":["동네 장소 두 곳.","장소와 하는 일의 짝.","문장으로 말하기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_basic#1','kor',1,1,'u4','L09','g1_1_kor_u4_L09_basic','lesson_basic','K1-1-u4-C7',1,'mc','auto','도윤이가 집을 나서면 먼저 보이는 곳은 어디인가요?',ARRAY['K1-1-u4-X13']::text[],false,'{"seq":1,"concept":"K1-1-u4-C7","difficulty":1,"kind":"mc","stem":"도윤이가 집을 나서면 먼저 보이는 곳은 어디인가요?","options":[{"t":"꽃집","correct":true},{"t":"빵집","mis":"K1-1-u4-X13"},{"t":"치과","mis":"K1-1-u4-X13"}],"explanation":["집을 나서면 먼저 「꽃집」이 보여요.","빵집·치과는 그다음에 나와요.","이야기를 처음부터 차례대로 떠올려요."],"asset":{"type":"passage","lines":["도윤이는 아침마다 걸어서 학교에 가요.","집을 나서면 먼저 꽃집이 보여요. 꽃집 앞에는 노란 꽃이 가득해요.","신호등이 초록불로 바뀌면 손을 들고 길을 건너요.","길 건너 빵집에서 고소한 냄새가 나요.","치과 옆 정류장에는 버스가 멈춰 서요.","눈이 온 날에는 길에 발자국이 콕콕 찍혀요."],"title":"학교 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_basic#2','kor',1,1,'u4','L09','g1_1_kor_u4_L09_basic','lesson_basic','K1-1-u4-C7',1,'mc','auto','도윤이는 신호등이 무슨 불로 바뀌면 길을 건너나요?',ARRAY['K1-1-u4-X14','K1-1-u4-X13']::text[],false,'{"seq":2,"concept":"K1-1-u4-C7","difficulty":1,"kind":"mc","stem":"도윤이는 신호등이 무슨 불로 바뀌면 길을 건너나요?","options":[{"t":"초록불","correct":true},{"t":"빨간불","mis":"K1-1-u4-X14"},{"t":"노란불","mis":"K1-1-u4-X13"}],"explanation":["초록불일 때 손을 들고 건너요.","빨간불에는 멈춰야 하고, 노란불은 이야기에 나오지 않았어요.","이야기에 나온 말을 그대로 찾아요."],"asset":{"type":"passage","lines":["도윤이는 아침마다 걸어서 학교에 가요.","집을 나서면 먼저 꽃집이 보여요. 꽃집 앞에는 노란 꽃이 가득해요.","신호등이 초록불로 바뀌면 손을 들고 길을 건너요.","길 건너 빵집에서 고소한 냄새가 나요.","치과 옆 정류장에는 버스가 멈춰 서요.","눈이 온 날에는 길에 발자국이 콕콕 찍혀요."],"title":"학교 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_basic#3','kor',1,1,'u4','L09','g1_1_kor_u4_L09_basic','lesson_basic','K1-1-u4-C7',1,'mc','auto','「학교 가는 길」 이야기에 나오지 않은 곳은 어디인가요?',ARRAY['K1-1-u4-X13']::text[],true,'{"seq":3,"concept":"K1-1-u4-C7","difficulty":1,"kind":"mc","stem":"「학교 가는 길」 이야기에 나오지 않은 곳은 어디인가요?","options":[{"t":"은행","correct":true},{"t":"꽃집","mis":"K1-1-u4-X13"},{"t":"빵집","mis":"K1-1-u4-X13"}],"explanation":["은행은 이야기에 나오지 않았어요.","꽃집·빵집은 이야기에 나왔어요.","나올 때마다 손가락을 꼽으며 들어요."],"asset":{"type":"passage","lines":["도윤이는 아침마다 걸어서 학교에 가요.","집을 나서면 먼저 꽃집이 보여요. 꽃집 앞에는 노란 꽃이 가득해요.","신호등이 초록불로 바뀌면 손을 들고 길을 건너요.","길 건너 빵집에서 고소한 냄새가 나요.","치과 옆 정류장에는 버스가 멈춰 서요.","눈이 온 날에는 길에 발자국이 콕콕 찍혀요."],"title":"학교 가는 길"},"variant_rule":{"alt":[{"stem":"「학교 가는 길」 이야기에 나오지 않은 것은 무엇인가요?","options":[{"t":"소방차","correct":true},{"t":"버스","mis":"K1-1-u4-X13"},{"t":"신호등","mis":"K1-1-u4-X13"}],"explanation":["소방차는 이야기에 나오지 않았어요.","버스·신호등은 이야기에 나왔어요.","나올 때마다 손가락을 꼽아요."],"asset":{"type":"passage","lines":["도윤이는 아침마다 걸어서 학교에 가요.","집을 나서면 먼저 꽃집이 보여요. 꽃집 앞에는 노란 꽃이 가득해요.","신호등이 초록불로 바뀌면 손을 들고 길을 건너요.","길 건너 빵집에서 고소한 냄새가 나요.","치과 옆 정류장에는 버스가 멈춰 서요.","눈이 온 날에는 길에 발자국이 콕콕 찍혀요."],"title":"학교 가는 길"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_basic#4','kor',1,1,'u4','L09','g1_1_kor_u4_L09_basic','lesson_basic','K1-1-u4-C7',1,'ox','auto','「길 건너 빵집에서 고소한 냄새가 나요.」는 이야기에 나온 내용이에요.',ARRAY['K1-1-u4-X13']::text[],true,'{"seq":4,"concept":"K1-1-u4-C7","difficulty":1,"kind":"ox","stem":"「길 건너 빵집에서 고소한 냄새가 나요.」는 이야기에 나온 내용이에요.","answer":"O","reason_options":[{"t":"이야기 넷째 줄에 빵집과 고소한 냄새가 나오니까","correct":true},{"t":"빵집은 이야기에 나오지 않았으니까","mis":"K1-1-u4-X13"}],"mis":"K1-1-u4-X13","explanation":["빵집에서 고소한 냄새가 났어요.","이야기를 끝까지 들으면 찾을 수 있어요.","들은 내용과 견주어 봐요."],"asset":{"type":"passage","lines":["도윤이는 아침마다 걸어서 학교에 가요.","집을 나서면 먼저 꽃집이 보여요. 꽃집 앞에는 노란 꽃이 가득해요.","신호등이 초록불로 바뀌면 손을 들고 길을 건너요.","길 건너 빵집에서 고소한 냄새가 나요.","치과 옆 정류장에는 버스가 멈춰 서요.","눈이 온 날에는 길에 발자국이 콕콕 찍혀요."],"title":"학교 가는 길"},"variant_rule":{"alt":[{"stem":"「치과 옆 정류장에 기차가 멈춰 서요.」는 이야기에 나온 내용이에요.","answer":"X","reason_options":[{"t":"정류장에 멈추는 것은 기차가 아니라 버스이니까","correct":true},{"t":"정류장은 이야기에 나오지 않았으니까","mis":"K1-1-u4-X13"}],"explanation":["이야기에서는 버스가 멈춰 서요.","정류장은 이야기에 나왔어요.","낱말 하나까지 견주어 봐요."],"asset":{"type":"passage","lines":["도윤이는 아침마다 걸어서 학교에 가요.","집을 나서면 먼저 꽃집이 보여요. 꽃집 앞에는 노란 꽃이 가득해요.","신호등이 초록불로 바뀌면 손을 들고 길을 건너요.","길 건너 빵집에서 고소한 냄새가 나요.","치과 옆 정류장에는 버스가 멈춰 서요.","눈이 온 날에는 길에 발자국이 콕콕 찍혀요."],"title":"학교 가는 길"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_basic#5','kor',1,1,'u4','L09','g1_1_kor_u4_L09_basic','lesson_basic','K1-1-u4-C7',2,'mc','auto','뜻이 맞는 문장은 어느 것인가요?',ARRAY['K1-1-u4-X14']::text[],true,'{"seq":5,"concept":"K1-1-u4-C7","difficulty":2,"kind":"mc","stem":"뜻이 맞는 문장은 어느 것인가요?","options":[{"t":"「신호등이 초록불일 때 길을 건너요.」","correct":true},{"t":"「신호등에서 빵을 사요.」","mis":"K1-1-u4-X14"},{"t":"「치과에서 꽃을 사요.」","mis":"K1-1-u4-X14"}],"explanation":["신호등은 길을 건널 때 보는 것이에요.","빵은 빵집에서, 꽃은 꽃집에서 사요.","문장을 읽고 「정말 그럴까?」 물어봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 뜻이 맞는 문장은 어느 것인가요?","options":[{"t":"「정류장에서 버스를 기다려요.」","correct":true},{"t":"「정류장에서 이를 치료받아요.」","mis":"K1-1-u4-X14"},{"t":"「꽃집에서 버스를 타요.」","mis":"K1-1-u4-X14"}],"explanation":["버스는 정류장에서 기다려요.","이는 치과에서 치료받고, 꽃집에서는 버스를 타지 않아요.","「정말 그럴까?」 물어봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_basic#6','kor',1,1,'u4','L09','g1_1_kor_u4_L09_basic','lesson_basic','K1-1-u4-C7',2,'match','auto','이야기 속 낱말과 어울리는 말을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K1-1-u4-C7","difficulty":2,"kind":"match","stem":"이야기 속 낱말과 어울리는 말을 이으세요.","pairs":[{"l":"꽃집","r":"노란 꽃"},{"l":"빵집","r":"고소한 냄새"},{"l":"정류장","r":"버스"}],"mis":"K1-1-u4-X13","explanation":["꽃집-노란 꽃, 빵집-고소한 냄새, 정류장-버스.","이야기를 다시 떠올려요.","장소마다 무엇이 함께 나왔는지 기억해요."],"asset":{"type":"passage","lines":["도윤이는 아침마다 걸어서 학교에 가요.","집을 나서면 먼저 꽃집이 보여요. 꽃집 앞에는 노란 꽃이 가득해요.","신호등이 초록불로 바뀌면 손을 들고 길을 건너요.","길 건너 빵집에서 고소한 냄새가 나요.","치과 옆 정류장에는 버스가 멈춰 서요.","눈이 온 날에는 길에 발자국이 콕콕 찍혀요."],"title":"학교 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_basic#7','kor',1,1,'u4','L09','g1_1_kor_u4_L09_basic','lesson_basic','K1-1-u4-C5',2,'mc','auto','「꽃집」에서 하는 일은 어느 것인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":7,"concept":"K1-1-u4-C5","difficulty":2,"kind":"mc","stem":"「꽃집」에서 하는 일은 어느 것인가요?","options":[{"t":"꽃을 사요","correct":true},{"t":"이를 치료받아요","mis":"K1-1-u4-X10"},{"t":"빵을 사요","mis":"K1-1-u4-X10"}],"explanation":["「꽃집」에서는 꽃을 사요.","「이를 치료받아요」·「빵을 사요」는 다른 곳에서 하는 일이에요.","장소 이름과 그곳에서 하는 일을 짝 지어 떠올려요."],"variant_rule":{"wlink":{"ask":"place","mis":{"link":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_basic#8','kor',1,1,'u4','L09','g1_1_kor_u4_L09_basic','lesson_basic','K1-1-u4-C7',2,'mc','auto','길에 발자국이 콕콕 찍힌 날은 어떤 날인가요?',ARRAY['K1-1-u4-X13']::text[],false,'{"seq":8,"concept":"K1-1-u4-C7","difficulty":2,"kind":"mc","stem":"길에 발자국이 콕콕 찍힌 날은 어떤 날인가요?","options":[{"t":"눈이 온 날","correct":true},{"t":"비가 온 날","mis":"K1-1-u4-X13"},{"t":"바람이 분 날","mis":"K1-1-u4-X13"}],"explanation":["눈이 온 날 발자국이 찍혀요.","비·바람은 이야기에 나오지 않았어요.","이야기 끝부분까지 들어요."],"asset":{"type":"passage","lines":["도윤이는 아침마다 걸어서 학교에 가요.","집을 나서면 먼저 꽃집이 보여요. 꽃집 앞에는 노란 꽃이 가득해요.","신호등이 초록불로 바뀌면 손을 들고 길을 건너요.","길 건너 빵집에서 고소한 냄새가 나요.","치과 옆 정류장에는 버스가 멈춰 서요.","눈이 온 날에는 길에 발자국이 콕콕 찍혀요."],"title":"학교 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_basic#9','kor',1,1,'u4','L09','g1_1_kor_u4_L09_basic','lesson_basic','K1-1-u4-C7',2,'mc','auto','「정류장」을 넣어 뜻에 맞게 말한 문장은 어느 것인가요?',ARRAY['K1-1-u4-X14']::text[],true,'{"seq":9,"concept":"K1-1-u4-C7","difficulty":2,"kind":"mc","stem":"「정류장」을 넣어 뜻에 맞게 말한 문장은 어느 것인가요?","options":[{"t":"「정류장에서 버스를 기다려요.」","correct":true},{"t":"「정류장에서 이를 치료받아요.」","mis":"K1-1-u4-X14"},{"t":"「정류장에서 꽃을 심어요.」","mis":"K1-1-u4-X14"}],"explanation":["정류장은 버스를 타고 내리는 곳이에요.","이를 치료받거나 꽃을 심는 곳이 아니에요.","낱말의 뜻에 맞게 문장을 만들어요."],"variant_rule":{"alt":[{"stem":"「신호등」을 넣어 뜻에 맞게 말한 문장은 어느 것인가요?","options":[{"t":"「신호등을 보고 길을 건너요.」","correct":true},{"t":"「신호등에서 빵을 사요.」","mis":"K1-1-u4-X14"},{"t":"「신호등으로 편지를 보내요.」","mis":"K1-1-u4-X14"}],"explanation":["신호등을 보고 길을 건너요.","빵을 사거나 편지를 보내는 곳이 아니에요.","뜻에 맞게 만들어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_basic#10','kor',1,1,'u4','L09','g1_1_kor_u4_L09_basic','lesson_basic','K1-1-u4-C7',3,'mc','auto','도윤이가 학교 가는 길에 지나간 차례대로 놓은 것은 어느 것인가요?',ARRAY['K1-1-u4-X13']::text[],false,'{"seq":10,"concept":"K1-1-u4-C7","difficulty":3,"kind":"mc","stem":"도윤이가 학교 가는 길에 지나간 차례대로 놓은 것은 어느 것인가요?","options":[{"t":"꽃집 → 신호등 → 빵집","correct":true},{"t":"빵집 → 신호등 → 꽃집","mis":"K1-1-u4-X13"},{"t":"꽃집 → 빵집 → 신호등","mis":"K1-1-u4-X13"}],"explanation":["꽃집을 보고, 신호등에서 건너, 빵집 냄새를 맡았어요.","다른 두 차례는 이야기와 달라요.","나온 차례대로 손가락을 꼽아요."],"asset":{"type":"passage","lines":["도윤이는 아침마다 걸어서 학교에 가요.","집을 나서면 먼저 꽃집이 보여요. 꽃집 앞에는 노란 꽃이 가득해요.","신호등이 초록불로 바뀌면 손을 들고 길을 건너요.","길 건너 빵집에서 고소한 냄새가 나요.","치과 옆 정류장에는 버스가 멈춰 서요.","눈이 온 날에는 길에 발자국이 콕콕 찍혀요."],"title":"학교 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_challenge#1','kor',1,1,'u4','L09','g1_1_kor_u4_L09_challenge','lesson_challenge','K1-1-u4-C7',2,'mc','auto','서윤이가 할머니께 편지를 보낸 곳은 어디인가요?',ARRAY['K1-1-u4-X13']::text[],false,'{"seq":1,"concept":"K1-1-u4-C7","difficulty":2,"kind":"mc","stem":"서윤이가 할머니께 편지를 보낸 곳은 어디인가요?","options":[{"t":"우체국","correct":true},{"t":"약국","mis":"K1-1-u4-X13"},{"t":"시장","mis":"K1-1-u4-X13"}],"explanation":["「우체국」에서 편지를 보냈어요.","약국에서는 약을, 시장에서는 사과와 대파를 샀어요.","이야기에서 편지가 나온 곳을 찾아요."],"asset":{"type":"passage","lines":["서윤이는 엄마와 함께 동네를 한 바퀴 돌았어요.","먼저 우체국에서 할머니께 편지를 보냈어요.","약국에 들러 감기약을 샀어요.","시장에서는 빨간 사과와 긴 대파를 골랐어요.","돌아오는 길에 가구점 앞 커다란 의자에 잠깐 앉아 쉬었어요."],"title":"서윤이의 심부름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_challenge#2','kor',1,1,'u4','L09','g1_1_kor_u4_L09_challenge','lesson_challenge','K1-1-u4-C5',2,'mc','auto','「약을 사요」 — 이 일을 하는 곳은 어디인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":2,"concept":"K1-1-u4-C5","difficulty":2,"kind":"mc","stem":"「약을 사요」 — 이 일을 하는 곳은 어디인가요?","options":[{"t":"약국","correct":true},{"t":"우체국","mis":"K1-1-u4-X10"},{"t":"빵집","mis":"K1-1-u4-X10"}],"explanation":["「약국」에서 약을 사요.","「우체국」·「빵집」은 하는 일이 달라요.","그 일을 하러 어디에 가는지 떠올려요."],"variant_rule":{"wlink":{"ask":"placer","mis":{"link":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_challenge#3','kor',1,1,'u4','L09','g1_1_kor_u4_L09_challenge','lesson_challenge','K1-1-u4-C7',3,'mc','auto','서윤이가 들른 곳이 아닌 곳은 어디인가요?',ARRAY['K1-1-u4-X06','K1-1-u4-X13']::text[],false,'{"seq":3,"concept":"K1-1-u4-C7","difficulty":3,"kind":"mc","stem":"서윤이가 들른 곳이 아닌 곳은 어디인가요?","options":[{"t":"병원","correct":true},{"t":"약국","mis":"K1-1-u4-X06"},{"t":"가구점","mis":"K1-1-u4-X13"}],"explanation":["병원은 이야기에 나오지 않았어요.","약국은 병원과 비슷하지만 이야기에 나왔어요.","비슷한 낱말도 끝까지 견주어요."],"asset":{"type":"passage","lines":["서윤이는 엄마와 함께 동네를 한 바퀴 돌았어요.","먼저 우체국에서 할머니께 편지를 보냈어요.","약국에 들러 감기약을 샀어요.","시장에서는 빨간 사과와 긴 대파를 골랐어요.","돌아오는 길에 가구점 앞 커다란 의자에 잠깐 앉아 쉬었어요."],"title":"서윤이의 심부름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_challenge#4','kor',1,1,'u4','L09','g1_1_kor_u4_L09_challenge','lesson_challenge','K1-1-u4-C7',3,'mc','auto','서윤이가 시장에서 고른 것을 꾸며 주는 말과 함께 바르게 말한 것은 어느 것인가요?',ARRAY['K1-1-u4-X13']::text[],false,'{"seq":4,"concept":"K1-1-u4-C7","difficulty":3,"kind":"mc","stem":"서윤이가 시장에서 고른 것을 꾸며 주는 말과 함께 바르게 말한 것은 어느 것인가요?","options":[{"t":"빨간 사과와 긴 대파","correct":true},{"t":"긴 사과와 빨간 대파","mis":"K1-1-u4-X13"},{"t":"빨간 사과와 커다란 의자","mis":"K1-1-u4-X13"}],"explanation":["「빨간 사과」와 「긴 대파」를 골랐어요.","꾸며 주는 말을 바꾸거나, 가구점의 의자를 섞으면 안 돼요.","이야기를 끝까지 듣고 짝을 기억해요."],"asset":{"type":"passage","lines":["서윤이는 엄마와 함께 동네를 한 바퀴 돌았어요.","먼저 우체국에서 할머니께 편지를 보냈어요.","약국에 들러 감기약을 샀어요.","시장에서는 빨간 사과와 긴 대파를 골랐어요.","돌아오는 길에 가구점 앞 커다란 의자에 잠깐 앉아 쉬었어요."],"title":"서윤이의 심부름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_challenge#5','kor',1,1,'u4','L09','g1_1_kor_u4_L09_challenge','lesson_challenge','K1-1-u4-C7',3,'error','auto','은솔이가 「서윤이의 심부름」을 듣고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_challenge#6','kor',1,1,'u4','L09','g1_1_kor_u4_L09_challenge','lesson_challenge','K1-1-u4-C5',3,'mc','auto','「가구점」에서 볼 수 있는 것끼리 모은 것은 어느 것인가요?',ARRAY['K1-1-u4-X10']::text[],false,'{"seq":6,"concept":"K1-1-u4-C5","difficulty":3,"kind":"mc","stem":"「가구점」에서 볼 수 있는 것끼리 모은 것은 어느 것인가요?","options":[{"t":"의자 · 책상 · 옷장","correct":true},{"t":"빵 · 과자 · 우유","mis":"K1-1-u4-X10"},{"t":"꽃 · 화분 · 씨앗","mis":"K1-1-u4-X10"}],"explanation":["가구점에서는 의자·책상·옷장 같은 가구를 팔아요.","빵은 빵집, 꽃은 꽃집에서 볼 수 있어요.","장소 이름에서 무엇을 파는지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_challenge#7','kor',1,1,'u4','L09','g1_1_kor_u4_L09_challenge','lesson_challenge','K1-1-u4-C7',3,'ox','auto','서윤이는 가구점에서 의자를 샀어요.',ARRAY['K1-1-u4-X13']::text[],false,'{"seq":7,"concept":"K1-1-u4-C7","difficulty":3,"kind":"ox","stem":"서윤이는 가구점에서 의자를 샀어요.","answer":"X","reason_options":[{"t":"의자에 잠깐 앉아 쉬었을 뿐 샀다는 말은 없으니까","correct":true},{"t":"가구점에 갔으니 무엇이든 샀을 테니까","mis":"K1-1-u4-X13"}],"mis":"K1-1-u4-X13","explanation":["이야기에는 「앉아 쉬었어요」라고만 나와요.","나오지 않은 내용을 짐작해 말하지 않아요.","들은 말 그대로 견주어요."],"asset":{"type":"passage","lines":["서윤이는 엄마와 함께 동네를 한 바퀴 돌았어요.","먼저 우체국에서 할머니께 편지를 보냈어요.","약국에 들러 감기약을 샀어요.","시장에서는 빨간 사과와 긴 대파를 골랐어요.","돌아오는 길에 가구점 앞 커다란 의자에 잠깐 앉아 쉬었어요."],"title":"서윤이의 심부름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_challenge#8','kor',1,1,'u4','L09','g1_1_kor_u4_L09_challenge','lesson_challenge','K1-1-u4-C5',4,'mc','auto','두 이야기에 나온 곳 가운데 아플 때 가는 곳만 모은 것은 어느 것인가요?',ARRAY['K1-1-u4-X10']::text[],false,'{"seq":8,"concept":"K1-1-u4-C5","difficulty":4,"kind":"mc","stem":"두 이야기에 나온 곳 가운데 아플 때 가는 곳만 모은 것은 어느 것인가요?","options":[{"t":"치과 · 약국","correct":true},{"t":"치과 · 빵집","mis":"K1-1-u4-X10"},{"t":"약국 · 우체국","mis":"K1-1-u4-X10"}],"explanation":["치과는 이를, 약국은 약을 — 아플 때 가는 곳이에요.","빵집·우체국은 아플 때 가는 곳이 아니에요.","장소마다 하는 일을 떠올려 골라요."],"asset":{"type":"passage","lines":["도윤이가 본 곳: 꽃집 · 신호등 · 빵집 · 치과 · 정류장","서윤이가 들른 곳: 우체국 · 약국 · 시장 · 가구점"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_challenge#9','kor',1,1,'u4','L09','g1_1_kor_u4_L09_challenge','lesson_challenge','K1-1-u4-C7',4,'mc','auto','낱말 하나만 바꾸면 뜻이 맞는 문장이 돼요. 바꿀 낱말을 바르게 고른 것은 어느 것인가요?',ARRAY['K1-1-u4-X10','K1-1-u4-X14']::text[],true,'{"seq":9,"concept":"K1-1-u4-C7","difficulty":4,"kind":"mc","stem":"낱말 하나만 바꾸면 뜻이 맞는 문장이 돼요. 바꿀 낱말을 바르게 고른 것은 어느 것인가요?","options":[{"t":"「꽃집에서 이를 치료받아요.」 — 「꽃집」을 「치과」로","correct":true},{"t":"「꽃집에서 이를 치료받아요.」 — 「꽃집」을 「빵집」으로","mis":"K1-1-u4-X10"},{"t":"「꽃집에서 이를 치료받아요.」 — 「이」를 「꽃」으로","mis":"K1-1-u4-X14"}],"explanation":["이를 치료받는 곳은 치과예요.","빵집으로 바꿔도, 「꽃을 치료받아요」로 바꿔도 뜻이 이상해요.","바꾼 문장을 읽고 「정말 그럴까?」 확인해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말 하나만 바꾸면 뜻이 맞는 문장이 돼요. 바꿀 낱말을 바르게 고른 것은 어느 것인가요?","options":[{"t":"「은행에서 편지를 보내요.」 — 「은행」을 「우체국」으로","correct":true},{"t":"「은행에서 편지를 보내요.」 — 「은행」을 「약국」으로","mis":"K1-1-u4-X10"},{"t":"「은행에서 편지를 보내요.」 — 「편지」를 「빵」으로","mis":"K1-1-u4-X14"}],"explanation":["편지는 우체국에서 보내요.","약국으로 바꾸거나 「빵을 보내요」로 바꿔도 이상해요.","바꾼 문장을 읽고 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L09_challenge#10','kor',1,1,'u4','L09','g1_1_kor_u4_L09_challenge','lesson_challenge','K1-1-u4-C7',4,'essay','teacher','학교 가는 길에 볼 수 있는 낱말 두 개를 골라, 두 낱말이 모두 들어간 문장을 만들어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u4-C7","difficulty":4,"kind":"essay","stem":"학교 가는 길에 볼 수 있는 낱말 두 개를 골라, 두 낱말이 모두 들어간 문장을 만들어 보세요.","answer_guide":{"answer":"예: 「신호등이 초록불일 때 정류장 쪽으로 길을 건너요.」","scoring_points":["학교 가는 길에 볼 수 있는 낱말 두 개를 골랐는가","두 낱말을 한 문장(또는 이어지는 문장)에 넣었는가","문장의 뜻이 통하는가"]},"explanation":["길에서 볼 수 있는 낱말 두 개.","두 낱말을 모두 넣기.","뜻이 통하는지 읽어 보기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_basic#1','kor',1,1,'u4','L11','g1_1_kor_u4_L11_basic','lesson_basic','K1-1-u4-C8',1,'mc','auto','「학교에 가면 칠판도 있고」 다음 친구가 이어 말한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u4-X12','K1-1-u4-X15']::text[],true,'{"seq":1,"concept":"K1-1-u4-C8","difficulty":1,"kind":"mc","stem":"「학교에 가면 칠판도 있고」 다음 친구가 이어 말한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「학교에 가면 칠판도 있고, 책상도 있고」","correct":true},{"t":"「학교에 가면 칠판도 있고, 은행도 있고」","mis":"K1-1-u4-X12"},{"t":"「학교에 가면 책상도 있고」","mis":"K1-1-u4-X15"}],"explanation":["앞 말 「칠판」을 그대로 말하고 학교 낱말 하나를 더했어요.","은행은 학교에 없고, 「칠판」을 빠뜨리면 안 돼요.","앞 말 그대로 + 새 낱말 하나."],"variant_rule":{"alt":[{"stem":"「동네에 가면 빵집도 있고」 다음 친구가 이어 말한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「동네에 가면 빵집도 있고, 약국도 있고」","correct":true},{"t":"「동네에 가면 빵집도 있고, 칠판도 있고」","mis":"K1-1-u4-X12"},{"t":"「동네에 가면 약국도 있고」","mis":"K1-1-u4-X15"}],"explanation":["앞 말 「빵집」을 그대로 말하고 동네 낱말 하나를 더했어요.","칠판은 동네에 없고, 「빵집」을 빠뜨리면 안 돼요.","앞 말 그대로 + 새 낱말 하나."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_basic#2','kor',1,1,'u4','L11','g1_1_kor_u4_L11_basic','lesson_basic','K1-1-u4-C8',1,'mc','auto','초성이 「ㅅㄱ」인 과일은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],true,'{"seq":2,"concept":"K1-1-u4-C8","difficulty":1,"kind":"mc","stem":"초성이 「ㅅㄱ」인 과일은 어느 것인가요?","options":[{"t":"사과","correct":true},{"t":"수박","mis":"K1-1-u4-X16"},{"t":"포도","mis":"K1-1-u4-X16"}],"explanation":["사과 = ㅅ + ㄱ.","수박은 ㅅㅂ, 포도는 ㅍㄷ이에요.","글자마다 첫 자음자를 차례대로 견줘요."],"variant_rule":{"alt":[{"stem":"초성이 「ㄱㅂ」인 학용품은 어느 것인가요?","options":[{"t":"가방","correct":true},{"t":"공책","mis":"K1-1-u4-X16"},{"t":"가위","mis":"K1-1-u4-X16"}],"explanation":["가방 = ㄱ + ㅂ.","공책은 ㄱㅊ, 가위는 ㄱㅇ이에요.","첫 자음자를 차례대로 견줘요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_basic#3','kor',1,1,'u4','L11','g1_1_kor_u4_L11_basic','lesson_basic','K1-1-u4-C6',1,'mc','auto','사람을 나타내는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X06']::text[],true,'{"seq":3,"concept":"K1-1-u4-C6","difficulty":1,"kind":"mc","stem":"사람을 나타내는 낱말은 어느 것인가요?","options":[{"t":"소방관","correct":true},{"t":"소방서","mis":"K1-1-u4-X06"},{"t":"소방차","mis":"K1-1-u4-X06"}],"explanation":["「소방관」은 불을 끄는 사람이에요.","소방서는 장소, 소방차는 차예요.","낱말 끝 글자까지 읽고 사람인지 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 사람을 나타내는 낱말은 어느 것인가요?","options":[{"t":"경찰관","correct":true},{"t":"경찰서","mis":"K1-1-u4-X06"},{"t":"경찰차","mis":"K1-1-u4-X06"}],"explanation":["「경찰관」은 우리를 지켜 주는 사람이에요.","경찰서는 장소, 경찰차는 차예요.","끝 글자까지 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_basic#4','kor',1,1,'u4','L11','g1_1_kor_u4_L11_basic','lesson_basic','K1-1-u4-C8',1,'ox','auto','초성 「ㄱㅂ」은 두 글자 낱말의 초성이에요.',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":4,"concept":"K1-1-u4-C8","difficulty":1,"kind":"ox","stem":"초성 「ㄱㅂ」은 두 글자 낱말의 초성이에요.","answer":"O","reason_options":[{"t":"초성 하나가 글자 하나이니 초성이 둘이면 두 글자이니까","correct":true},{"t":"자음자가 두 개 모이면 한 글자이니까","mis":"K1-1-u4-X16"}],"mis":"K1-1-u4-X16","explanation":["ㄱㅂ → 가방처럼 두 글자예요.","초성 칸 하나 = 글자 하나.","초성 수를 세면 글자 수를 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_basic#5','kor',1,1,'u4','L11','g1_1_kor_u4_L11_basic','lesson_basic','K1-1-u4-C8',2,'mc','auto','초성이 「ㅈㅇㄱ」인 학용품은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],true,'{"seq":5,"concept":"K1-1-u4-C8","difficulty":2,"kind":"mc","stem":"초성이 「ㅈㅇㄱ」인 학용품은 어느 것인가요?","options":[{"t":"지우개","correct":true},{"t":"자","mis":"K1-1-u4-X16"},{"t":"색연필","mis":"K1-1-u4-X16"}],"explanation":["지우개 = ㅈ + ㅇ + ㄱ, 세 글자예요.","자는 한 글자, 색연필은 ㅅㅇㅍ이에요.","초성 수와 글자 수를 함께 견줘요."],"variant_rule":{"alt":[{"stem":"초성이 「ㄱㄱㅅ」인 학교 물건은 어느 것인가요?","options":[{"t":"교과서","correct":true},{"t":"공책","mis":"K1-1-u4-X16"},{"t":"가방","mis":"K1-1-u4-X16"}],"explanation":["교과서 = ㄱ + ㄱ + ㅅ, 세 글자예요.","공책·가방은 두 글자예요.","초성 수 = 글자 수."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_basic#6','kor',1,1,'u4','L11','g1_1_kor_u4_L11_basic','lesson_basic','K1-1-u4-C8',2,'error','auto','친구들이 「동네에 가면」 놀이를 했어요. 잘못 이어 말한 친구와 그 까닭은 어느 것인가요?',ARRAY['K1-1-u4-X15']::text[],false,'{"seq":6,"concept":"K1-1-u4-C8","difficulty":2,"kind":"error","stem":"친구들이 「동네에 가면」 놀이를 했어요. 잘못 이어 말한 친구와 그 까닭은 어느 것인가요?","options":[{"t":"태민 — 앞에서 말한 「빵집」을 빠뜨렸어요","correct":true,"mis_target":"K1-1-u4-X15"},{"t":"하린 — 낱말을 두 개나 말했어요","mis":"K1-1-u4-X15"},{"t":"민호 — 낱말을 하나만 말했어요","mis":"K1-1-u4-X15"}],"explanation":["태민이는 「빵집」을 빼고 말했어요.","하린이는 앞 말 + 새 낱말로 바르게, 민호는 처음이라 하나만 말해요.","앞 말을 손가락으로 꼽으며 그대로 말해요."],"asset":{"type":"speech","turns":[{"who":"민호","text":"동네에 가면 빵집도 있고"},{"who":"하린","text":"동네에 가면 빵집도 있고, 은행도 있고"},{"who":"태민","text":"동네에 가면 은행도 있고, 꽃집도 있고"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_basic#7','kor',1,1,'u4','L11','g1_1_kor_u4_L11_basic','lesson_basic','K1-1-u4-C6',2,'mc','auto','「아픈 사람을 치료해요.」 이 일을 하는 사람은 누구인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":7,"concept":"K1-1-u4-C6","difficulty":2,"kind":"mc","stem":"「아픈 사람을 치료해요.」 이 일을 하는 사람은 누구인가요?","options":[{"t":"의사","correct":true},{"t":"소방관","mis":"K1-1-u4-X10"},{"t":"선생님","mis":"K1-1-u4-X10"}],"explanation":["아픈 사람을 치료하는 사람은 「의사」예요.","소방관은 불을 끄고, 선생님은 가르쳐요.","사람과 하는 일을 짝 지어요."],"variant_rule":{"alt":[{"stem":"「편지와 소포를 집집마다 전해 줘요.」 이 일을 하는 사람은 누구인가요?","options":[{"t":"집배원","correct":true},{"t":"경찰관","mis":"K1-1-u4-X10"},{"t":"의사","mis":"K1-1-u4-X10"}],"explanation":["편지를 전해 주는 사람은 「집배원」이에요.","경찰관은 우리를 지키고, 의사는 치료해요.","사람과 하는 일을 짝 지어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_basic#8','kor',1,1,'u4','L11','g1_1_kor_u4_L11_basic','lesson_basic','K1-1-u4-C6',2,'match','auto','사람과 그 사람이 하는 일을 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K1-1-u4-C6","difficulty":2,"kind":"match","stem":"사람과 그 사람이 하는 일을 이으세요.","pairs":[{"l":"소방관","r":"불을 꺼요"},{"l":"경찰관","r":"길을 안내하고 지켜요"},{"l":"집배원","r":"편지를 전해요"}],"mis":"K1-1-u4-X10","explanation":["소방관-불, 경찰관-지키기, 집배원-편지.","사람마다 하는 일을 떠올려요.","사람 낱말도 낱말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_basic#9','kor',1,1,'u4','L11','g1_1_kor_u4_L11_basic','lesson_basic','K1-1-u4-C8',2,'mc','auto','다음 초성 퀴즈에서 정답이 몇 글자 낱말인지 바르게 말한 것은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],true,'{"seq":9,"concept":"K1-1-u4-C8","difficulty":2,"kind":"mc","stem":"다음 초성 퀴즈에서 정답이 몇 글자 낱말인지 바르게 말한 것은 어느 것인가요?","options":[{"t":"세 글자","correct":true},{"t":"두 글자","mis":"K1-1-u4-X16"},{"t":"한 글자","mis":"K1-1-u4-X16"}],"explanation":["초성 칸이 세 개이니 세 글자예요 — 정답은 「호랑이」.","자음자 수를 잘못 세면 글자 수가 틀려요.","초성 칸 하나 = 글자 하나."],"asset":{"type":"scene","icon":"🐯","text":"ㅎ ㄹ ㅇ"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 초성 퀴즈에서 정답이 몇 글자 낱말인지 바르게 말한 것은 어느 것인가요?","options":[{"t":"두 글자","correct":true},{"t":"세 글자","mis":"K1-1-u4-X16"},{"t":"네 글자","mis":"K1-1-u4-X16"}],"explanation":["초성 칸이 두 개이니 두 글자예요 — 정답은 「기린」.","초성 칸 수를 세어요.","초성 칸 하나 = 글자 하나."],"asset":{"type":"scene","icon":"🦒","text":"ㄱ ㄹ"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_basic#10','kor',1,1,'u4','L11','g1_1_kor_u4_L11_basic','lesson_basic','K1-1-u4-C8',3,'mc','auto','글자판에서 가로(→)나 세로(↓)로 숨어 있지 않은 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],true,'{"seq":10,"concept":"K1-1-u4-C8","difficulty":3,"kind":"mc","stem":"글자판에서 가로(→)나 세로(↓)로 숨어 있지 않은 낱말은 어느 것인가요?","options":[{"t":"포도","correct":true},{"t":"사과","mis":"K1-1-u4-X16"},{"t":"나무","mis":"K1-1-u4-X16"}],"explanation":["「포도」는 글자판 어디에도 없어요.","「사과」는 가로로, 「나무」는 세로로 숨어 있어요.","왼쪽 → 오른쪽, 위 → 아래로만 이어 읽어요."],"asset":{"type":"word_grid","rows":["수박나","사과무","토끼리"],"ask":"find"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글자판에서 가로(→)나 세로(↓)로 숨어 있지 않은 낱말은 어느 것인가요?","options":[{"t":"기린","correct":true},{"t":"우유","mis":"K1-1-u4-X16"},{"t":"기차","mis":"K1-1-u4-X16"}],"explanation":["「기린」은 글자판 어디에도 없어요.","「우유」는 세로로, 「기차」는 세로로 숨어 있어요.","가로·세로로만 이어 읽어요."],"asset":{"type":"word_grid","rows":["기우바","차유나","감나비"],"ask":"find"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_challenge#1','kor',1,1,'u4','L11','g1_1_kor_u4_L11_challenge','lesson_challenge','K1-1-u4-C8',2,'mc','auto','글자판에서 가로(→)나 세로(↓)로 숨어 있는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],true,'{"seq":1,"concept":"K1-1-u4-C8","difficulty":2,"kind":"mc","stem":"글자판에서 가로(→)나 세로(↓)로 숨어 있는 낱말은 어느 것인가요?","options":[{"t":"우산","correct":true},{"t":"사자","mis":"K1-1-u4-X16"},{"t":"포크","mis":"K1-1-u4-X16"}],"explanation":["「우산」은 왼쪽 첫 줄을 위에서 아래로 읽으면 나와요.","「사자」·「포크」는 글자판에 없어요.","가로·세로로만 이어 읽어요."],"asset":{"type":"word_grid","rows":["우유컵","산포도","책상자"],"ask":"find"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글자판에서 가로(→)나 세로(↓)로 숨어 있는 낱말은 어느 것인가요?","options":[{"t":"바나나","correct":true},{"t":"나비","mis":"K1-1-u4-X16"},{"t":"바다","mis":"K1-1-u4-X16"}],"explanation":["「바나나」는 맨 아래 줄을 왼쪽에서 오른쪽으로 읽으면 나와요.","「나비」·「바다」는 글자판에 없어요.","가로·세로로만 이어 읽어요."],"asset":{"type":"word_grid","rows":["기린우","차사유","바나나"],"ask":"find"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_challenge#2','kor',1,1,'u4','L11','g1_1_kor_u4_L11_challenge','lesson_challenge','K1-1-u4-C8',2,'mc','auto','「학교에 가면」 이어 말하기 놀이의 규칙으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u4-X15','K1-1-u4-X12']::text[],false,'{"seq":2,"concept":"K1-1-u4-C8","difficulty":2,"kind":"mc","stem":"「학교에 가면」 이어 말하기 놀이의 규칙으로 알맞은 것은 어느 것인가요?","options":[{"t":"앞 친구가 말한 낱말을 모두 말하고 새 낱말을 하나 더해요","correct":true},{"t":"앞 말은 빼고 새 낱말만 말해요","mis":"K1-1-u4-X15"},{"t":"어느 곳 낱말이든 아무거나 말해요","mis":"K1-1-u4-X12"}],"explanation":["앞 말 그대로 + 새 낱말 하나가 규칙이에요.","앞 말을 빼면 이어지지 않아요.","학교에서 볼 수 있는 낱말만 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
