INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_challenge#4','kor',1,1,'u4','L11','g1_1_kor_u4_L11_challenge','lesson_challenge','K1-1-u4-C8',3,'mc','auto','초성이 「ㅅㅂㅅ」이고 불이 나면 출동하는 곳은 어디인가요?',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":4,"concept":"K1-1-u4-C8","difficulty":3,"kind":"mc","stem":"초성이 「ㅅㅂㅅ」이고 불이 나면 출동하는 곳은 어디인가요?","options":[{"t":"소방서","correct":true},{"t":"소방관","mis":"K1-1-u4-X16"},{"t":"소방차","mis":"K1-1-u4-X16"}],"explanation":["소방서 = ㅅ + ㅂ + ㅅ.","소방관은 ㅅㅂㄱ, 소방차는 ㅅㅂㅊ이에요.","마지막 초성까지 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_challenge#5','kor',1,1,'u4','L11','g1_1_kor_u4_L11_challenge','lesson_challenge','K1-1-u4-C6',3,'mc','auto','「의사 · 병원 · 경찰관 · 경찰서」에서 사람을 나타내는 낱말만 모은 것은 어느 것인가요?',ARRAY['K1-1-u4-X12','K1-1-u4-X06']::text[],false,'{"seq":5,"concept":"K1-1-u4-C6","difficulty":3,"kind":"mc","stem":"「의사 · 병원 · 경찰관 · 경찰서」에서 사람을 나타내는 낱말만 모은 것은 어느 것인가요?","options":[{"t":"의사 · 경찰관","correct":true},{"t":"병원 · 경찰서","mis":"K1-1-u4-X12"},{"t":"의사 · 경찰서","mis":"K1-1-u4-X06"}],"explanation":["의사·경찰관은 사람이에요.","병원·경찰서는 장소예요.","낱말마다 「사람? 장소?」를 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_challenge#6','kor',1,1,'u4','L11','g1_1_kor_u4_L11_challenge','lesson_challenge','K1-1-u4-C8',3,'mc','auto','글자판에서 가로(→)나 세로(↓)로 숨어 있지 않은 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],true,'{"seq":6,"concept":"K1-1-u4-C8","difficulty":3,"kind":"mc","stem":"글자판에서 가로(→)나 세로(↓)로 숨어 있지 않은 낱말은 어느 것인가요?","options":[{"t":"나비","correct":true},{"t":"기차","mis":"K1-1-u4-X16"},{"t":"우유","mis":"K1-1-u4-X16"}],"explanation":["「나비」는 글자판 어디에도 없어요.","「기차」는 첫째 칸 세로, 「우유」는 셋째 칸 세로로 숨어 있어요.","대각선이나 거꾸로는 읽지 않아요."],"asset":{"type":"word_grid","rows":["기린우","차사유","바나나"],"ask":"find"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 글자판에서 가로(→)나 세로(↓)로 숨어 있지 않은 낱말은 어느 것인가요?","options":[{"t":"도자기","correct":true},{"t":"우산","mis":"K1-1-u4-X16"},{"t":"상자","mis":"K1-1-u4-X16"}],"explanation":["「도자기」는 글자판 어디에도 없어요.","「우산」은 세로, 「상자」는 가로로 숨어 있어요.","가로·세로로만 이어 읽어요."],"asset":{"type":"word_grid","rows":["우유컵","산포도","책상자"],"ask":"find"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_challenge#7','kor',1,1,'u4','L11','g1_1_kor_u4_L11_challenge','lesson_challenge','K1-1-u4-C8',3,'ox','auto','초성 「ㅂㄴㄴ」의 정답은 「바나나」처럼 세 글자 낱말이에요.',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":7,"concept":"K1-1-u4-C8","difficulty":3,"kind":"ox","stem":"초성 「ㅂㄴㄴ」의 정답은 「바나나」처럼 세 글자 낱말이에요.","answer":"O","reason_options":[{"t":"초성 칸이 세 개이니 세 글자이니까","correct":true},{"t":"「ㄴ」이 두 번 나오니 한 글자로 합쳐지니까","mis":"K1-1-u4-X16"}],"mis":"K1-1-u4-X16","explanation":["ㅂ·ㄴ·ㄴ → 바·나·나.","같은 초성이 두 번 나와도 글자는 따로따로예요.","초성 칸 하나 = 글자 하나."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_challenge#8','kor',1,1,'u4','L11','g1_1_kor_u4_L11_challenge','lesson_challenge','K1-1-u4-C8',4,'mc','auto','친구들이 「학교에 가면」 놀이를 하고 있어요. 넷째 친구가 이어 말할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u4-X15','K1-1-u4-X12']::text[],false,'{"seq":8,"concept":"K1-1-u4-C8","difficulty":4,"kind":"mc","stem":"친구들이 「학교에 가면」 놀이를 하고 있어요. 넷째 친구가 이어 말할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「학교에 가면 칠판도 있고, 교실도 있고, 강당도 있고, 사물함도 있고」","correct":true},{"t":"「학교에 가면 칠판도 있고, 강당도 있고, 사물함도 있고」","mis":"K1-1-u4-X15"},{"t":"「학교에 가면 칠판도 있고, 교실도 있고, 강당도 있고, 꽃집도 있고」","mis":"K1-1-u4-X12"}],"explanation":["앞 세 낱말을 차례대로 말하고 학교 낱말을 하나 더했어요.","「교실」을 빠뜨리거나, 학교에 없는 꽃집을 더하면 안 돼요.","앞 말 그대로 + 새 낱말 하나."],"asset":{"type":"speech","turns":[{"who":"첫째","text":"학교에 가면 칠판도 있고"},{"who":"둘째","text":"학교에 가면 칠판도 있고, 교실도 있고"},{"who":"셋째","text":"학교에 가면 칠판도 있고, 교실도 있고, 강당도 있고"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_challenge#9','kor',1,1,'u4','L11','g1_1_kor_u4_L11_challenge','lesson_challenge','K1-1-u4-C6',4,'mc','auto','수수께끼예요. 「나는 학교에 있어요. 다치거나 아프면 보건실에서 돌봐 줘요.」 나는 누구일까요?',ARRAY['K1-1-u4-X06']::text[],false,'{"seq":9,"concept":"K1-1-u4-C6","difficulty":4,"kind":"mc","stem":"수수께끼예요. 「나는 학교에 있어요. 다치거나 아프면 보건실에서 돌봐 줘요.」 나는 누구일까요?","options":[{"t":"보건 선생님","correct":true},{"t":"의사","mis":"K1-1-u4-X06"},{"t":"보건실","mis":"K1-1-u4-X06"}],"explanation":["학교 보건실에서 돌봐 주는 사람은 「보건 선생님」이에요.","의사는 병원에 있고, 보건실은 장소예요.","설명을 끝까지 듣고 사람인지 장소인지 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_L11_challenge#10','kor',1,1,'u4','L11','g1_1_kor_u4_L11_challenge','lesson_challenge','K1-1-u4-C8',4,'essay','teacher','「동네에 가면 ~도 있고」 놀이로 낱말 세 개를 이어 말하고, 이 놀이의 규칙을 한 문장으로 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-1-u4-C8","difficulty":4,"kind":"essay","stem":"「동네에 가면 ~도 있고」 놀이로 낱말 세 개를 이어 말하고, 이 놀이의 규칙을 한 문장으로 말해 보세요.","answer_guide":{"answer":"예: 「동네에 가면 빵집도 있고, 은행도 있고, 꽃집도 있고」 — 규칙: 앞 친구가 말한 낱말을 모두 말하고 동네 낱말을 하나 더해요.","scoring_points":["동네에서 볼 수 있는 낱말 세 개를 말했는가","틀(「~도 있고」)에 맞게 이어 말했는가","「앞 말 그대로 + 새 낱말 하나」 규칙을 말했는가"]},"explanation":["동네 낱말 세 개.","틀에 맞게 이어 말하기.","규칙을 한 문장으로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#1','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C1',1,'ox','auto','「저거 주세요」라고만 말해도 듣는 사람이 무엇인지 늘 알 수 있어요.',ARRAY['K1-1-u4-X01']::text[],false,'{"seq":1,"concept":"K1-1-u4-C1","difficulty":1,"kind":"ox","stem":"「저거 주세요」라고만 말해도 듣는 사람이 무엇인지 늘 알 수 있어요.","answer":"X","reason_options":[{"t":"「저거」는 이름이 아니라 무엇을 가리키는지 알기 어려우니까","correct":true},{"t":"손으로 가리키면 언제나 알아들으니까","mis":"K1-1-u4-X01"}],"mis":"K1-1-u4-X01","explanation":["이름(낱말)을 말해야 뜻이 전해져요.","멀리 있거나 여러 개면 「저거」로는 몰라요.","「저거」 자리에 이름을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#2','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C2',1,'mc','auto','「눈」으로 하는 일을 나타내는 말은 어느 것인가요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":2,"concept":"K1-1-u4-C2","difficulty":1,"kind":"mc","stem":"「눈」으로 하는 일을 나타내는 말은 어느 것인가요?","options":[{"t":"보다","correct":true},{"t":"듣다","mis":"K1-1-u4-X03"},{"t":"잡다","mis":"K1-1-u4-X03"}],"explanation":["「눈」으로 하는 일은 「보다」예요.","「듣다」·「잡다」는 몸의 다른 곳으로 하는 일이에요.","몸의 그곳을 직접 움직여 보며 무엇을 하는지 떠올려요."],"variant_rule":{"wlink":{"ask":"body","mis":{"link":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#3','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C3',1,'mc','auto','아빠의 엄마를 부르는 말은 어느 것인가요?',ARRAY['K1-1-u4-X04']::text[],false,'{"seq":3,"concept":"K1-1-u4-C3","difficulty":1,"kind":"mc","stem":"아빠의 엄마를 부르는 말은 어느 것인가요?","options":[{"t":"할머니","correct":true},{"t":"이모","mis":"K1-1-u4-X04"},{"t":"고모","mis":"K1-1-u4-X04"}],"explanation":["아빠의 엄마를 부르는 말은 「할머니」예요.","「이모」·「고모」는 다른 관계를 부르는 말이에요.","「누구의 누구인가」를 먼저 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#4','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C4',1,'mc','auto','「얼음」에 어울리는 꾸며 주는 말은 어느 것인가요?',ARRAY['K1-1-u4-X09']::text[],false,'{"seq":4,"concept":"K1-1-u4-C4","difficulty":1,"kind":"mc","stem":"「얼음」에 어울리는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"차가운","correct":true},{"t":"뜨거운","mis":"K1-1-u4-X09"},{"t":"매운","mis":"K1-1-u4-X09"}],"explanation":["「차가운 얼음」 — 모습이 잘 어울려요.","뜨거운·매운 얼음은 없어요.","꾸민 모습을 머릿속에 그려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#5','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C5',1,'mc','auto','「우체국」에서 하는 일은 어느 것인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":5,"concept":"K1-1-u4-C5","difficulty":1,"kind":"mc","stem":"「우체국」에서 하는 일은 어느 것인가요?","options":[{"t":"편지를 보내요","correct":true},{"t":"빵을 사요","mis":"K1-1-u4-X10"},{"t":"돈을 맡겨요","mis":"K1-1-u4-X10"}],"explanation":["「우체국」에서는 편지를 보내요.","「빵을 사요」·「돈을 맡겨요」는 다른 곳에서 하는 일이에요.","장소 이름과 그곳에서 하는 일을 짝 지어 떠올려요."],"variant_rule":{"wlink":{"ask":"place","mis":{"link":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#6','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C6',1,'mc','auto','몸을 나타내는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X02','K1-1-u4-X12']::text[],true,'{"seq":6,"concept":"K1-1-u4-C6","difficulty":1,"kind":"mc","stem":"몸을 나타내는 낱말은 어느 것인가요?","options":[{"t":"무릎","correct":true},{"t":"장갑","mis":"K1-1-u4-X02"},{"t":"피자","mis":"K1-1-u4-X12"}],"explanation":["「무릎」은 몸을 나타내는 낱말이에요.","「장갑」·「피자」는 몸을 나타내는 낱말이 아니에요.","낱말이 무엇을 나타내는지 떠올려 묶음을 정해요."],"variant_rule":{"wcat":{"ask":"pick","cats":["body"],"mis":{"near":"X02","other":"X12"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#7','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C7',1,'mc','auto','뜻이 맞는 문장은 어느 것인가요?',ARRAY['K1-1-u4-X14']::text[],false,'{"seq":7,"concept":"K1-1-u4-C7","difficulty":1,"kind":"mc","stem":"뜻이 맞는 문장은 어느 것인가요?","options":[{"t":"「정류장에서 버스를 기다려요.」","correct":true},{"t":"「정류장에서 이를 치료받아요.」","mis":"K1-1-u4-X14"},{"t":"「신호등에서 빵을 사요.」","mis":"K1-1-u4-X14"}],"explanation":["「정류장에서 버스를 기다려요.」 — 장소와 하는 일이 어울려요.","다른 두 문장은 그곳에서 하지 않는 일이에요.","문장을 읽고 「정말 그럴까?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#8','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C9',1,'mc','auto','그림을 보고 빈칸에 알맞은 낱말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#9','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C2',2,'mc','auto','「듣다」는 몸의 어느 곳으로 하는 일인가요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":9,"concept":"K1-1-u4-C2","difficulty":2,"kind":"mc","stem":"「듣다」는 몸의 어느 곳으로 하는 일인가요?","options":[{"t":"귀","correct":true},{"t":"눈","mis":"K1-1-u4-X03"},{"t":"발","mis":"K1-1-u4-X03"}],"explanation":["「듣다」는 「귀」로 하는 일이에요.","「눈」·「발」은 다른 일을 해요.","그 일을 할 때 몸의 어디가 바빠지는지 떠올려요."],"variant_rule":{"wlink":{"ask":"bodyr","mis":{"link":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#10','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C3',2,'mc','auto','가족을 부르는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X05']::text[],true,'{"seq":10,"concept":"K1-1-u4-C3","difficulty":2,"kind":"mc","stem":"가족을 부르는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"친구","correct":true},{"t":"이모","mis":"K1-1-u4-X05"},{"t":"할아버지","mis":"K1-1-u4-X05"}],"explanation":["「친구」는 가족을 부르는 낱말이 아니에요.","「이모」·「할아버지」는 가족을 부르는 낱말이에요.","묶음마다 무엇을 모았는지 먼저 떠올리고 하나씩 견주어요."],"variant_rule":{"wcat":{"ask":"odd","cats":["family"],"mis":{"in":"X05","near":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#11','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C4',2,'mc','auto','꾸며 주는 말을 바르게 넣은 것은 어느 것인가요?',ARRAY['K1-1-u4-X08','K1-1-u4-X09']::text[],false,'{"seq":11,"concept":"K1-1-u4-C4","difficulty":2,"kind":"mc","stem":"꾸며 주는 말을 바르게 넣은 것은 어느 것인가요?","options":[{"t":"빨간 사과","correct":true},{"t":"사과 빨간","mis":"K1-1-u4-X08"},{"t":"뜨거운 사과","mis":"K1-1-u4-X09"}],"explanation":["꾸며 주는 말 「빨간」은 「사과」 앞에 와요.","뒤에 쓰거나 어울리지 않는 말을 넣으면 안 돼요.","앞에 넣고 소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#12','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C5',2,'mc','auto','「돈을 맡겨요」 — 이 일을 하는 곳은 어디인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":12,"concept":"K1-1-u4-C5","difficulty":2,"kind":"mc","stem":"「돈을 맡겨요」 — 이 일을 하는 곳은 어디인가요?","options":[{"t":"은행","correct":true},{"t":"꽃집","mis":"K1-1-u4-X10"},{"t":"우체국","mis":"K1-1-u4-X10"}],"explanation":["「은행」에서 돈을 맡겨요.","「꽃집」·「우체국」은 하는 일이 달라요.","그 일을 하러 어디에 가는지 떠올려요."],"variant_rule":{"wlink":{"ask":"placer","mis":{"link":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#13','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C6',2,'mc','auto','몸을 나타내는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X02']::text[],true,'{"seq":13,"concept":"K1-1-u4-C6","difficulty":2,"kind":"mc","stem":"몸을 나타내는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"신발","correct":true},{"t":"팔","mis":"K1-1-u4-X02"},{"t":"이마","mis":"K1-1-u4-X02"}],"explanation":["「신발」은 몸을 나타내는 낱말이 아니에요.","「팔」·「이마」는 몸을 나타내는 낱말이에요.","묶음마다 무엇을 모았는지 먼저 떠올리고 하나씩 견주어요."],"variant_rule":{"wcat":{"ask":"odd","cats":["body"],"mis":{"in":"X02","near":"X02"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#14','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C8',2,'mc','auto','초성이 「ㄱ ㄹ」인 동물은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":14,"concept":"K1-1-u4-C8","difficulty":2,"kind":"mc","stem":"초성이 「ㄱ ㄹ」인 동물은 어느 것인가요?","options":[{"t":"기린","correct":true},{"t":"거미","mis":"K1-1-u4-X16"},{"t":"고양이","mis":"K1-1-u4-X16"}],"explanation":["기린 = ㄱ + ㄹ.","「거미」·「고양이」는 초성이 달라요.","글자마다 첫 자음자를 차례대로, 칸 수까지 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#15','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C8',2,'mc','auto','글자판에서 가로(→)나 세로(↓)로 숨어 있는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":15,"concept":"K1-1-u4-C8","difficulty":2,"kind":"mc","stem":"글자판에서 가로(→)나 세로(↓)로 숨어 있는 낱말은 어느 것인가요?","options":[{"t":"사과","correct":true},{"t":"포도","mis":"K1-1-u4-X16"},{"t":"감자","mis":"K1-1-u4-X16"}],"explanation":["「사과」는 왼쪽 첫째 줄을 위에서 아래로 읽으면 나와요.","「포도」·「감자」는 글자판에 없어요.","왼쪽 → 오른쪽, 위 → 아래로만 이어 읽어요."],"asset":{"type":"word_grid","rows":["사자두","과일부","수박지"],"ask":"find"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
