INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#17','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C4',3,'error','auto','은솔이가 쓴 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#18','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C6',3,'mc','auto','「학교 · 동네 · 둘 다」 표를 만들었어요. 「도서관」은 어느 칸에 넣으면 좋을까요?',ARRAY['K1-1-u4-X11']::text[],false,'{"seq":18,"concept":"K1-1-u4-C6","difficulty":3,"kind":"mc","stem":"「학교 · 동네 · 둘 다」 표를 만들었어요. 「도서관」은 어느 칸에 넣으면 좋을까요?","options":[{"t":"둘 다","correct":true},{"t":"학교만","mis":"K1-1-u4-X11"},{"t":"동네만","mis":"K1-1-u4-X11"}],"explanation":["도서관은 학교에도 동네에도 있어요.","한 칸에만 넣거나 엉뚱한 칸에 넣으면 안 돼요.","어디에서 볼 수 있는지 떠올려 칸을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#19','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C7',3,'error','auto','은솔이가 「서윤이의 심부름」을 듣고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#20','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C8',3,'error','auto','친구들이 「동네에 가면」 놀이를 했어요. 잘못 이어 말한 친구와 그 까닭은 어느 것인가요?',ARRAY['K1-1-u4-X15']::text[],false,'{"seq":20,"concept":"K1-1-u4-C8","difficulty":3,"kind":"error","stem":"친구들이 「동네에 가면」 놀이를 했어요. 잘못 이어 말한 친구와 그 까닭은 어느 것인가요?","options":[{"t":"태민 — 앞에서 말한 「빵집」을 빠뜨렸어요","correct":true,"mis_target":"K1-1-u4-X15"},{"t":"하린 — 낱말을 두 개나 말했어요","mis":"K1-1-u4-X15"},{"t":"민호 — 낱말을 하나만 말했어요","mis":"K1-1-u4-X15"}],"explanation":["태민이는 「빵집」을 빼고 말했어요.","둘째 친구는 앞 말 + 새 낱말로 바르게, 첫째 친구는 처음이라 하나만 말해요.","앞 말을 손가락으로 꼽으며 그대로 말해요."],"asset":{"type":"speech","turns":[{"who":"민호","text":"동네에 가면 빵집도 있고"},{"who":"하린","text":"동네에 가면 빵집도 있고, 은행도 있고"},{"who":"태민","text":"동네에 가면 은행도 있고, 꽃집도 있고"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#21','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C9',3,'mc','auto','「있다」와 뜻이 반대인 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X17']::text[],false,'{"seq":21,"concept":"K1-1-u4-C9","difficulty":3,"kind":"mc","stem":"「있다」와 뜻이 반대인 낱말은 어느 것인가요?","options":[{"t":"없다","correct":true},{"t":"쓰다","mis":"K1-1-u4-X17"},{"t":"읽다","mis":"K1-1-u4-X17"}],"explanation":["「있다」의 반대는 「없다」예요.","「쓰다」·「읽다」는 공부할 때 하는 일이에요.","낱말을 몸으로 해 보며 뜻을 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#22','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C1',3,'mc','auto','그림을 보고 「저거 타고 공원에 가요.」를 낱말을 넣어 바르게 고쳐 말한 것은 어느 것인가요?',ARRAY['K1-1-u4-X01','K1-1-u4-X06']::text[],false,'{"seq":22,"concept":"K1-1-u4-C1","difficulty":3,"kind":"mc","stem":"그림을 보고 「저거 타고 공원에 가요.」를 낱말을 넣어 바르게 고쳐 말한 것은 어느 것인가요?","options":[{"t":"「자전거 타고 공원에 가요.」","correct":true},{"t":"「저것 타고 공원에 가요.」","mis":"K1-1-u4-X01"},{"t":"「자동차 타고 공원에 가요.」","mis":"K1-1-u4-X06"}],"explanation":["그림은 「자전거」예요.","「저것」은 이름이 아니라 뜻이 흐리고, 다른 낱말을 넣으면 그림과 달라요.","가리키는 말 자리에 그림의 이름을 넣어 말해요."],"asset":{"type":"scene","icon":"🚲"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#23','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C3',4,'mc','auto','도윤이는 남자아이이고, 누나가 한 명 있어요. 누나가 보기에 도윤이는 누구인가요?',ARRAY['K1-1-u4-X04']::text[],false,'{"seq":23,"concept":"K1-1-u4-C3","difficulty":4,"kind":"mc","stem":"도윤이는 남자아이이고, 누나가 한 명 있어요. 누나가 보기에 도윤이는 누구인가요?","options":[{"t":"동생","correct":true},{"t":"오빠","mis":"K1-1-u4-X04"},{"t":"형","mis":"K1-1-u4-X04"}],"explanation":["누나보다 어리니 도윤이는 누나의 「동생」이에요.","「오빠」·「형」은 다른 관계를 부르는 말이에요.","누가 누구를 부르는지 자리를 바꿔 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#24','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C5',4,'mc','auto','「우체국에서 빵을 사요.」를 장소와 하는 일이 맞게 고친 것은 어느 것인가요?',ARRAY['K1-1-u4-X10']::text[],false,'{"seq":24,"concept":"K1-1-u4-C5","difficulty":4,"kind":"mc","stem":"「우체국에서 빵을 사요.」를 장소와 하는 일이 맞게 고친 것은 어느 것인가요?","options":[{"t":"빵집에서 빵을 사요.","correct":true},{"t":"우체국에서 꽃을 사요.","mis":"K1-1-u4-X10"},{"t":"빵집에서 편지를 보내요.","mis":"K1-1-u4-X10"}],"explanation":["「빵집에서 빵을 사요.」 — 장소와 하는 일이 어울려요.","다른 두 문장도 장소와 하는 일이 어긋나요.","고친 뒤 「정말 그곳에서 할까?」 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_a#25','kor',1,1,'u4','','g1_1_kor_u4_review_a','unit_review','K1-1-u4-C8',4,'mc','auto','글자판에서 가로(→)나 세로(↓)로 숨어 있지 않은 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":25,"concept":"K1-1-u4-C8","difficulty":4,"kind":"mc","stem":"글자판에서 가로(→)나 세로(↓)로 숨어 있지 않은 낱말은 어느 것인가요?","options":[{"t":"기린","correct":true},{"t":"기차","mis":"K1-1-u4-X16"},{"t":"우유","mis":"K1-1-u4-X16"}],"explanation":["「기린」은 대각선으로 읽어야 나와서 숨은 낱말로 치지 않아요.","「기차」·「우유」는 가로나 세로로 숨어 있어요.","왼쪽 → 오른쪽, 위 → 아래로만 이어 읽어요."],"asset":{"type":"word_grid","rows":["기우유","차린다","표바람"],"ask":"find"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#1','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C1',1,'ox','auto','「그거 어디 있어」라고만 말해도 듣는 사람이 무엇인지 늘 알 수 있어요.',ARRAY['K1-1-u4-X01']::text[],false,'{"seq":1,"concept":"K1-1-u4-C1","difficulty":1,"kind":"ox","stem":"「그거 어디 있어」라고만 말해도 듣는 사람이 무엇인지 늘 알 수 있어요.","answer":"X","reason_options":[{"t":"「그거」는 이름이 아니라 무엇을 가리키는지 알기 어려우니까","correct":true},{"t":"손으로 가리키면 언제나 알아들으니까","mis":"K1-1-u4-X01"}],"mis":"K1-1-u4-X01","explanation":["이름(낱말)을 말해야 뜻이 전해져요.","멀리 있거나 여러 개면 「그거」로는 몰라요.","「그거」 자리에 이름을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#2','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C2',1,'mc','auto','「귀」로 하는 일을 나타내는 말은 어느 것인가요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":2,"concept":"K1-1-u4-C2","difficulty":1,"kind":"mc","stem":"「귀」로 하는 일을 나타내는 말은 어느 것인가요?","options":[{"t":"듣다","correct":true},{"t":"냄새를 맡다","mis":"K1-1-u4-X03"},{"t":"걷다","mis":"K1-1-u4-X03"}],"explanation":["「귀」로 하는 일은 「듣다」예요.","「냄새를 맡다」·「걷다」는 몸의 다른 곳으로 하는 일이에요.","몸의 그곳을 직접 움직여 보며 무엇을 하는지 떠올려요."],"variant_rule":{"wlink":{"ask":"body","mis":{"link":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#3','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C3',1,'mc','auto','엄마의 언니나 여동생을 부르는 말은 어느 것인가요?',ARRAY['K1-1-u4-X04']::text[],false,'{"seq":3,"concept":"K1-1-u4-C3","difficulty":1,"kind":"mc","stem":"엄마의 언니나 여동생을 부르는 말은 어느 것인가요?","options":[{"t":"이모","correct":true},{"t":"고모","mis":"K1-1-u4-X04"},{"t":"누나","mis":"K1-1-u4-X04"}],"explanation":["엄마의 언니나 여동생을 부르는 말은 「이모」예요.","「고모」·「누나」는 다른 관계를 부르는 말이에요.","「누구의 누구인가」를 먼저 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#4','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C4',1,'mc','auto','「국수」에 어울리는 꾸며 주는 말은 어느 것인가요?',ARRAY['K1-1-u4-X09']::text[],false,'{"seq":4,"concept":"K1-1-u4-C4","difficulty":1,"kind":"mc","stem":"「국수」에 어울리는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"긴","correct":true},{"t":"네모난","mis":"K1-1-u4-X09"},{"t":"뾰족한","mis":"K1-1-u4-X09"}],"explanation":["「긴 국수」 — 모습이 잘 어울려요.","네모난·뾰족한 국수는 없어요.","꾸민 모습을 머릿속에 그려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#5','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C5',1,'mc','auto','「빵집」에서 하는 일은 어느 것인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":5,"concept":"K1-1-u4-C5","difficulty":1,"kind":"mc","stem":"「빵집」에서 하는 일은 어느 것인가요?","options":[{"t":"빵을 사요","correct":true},{"t":"불을 끄러 출동해요","mis":"K1-1-u4-X10"},{"t":"꽃을 사요","mis":"K1-1-u4-X10"}],"explanation":["「빵집」에서는 빵을 사요.","「불을 끄러 출동해요」·「꽃을 사요」는 다른 곳에서 하는 일이에요.","장소 이름과 그곳에서 하는 일을 짝 지어 떠올려요."],"variant_rule":{"wlink":{"ask":"place","mis":{"link":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#6','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C6',1,'mc','auto','가족을 부르는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X05','K1-1-u4-X12']::text[],true,'{"seq":6,"concept":"K1-1-u4-C6","difficulty":1,"kind":"mc","stem":"가족을 부르는 낱말은 어느 것인가요?","options":[{"t":"삼촌","correct":true},{"t":"친구","mis":"K1-1-u4-X05"},{"t":"귀","mis":"K1-1-u4-X12"}],"explanation":["「삼촌」은 가족을 부르는 낱말이에요.","「친구」·「귀」는 가족을 부르는 낱말이 아니에요.","낱말이 무엇을 나타내는지 떠올려 묶음을 정해요."],"variant_rule":{"wcat":{"ask":"pick","cats":["family"],"mis":{"near":"X05","other":"X12"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#7','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C7',1,'mc','auto','뜻이 맞는 문장은 어느 것인가요?',ARRAY['K1-1-u4-X14']::text[],false,'{"seq":7,"concept":"K1-1-u4-C7","difficulty":1,"kind":"mc","stem":"뜻이 맞는 문장은 어느 것인가요?","options":[{"t":"「꽃집에서 노란 꽃을 사요.」","correct":true},{"t":"「꽃집에서 편지를 보내요.」","mis":"K1-1-u4-X14"},{"t":"「치과에서 꽃을 심어요.」","mis":"K1-1-u4-X14"}],"explanation":["「꽃집에서 노란 꽃을 사요.」 — 장소와 하는 일이 어울려요.","다른 두 문장은 그곳에서 하지 않는 일이에요.","문장을 읽고 「정말 그럴까?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#8','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C9',1,'mc','auto','그림을 보고 빈칸에 알맞은 낱말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#9','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C2',2,'mc','auto','「냄새를 맡다」는 몸의 어느 곳으로 하는 일인가요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":9,"concept":"K1-1-u4-C2","difficulty":2,"kind":"mc","stem":"「냄새를 맡다」는 몸의 어느 곳으로 하는 일인가요?","options":[{"t":"코","correct":true},{"t":"손","mis":"K1-1-u4-X03"},{"t":"귀","mis":"K1-1-u4-X03"}],"explanation":["「냄새를 맡다」는 「코」로 하는 일이에요.","「손」·「귀」는 다른 일을 해요.","그 일을 할 때 몸의 어디가 바빠지는지 떠올려요."],"variant_rule":{"wlink":{"ask":"bodyr","mis":{"link":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#10','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C3',2,'mc','auto','가족을 부르는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X05']::text[],true,'{"seq":10,"concept":"K1-1-u4-C3","difficulty":2,"kind":"mc","stem":"가족을 부르는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"선생님","correct":true},{"t":"고모","mis":"K1-1-u4-X05"},{"t":"형","mis":"K1-1-u4-X05"}],"explanation":["「선생님」은 가족을 부르는 낱말이 아니에요.","「고모」·「형」은 가족을 부르는 낱말이에요.","묶음마다 무엇을 모았는지 먼저 떠올리고 하나씩 견주어요."],"variant_rule":{"wcat":{"ask":"odd","cats":["family"],"mis":{"in":"X05","near":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#11','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C4',2,'mc','auto','꾸며 주는 말을 바르게 넣은 것은 어느 것인가요?',ARRAY['K1-1-u4-X08','K1-1-u4-X09']::text[],false,'{"seq":11,"concept":"K1-1-u4-C4","difficulty":2,"kind":"mc","stem":"꾸며 주는 말을 바르게 넣은 것은 어느 것인가요?","options":[{"t":"하얀 우유","correct":true},{"t":"우유 하얀","mis":"K1-1-u4-X08"},{"t":"뾰족한 우유","mis":"K1-1-u4-X09"}],"explanation":["꾸며 주는 말 「하얀」은 「우유」 앞에 와요.","뒤에 쓰거나 어울리지 않는 말을 넣으면 안 돼요.","앞에 넣고 소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#12','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C5',2,'mc','auto','「불을 끄러 출동해요」 — 이 일을 하는 곳은 어디인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":12,"concept":"K1-1-u4-C5","difficulty":2,"kind":"mc","stem":"「불을 끄러 출동해요」 — 이 일을 하는 곳은 어디인가요?","options":[{"t":"소방서","correct":true},{"t":"빵집","mis":"K1-1-u4-X10"},{"t":"도서관","mis":"K1-1-u4-X10"}],"explanation":["「소방서」에서 불을 끄러 출동해요.","「빵집」·「도서관」은 하는 일이 달라요.","그 일을 하러 어디에 가는지 떠올려요."],"variant_rule":{"wlink":{"ask":"placer","mis":{"link":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#13','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C6',2,'mc','auto','학교에서 볼 수 있는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X11']::text[],true,'{"seq":13,"concept":"K1-1-u4-C6","difficulty":2,"kind":"mc","stem":"학교에서 볼 수 있는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"냉장고","correct":true},{"t":"교과서","mis":"K1-1-u4-X11"},{"t":"사물함","mis":"K1-1-u4-X11"}],"explanation":["「냉장고」는 학교에서 볼 수 있는 낱말이 아니에요.","「교과서」·「사물함」은 학교에서 볼 수 있는 낱말이에요.","묶음마다 무엇을 모았는지 먼저 떠올리고 하나씩 견주어요."],"variant_rule":{"wcat":{"ask":"odd","cats":["school"],"mis":{"in":"X11","near":"X11"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#14','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C8',2,'mc','auto','초성이 「ㅂ ㄴ ㄴ」인 과일은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":14,"concept":"K1-1-u4-C8","difficulty":2,"kind":"mc","stem":"초성이 「ㅂ ㄴ ㄴ」인 과일은 어느 것인가요?","options":[{"t":"바나나","correct":true},{"t":"배","mis":"K1-1-u4-X16"},{"t":"복숭아","mis":"K1-1-u4-X16"}],"explanation":["바나나 = ㅂ + ㄴ + ㄴ.","「배」·「복숭아」는 초성이 달라요.","글자마다 첫 자음자를 차례대로, 칸 수까지 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#15','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C8',2,'mc','auto','글자판에서 가로(→)나 세로(↓)로 숨어 있는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":15,"concept":"K1-1-u4-C8","difficulty":2,"kind":"mc","stem":"글자판에서 가로(→)나 세로(↓)로 숨어 있는 낱말은 어느 것인가요?","options":[{"t":"토끼","correct":true},{"t":"양말","mis":"K1-1-u4-X16"},{"t":"파도","mis":"K1-1-u4-X16"}],"explanation":["「토끼」는 왼쪽 첫째 줄을 위에서 아래로 읽으면 나와요.","「양말」·「파도」는 글자판에 없어요.","왼쪽 → 오른쪽, 위 → 아래로만 이어 읽어요."],"asset":{"type":"word_grid","rows":["토마토","끼리비","양파누"],"ask":"find"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
