INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#17','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C4',3,'error','auto','태민이가 쓴 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#18','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C6',3,'mc','auto','「학교 · 동네 · 둘 다」 표를 만들었어요. 「화장실」은 어느 칸에 넣으면 좋을까요?',ARRAY['K1-1-u4-X11']::text[],false,'{"seq":18,"concept":"K1-1-u4-C6","difficulty":3,"kind":"mc","stem":"「학교 · 동네 · 둘 다」 표를 만들었어요. 「화장실」은 어느 칸에 넣으면 좋을까요?","options":[{"t":"둘 다","correct":true},{"t":"학교만","mis":"K1-1-u4-X11"},{"t":"동네만","mis":"K1-1-u4-X11"}],"explanation":["화장실은 학교에도 동네 공원에도 있어요.","한 칸에만 넣거나 엉뚱한 칸에 넣으면 안 돼요.","어디에서 볼 수 있는지 떠올려 칸을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#19','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C7',3,'error','auto','태민이가 「서윤이의 심부름」을 듣고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#20','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C8',3,'error','auto','친구들이 「학교에 가면」 놀이를 했어요. 잘못 이어 말한 친구와 그 까닭은 어느 것인가요?',ARRAY['K1-1-u4-X15']::text[],false,'{"seq":20,"concept":"K1-1-u4-C8","difficulty":3,"kind":"error","stem":"친구들이 「학교에 가면」 놀이를 했어요. 잘못 이어 말한 친구와 그 까닭은 어느 것인가요?","options":[{"t":"예린 — 앞에서 말한 「칠판」을 빠뜨렸어요","correct":true,"mis_target":"K1-1-u4-X15"},{"t":"현우 — 낱말을 두 개나 말했어요","mis":"K1-1-u4-X15"},{"t":"소율 — 낱말을 하나만 말했어요","mis":"K1-1-u4-X15"}],"explanation":["예린이는 「칠판」을 빼고 말했어요.","둘째 친구는 앞 말 + 새 낱말로 바르게, 첫째 친구는 처음이라 하나만 말해요.","앞 말을 손가락으로 꼽으며 그대로 말해요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"학교에 가면 칠판도 있고"},{"who":"현우","text":"학교에 가면 칠판도 있고, 교실도 있고"},{"who":"예린","text":"학교에 가면 교실도 있고, 강당도 있고"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#21','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C9',3,'mc','auto','「읽다」와 「쓰다」를 바르게 견준 것은 어느 것인가요?',ARRAY['K1-1-u4-X17']::text[],false,'{"seq":21,"concept":"K1-1-u4-C9","difficulty":3,"kind":"mc","stem":"「읽다」와 「쓰다」를 바르게 견준 것은 어느 것인가요?","options":[{"t":"읽다는 글을 보고 소리 내기, 쓰다는 손으로 글자를 적기","correct":true},{"t":"읽다는 손으로 적기, 쓰다는 소리 내기","mis":"K1-1-u4-X17"},{"t":"읽다와 쓰다는 같은 뜻","mis":"K1-1-u4-X17"}],"explanation":["읽기는 눈과 입, 쓰기는 손으로 해요.","두 낱말은 하는 일이 달라요.","낱말을 몸으로 해 보며 뜻을 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#22','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C1',3,'mc','auto','그림을 보고 「그거 불어 줄래?」를 낱말을 넣어 바르게 고쳐 말한 것은 어느 것인가요?',ARRAY['K1-1-u4-X01','K1-1-u4-X14']::text[],false,'{"seq":22,"concept":"K1-1-u4-C1","difficulty":3,"kind":"mc","stem":"그림을 보고 「그거 불어 줄래?」를 낱말을 넣어 바르게 고쳐 말한 것은 어느 것인가요?","options":[{"t":"「풍선 불어 줄래?」","correct":true},{"t":"「그것 불어 줄래?」","mis":"K1-1-u4-X01"},{"t":"「풍선 먹어 줄래?」","mis":"K1-1-u4-X14"}],"explanation":["그림은 「풍선」이에요.","「그것」은 이름이 아니라 뜻이 흐리고, 다른 낱말을 넣으면 그림과 달라요.","가리키는 말 자리에 그림의 이름을 넣어 말해요."],"asset":{"type":"scene","icon":"🎈"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#23','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C3',4,'mc','auto','하린이는 여자아이이고, 오빠가 한 명 있어요. 하린이의 오빠는 하린이를 무엇이라고 소개할까요?',ARRAY['K1-1-u4-X04']::text[],false,'{"seq":23,"concept":"K1-1-u4-C3","difficulty":4,"kind":"mc","stem":"하린이는 여자아이이고, 오빠가 한 명 있어요. 하린이의 오빠는 하린이를 무엇이라고 소개할까요?","options":[{"t":"동생","correct":true},{"t":"언니","mis":"K1-1-u4-X04"},{"t":"누나","mis":"K1-1-u4-X04"}],"explanation":["오빠보다 어리니 하린이는 오빠의 「동생」이에요.","「언니」·「누나」는 다른 관계를 부르는 말이에요.","누가 누구를 부르는지 자리를 바꿔 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#24','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C5',4,'mc','auto','「은행에서 꽃을 사요.」를 장소와 하는 일이 맞게 고친 것은 어느 것인가요?',ARRAY['K1-1-u4-X10']::text[],false,'{"seq":24,"concept":"K1-1-u4-C5","difficulty":4,"kind":"mc","stem":"「은행에서 꽃을 사요.」를 장소와 하는 일이 맞게 고친 것은 어느 것인가요?","options":[{"t":"꽃집에서 꽃을 사요.","correct":true},{"t":"은행에서 빵을 사요.","mis":"K1-1-u4-X10"},{"t":"꽃집에서 돈을 맡겨요.","mis":"K1-1-u4-X10"}],"explanation":["「꽃집에서 꽃을 사요.」 — 장소와 하는 일이 어울려요.","다른 두 문장도 장소와 하는 일이 어긋나요.","고친 뒤 「정말 그곳에서 할까?」 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_b#25','kor',1,1,'u4','','g1_1_kor_u4_review_b','unit_review','K1-1-u4-C8',4,'mc','auto','글자판에서 가로(→)나 세로(↓)로 숨어 있지 않은 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":25,"concept":"K1-1-u4-C8","difficulty":4,"kind":"mc","stem":"글자판에서 가로(→)나 세로(↓)로 숨어 있지 않은 낱말은 어느 것인가요?","options":[{"t":"사자","correct":true},{"t":"토끼","mis":"K1-1-u4-X16"},{"t":"토마토","mis":"K1-1-u4-X16"}],"explanation":["「사자」는 오른쪽에서 왼쪽으로 거꾸로 읽어야 나와서 숨은 낱말로 치지 않아요.","「토끼」·「토마토」는 가로나 세로로 숨어 있어요.","왼쪽 → 오른쪽, 위 → 아래로만 이어 읽어요."],"asset":{"type":"word_grid","rows":["토끼리","마자사","토리개"],"ask":"find"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#1','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C1',1,'ox','auto','「이거 같이 하자」라고만 말해도 듣는 사람이 무엇인지 늘 알 수 있어요.',ARRAY['K1-1-u4-X01']::text[],false,'{"seq":1,"concept":"K1-1-u4-C1","difficulty":1,"kind":"ox","stem":"「이거 같이 하자」라고만 말해도 듣는 사람이 무엇인지 늘 알 수 있어요.","answer":"X","reason_options":[{"t":"「이거」는 이름이 아니라 무엇을 가리키는지 알기 어려우니까","correct":true},{"t":"손으로 가리키면 언제나 알아들으니까","mis":"K1-1-u4-X01"}],"mis":"K1-1-u4-X01","explanation":["이름(낱말)을 말해야 뜻이 전해져요.","멀리 있거나 여러 개면 「이거」로는 몰라요.","「이거」 자리에 이름을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#2','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C2',1,'mc','auto','「발」로 하는 일을 나타내는 말은 어느 것인가요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":2,"concept":"K1-1-u4-C2","difficulty":1,"kind":"mc","stem":"「발」로 하는 일을 나타내는 말은 어느 것인가요?","options":[{"t":"걷다","correct":true},{"t":"먹다","mis":"K1-1-u4-X03"},{"t":"보다","mis":"K1-1-u4-X03"}],"explanation":["「발」로 하는 일은 「걷다」예요.","「먹다」·「보다」는 몸의 다른 곳으로 하는 일이에요.","몸의 그곳을 직접 움직여 보며 무엇을 하는지 떠올려요."],"variant_rule":{"wlink":{"ask":"body","mis":{"link":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#3','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C3',1,'mc','auto','아빠의 누나나 여동생을 부르는 말은 어느 것인가요?',ARRAY['K1-1-u4-X04']::text[],false,'{"seq":3,"concept":"K1-1-u4-C3","difficulty":1,"kind":"mc","stem":"아빠의 누나나 여동생을 부르는 말은 어느 것인가요?","options":[{"t":"고모","correct":true},{"t":"이모","mis":"K1-1-u4-X04"},{"t":"언니","mis":"K1-1-u4-X04"}],"explanation":["아빠의 누나나 여동생을 부르는 말은 「고모」예요.","「이모」·「언니」는 다른 관계를 부르는 말이에요.","「누구의 누구인가」를 먼저 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#4','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C4',1,'mc','auto','「김치」에 어울리는 꾸며 주는 말은 어느 것인가요?',ARRAY['K1-1-u4-X09']::text[],false,'{"seq":4,"concept":"K1-1-u4-C4","difficulty":1,"kind":"mc","stem":"「김치」에 어울리는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"매운","correct":true},{"t":"달콤한","mis":"K1-1-u4-X09"},{"t":"뾰족한","mis":"K1-1-u4-X09"}],"explanation":["「매운 김치」 — 모습이 잘 어울려요.","달콤한·뾰족한 김치는 없어요.","꾸민 모습을 머릿속에 그려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#5','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C5',1,'mc','auto','「도서관」에서 하는 일은 어느 것인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":5,"concept":"K1-1-u4-C5","difficulty":1,"kind":"mc","stem":"「도서관」에서 하는 일은 어느 것인가요?","options":[{"t":"책을 빌려요","correct":true},{"t":"돈을 맡겨요","mis":"K1-1-u4-X10"},{"t":"점심을 먹어요","mis":"K1-1-u4-X10"}],"explanation":["「도서관」에서는 책을 빌려요.","「돈을 맡겨요」·「점심을 먹어요」는 다른 곳에서 하는 일이에요.","장소 이름과 그곳에서 하는 일을 짝 지어 떠올려요."],"variant_rule":{"wlink":{"ask":"place","mis":{"link":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#6','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C6',1,'mc','auto','음식을 나타내는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X12']::text[],true,'{"seq":6,"concept":"K1-1-u4-C6","difficulty":1,"kind":"mc","stem":"음식을 나타내는 낱말은 어느 것인가요?","options":[{"t":"두부","correct":true},{"t":"냄비","mis":"K1-1-u4-X12"},{"t":"은행","mis":"K1-1-u4-X12"}],"explanation":["「두부」는 음식을 나타내는 낱말이에요.","「냄비」·「은행」은 음식을 나타내는 낱말이 아니에요.","낱말이 무엇을 나타내는지 떠올려 묶음을 정해요."],"variant_rule":{"wcat":{"ask":"pick","cats":["food"],"mis":{"near":"X12","other":"X12"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#7','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C7',1,'mc','auto','뜻이 맞는 문장은 어느 것인가요?',ARRAY['K1-1-u4-X14']::text[],false,'{"seq":7,"concept":"K1-1-u4-C7","difficulty":1,"kind":"mc","stem":"뜻이 맞는 문장은 어느 것인가요?","options":[{"t":"「신호등을 보고 길을 건너요.」","correct":true},{"t":"「신호등에서 점심을 먹어요.」","mis":"K1-1-u4-X14"},{"t":"「빵집에서 돈을 맡겨요.」","mis":"K1-1-u4-X14"}],"explanation":["「신호등을 보고 길을 건너요.」 — 장소와 하는 일이 어울려요.","다른 두 문장은 그곳에서 하지 않는 일이에요.","문장을 읽고 「정말 그럴까?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#8','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C9',1,'mc','auto','그림을 보고 빈칸에 알맞은 낱말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#9','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C2',2,'mc','auto','「먹다」는 몸의 어느 곳으로 하는 일인가요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":9,"concept":"K1-1-u4-C2","difficulty":2,"kind":"mc","stem":"「먹다」는 몸의 어느 곳으로 하는 일인가요?","options":[{"t":"입","correct":true},{"t":"발","mis":"K1-1-u4-X03"},{"t":"귀","mis":"K1-1-u4-X03"}],"explanation":["「먹다」는 「입」으로 하는 일이에요.","「발」·「귀」는 다른 일을 해요.","그 일을 할 때 몸의 어디가 바빠지는지 떠올려요."],"variant_rule":{"wlink":{"ask":"bodyr","mis":{"link":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#10','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C3',2,'mc','auto','가족을 부르는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X05']::text[],true,'{"seq":10,"concept":"K1-1-u4-C3","difficulty":2,"kind":"mc","stem":"가족을 부르는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"이웃","correct":true},{"t":"삼촌","mis":"K1-1-u4-X05"},{"t":"누나","mis":"K1-1-u4-X05"}],"explanation":["「이웃」은 가족을 부르는 낱말이 아니에요.","「삼촌」·「누나」는 가족을 부르는 낱말이에요.","묶음마다 무엇을 모았는지 먼저 떠올리고 하나씩 견주어요."],"variant_rule":{"wcat":{"ask":"odd","cats":["family"],"mis":{"in":"X05","near":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#11','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C4',2,'mc','auto','꾸며 주는 말을 바르게 넣은 것은 어느 것인가요?',ARRAY['K1-1-u4-X08','K1-1-u4-X09']::text[],false,'{"seq":11,"concept":"K1-1-u4-C4","difficulty":2,"kind":"mc","stem":"꾸며 주는 말을 바르게 넣은 것은 어느 것인가요?","options":[{"t":"달콤한 사탕","correct":true},{"t":"사탕 달콤한","mis":"K1-1-u4-X08"},{"t":"매운 사탕","mis":"K1-1-u4-X09"}],"explanation":["꾸며 주는 말 「달콤한」은 「사탕」 앞에 와요.","뒤에 쓰거나 어울리지 않는 말을 넣으면 안 돼요.","앞에 넣고 소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#12','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C5',2,'mc','auto','「점심을 먹어요」 — 이 일을 하는 곳은 어디인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":12,"concept":"K1-1-u4-C5","difficulty":2,"kind":"mc","stem":"「점심을 먹어요」 — 이 일을 하는 곳은 어디인가요?","options":[{"t":"급식실","correct":true},{"t":"은행","mis":"K1-1-u4-X10"},{"t":"꽃집","mis":"K1-1-u4-X10"}],"explanation":["「급식실」에서 점심을 먹어요.","「은행」·「꽃집」은 하는 일이 달라요.","그 일을 하러 어디에 가는지 떠올려요."],"variant_rule":{"wlink":{"ask":"placer","mis":{"link":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#13','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C6',2,'mc','auto','음식을 나타내는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X12']::text[],true,'{"seq":13,"concept":"K1-1-u4-C6","difficulty":2,"kind":"mc","stem":"음식을 나타내는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"숟가락","correct":true},{"t":"감자","mis":"K1-1-u4-X12"},{"t":"우유","mis":"K1-1-u4-X12"}],"explanation":["「숟가락」은 음식을 나타내는 낱말이 아니에요.","「감자」·「우유」는 음식을 나타내는 낱말이에요.","묶음마다 무엇을 모았는지 먼저 떠올리고 하나씩 견주어요."],"variant_rule":{"wcat":{"ask":"odd","cats":["food"],"mis":{"in":"X12","near":"X12"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#14','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C8',2,'mc','auto','초성이 「ㅅ ㅁ ㅎ」인 학교 물건은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":14,"concept":"K1-1-u4-C8","difficulty":2,"kind":"mc","stem":"초성이 「ㅅ ㅁ ㅎ」인 학교 물건은 어느 것인가요?","options":[{"t":"사물함","correct":true},{"t":"실내화","mis":"K1-1-u4-X16"},{"t":"상자","mis":"K1-1-u4-X16"}],"explanation":["사물함 = ㅅ + ㅁ + ㅎ.","「실내화」·「상자」는 초성이 달라요.","글자마다 첫 자음자를 차례대로, 칸 수까지 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#15','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C8',2,'mc','auto','글자판에서 가로(→)나 세로(↓)로 숨어 있는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":15,"concept":"K1-1-u4-C8","difficulty":2,"kind":"mc","stem":"글자판에서 가로(→)나 세로(↓)로 숨어 있는 낱말은 어느 것인가요?","options":[{"t":"가방","correct":true},{"t":"공책","mis":"K1-1-u4-X16"},{"t":"지우개","mis":"K1-1-u4-X16"}],"explanation":["「가방」은 왼쪽 첫째 줄을 위에서 아래로 읽으면 나와요.","「공책」·「지우개」는 글자판에 없어요.","왼쪽 → 오른쪽, 위 → 아래로만 이어 읽어요."],"asset":{"type":"word_grid","rows":["연필통","가위자","방석지"],"ask":"find"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#16','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C9',2,'mc','auto','빈칸에 알맞은 낱말을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#17','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C4',3,'error','auto','지안이가 쓴 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#18','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C6',3,'mc','auto','「학교 · 동네 · 둘 다」 표를 만들었어요. 「교탁」은 어느 칸에 넣으면 좋을까요?',ARRAY['K1-1-u4-X11']::text[],false,'{"seq":18,"concept":"K1-1-u4-C6","difficulty":3,"kind":"mc","stem":"「학교 · 동네 · 둘 다」 표를 만들었어요. 「교탁」은 어느 칸에 넣으면 좋을까요?","options":[{"t":"학교만","correct":true},{"t":"동네만","mis":"K1-1-u4-X11"},{"t":"둘 다","mis":"K1-1-u4-X11"}],"explanation":["교탁은 교실 앞 선생님 책상이에요.","한 칸에만 넣거나 엉뚱한 칸에 넣으면 안 돼요.","어디에서 볼 수 있는지 떠올려 칸을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#19','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C7',3,'error','auto','지안이가 「학교 가는 길」을 듣고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#20','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C8',3,'error','auto','친구들이 「시장에 가면」 놀이를 했어요. 잘못 이어 말한 친구와 그 까닭은 어느 것인가요?',ARRAY['K1-1-u4-X15']::text[],false,'{"seq":20,"concept":"K1-1-u4-C8","difficulty":3,"kind":"error","stem":"친구들이 「시장에 가면」 놀이를 했어요. 잘못 이어 말한 친구와 그 까닭은 어느 것인가요?","options":[{"t":"준우 — 앞에서 말한 「사과」를 빠뜨렸어요","correct":true,"mis_target":"K1-1-u4-X15"},{"t":"다은 — 낱말을 두 개나 말했어요","mis":"K1-1-u4-X15"},{"t":"시우 — 낱말을 하나만 말했어요","mis":"K1-1-u4-X15"}],"explanation":["준우는 「사과」를 빼고 말했어요.","둘째 친구는 앞 말 + 새 낱말로 바르게, 첫째 친구는 처음이라 하나만 말해요.","앞 말을 손가락으로 꼽으며 그대로 말해요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"시장에 가면 사과도 있고"},{"who":"다은","text":"시장에 가면 사과도 있고, 떡도 있고"},{"who":"준우","text":"시장에 가면 떡도 있고, 두부도 있고"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#21','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C9',3,'mc','auto','「차례」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K1-1-u4-X17']::text[],false,'{"seq":21,"concept":"K1-1-u4-C9","difficulty":3,"kind":"mc","stem":"「차례」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"여럿이 순서대로 하나씩 하는 것, 또는 그 순서","correct":true},{"t":"아무 때나 먼저 하는 것","mis":"K1-1-u4-X17"},{"t":"물건이 하나도 없는 것","mis":"K1-1-u4-X17"}],"explanation":["「차례」는 순서예요.","먼저 끼어드는 것이나 없는 것과는 달라요.","낱말을 몸으로 해 보며 뜻을 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#22','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C1',3,'mc','auto','그림을 보고 「비가 와서 저거 썼어요.」를 낱말을 넣어 바르게 고쳐 말한 것은 어느 것인가요?',ARRAY['K1-1-u4-X01','K1-1-u4-X14']::text[],false,'{"seq":22,"concept":"K1-1-u4-C1","difficulty":3,"kind":"mc","stem":"그림을 보고 「비가 와서 저거 썼어요.」를 낱말을 넣어 바르게 고쳐 말한 것은 어느 것인가요?","options":[{"t":"「비가 와서 우산 썼어요.」","correct":true},{"t":"「비가 와서 저기 썼어요.」","mis":"K1-1-u4-X01"},{"t":"「비가 와서 양말 썼어요.」","mis":"K1-1-u4-X14"}],"explanation":["그림은 「우산」이에요.","「저기」는 이름이 아니라 뜻이 흐리고, 다른 낱말을 넣으면 그림과 달라요.","가리키는 말 자리에 그림의 이름을 넣어 말해요."],"asset":{"type":"scene","icon":"☂️"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#23','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C3',4,'mc','auto','시우의 엄마에게 언니가 있어요. 시우는 그분을 무엇이라고 부르나요?',ARRAY['K1-1-u4-X04']::text[],false,'{"seq":23,"concept":"K1-1-u4-C3","difficulty":4,"kind":"mc","stem":"시우의 엄마에게 언니가 있어요. 시우는 그분을 무엇이라고 부르나요?","options":[{"t":"이모","correct":true},{"t":"고모","mis":"K1-1-u4-X04"},{"t":"할머니","mis":"K1-1-u4-X04"}],"explanation":["엄마의 언니는 시우에게 「이모」예요.","「고모」·「할머니」는 다른 관계를 부르는 말이에요.","누가 누구를 부르는지 자리를 바꿔 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#24','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C5',4,'mc','auto','「급식실에서 책을 빌려요.」를 장소와 하는 일이 맞게 고친 것은 어느 것인가요?',ARRAY['K1-1-u4-X10']::text[],false,'{"seq":24,"concept":"K1-1-u4-C5","difficulty":4,"kind":"mc","stem":"「급식실에서 책을 빌려요.」를 장소와 하는 일이 맞게 고친 것은 어느 것인가요?","options":[{"t":"도서관에서 책을 빌려요.","correct":true},{"t":"급식실에서 편지를 보내요.","mis":"K1-1-u4-X10"},{"t":"도서관에서 점심을 먹어요.","mis":"K1-1-u4-X10"}],"explanation":["「도서관에서 책을 빌려요.」 — 장소와 하는 일이 어울려요.","다른 두 문장도 장소와 하는 일이 어긋나요.","고친 뒤 「정말 그곳에서 할까?」 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_c#25','kor',1,1,'u4','','g1_1_kor_u4_review_c','unit_review','K1-1-u4-C8',4,'mc','auto','글자판에서 가로(→)나 세로(↓)로 숨어 있지 않은 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":25,"concept":"K1-1-u4-C8","difficulty":4,"kind":"mc","stem":"글자판에서 가로(→)나 세로(↓)로 숨어 있지 않은 낱말은 어느 것인가요?","options":[{"t":"바다","correct":true},{"t":"다리","mis":"K1-1-u4-X16"},{"t":"개미","mis":"K1-1-u4-X16"}],"explanation":["「바다」는 대각선으로 읽어야 나와서 숨은 낱말로 치지 않아요.","「다리」·「개미」는 가로나 세로로 숨어 있어요.","왼쪽 → 오른쪽, 위 → 아래로만 이어 읽어요."],"asset":{"type":"word_grid","rows":["바나나","지다리","개미비"],"ask":"find"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#1','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C1',1,'ox','auto','「저기 가자」라고만 말해도 듣는 사람이 어디인지 늘 알 수 있어요.',ARRAY['K1-1-u4-X01']::text[],false,'{"seq":1,"concept":"K1-1-u4-C1","difficulty":1,"kind":"ox","stem":"「저기 가자」라고만 말해도 듣는 사람이 어디인지 늘 알 수 있어요.","answer":"X","reason_options":[{"t":"「저기」는 이름이 아니라 무엇을 가리키는지 알기 어려우니까","correct":true},{"t":"손으로 가리키면 언제나 알아들으니까","mis":"K1-1-u4-X01"}],"mis":"K1-1-u4-X01","explanation":["이름(낱말)을 말해야 뜻이 전해져요.","멀리 있거나 여러 개면 「저기」로는 몰라요.","「저기」 자리에 이름을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#2','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C2',1,'mc','auto','「손」으로 하는 일을 나타내는 말은 어느 것인가요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":2,"concept":"K1-1-u4-C2","difficulty":1,"kind":"mc","stem":"「손」으로 하는 일을 나타내는 말은 어느 것인가요?","options":[{"t":"잡다","correct":true},{"t":"듣다","mis":"K1-1-u4-X03"},{"t":"냄새를 맡다","mis":"K1-1-u4-X03"}],"explanation":["「손」으로 하는 일은 「잡다」예요.","「듣다」·「냄새를 맡다」는 몸의 다른 곳으로 하는 일이에요.","몸의 그곳을 직접 움직여 보며 무엇을 하는지 떠올려요."],"variant_rule":{"wlink":{"ask":"body","mis":{"link":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#3','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C3',1,'mc','auto','아빠의 아빠를 부르는 말은 어느 것인가요?',ARRAY['K1-1-u4-X04']::text[],false,'{"seq":3,"concept":"K1-1-u4-C3","difficulty":1,"kind":"mc","stem":"아빠의 아빠를 부르는 말은 어느 것인가요?","options":[{"t":"할아버지","correct":true},{"t":"삼촌","mis":"K1-1-u4-X04"},{"t":"오빠","mis":"K1-1-u4-X04"}],"explanation":["아빠의 아빠를 부르는 말은 「할아버지」예요.","「삼촌」·「오빠」는 다른 관계를 부르는 말이에요.","「누구의 누구인가」를 먼저 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#4','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C4',1,'mc','auto','「두부」에 어울리는 꾸며 주는 말은 어느 것인가요?',ARRAY['K1-1-u4-X09']::text[],false,'{"seq":4,"concept":"K1-1-u4-C4","difficulty":1,"kind":"mc","stem":"「두부」에 어울리는 꾸며 주는 말은 어느 것인가요?","options":[{"t":"네모난","correct":true},{"t":"긴","mis":"K1-1-u4-X09"},{"t":"뾰족한","mis":"K1-1-u4-X09"}],"explanation":["「네모난 두부」 — 모습이 잘 어울려요.","긴·뾰족한 두부는 없어요.","꾸민 모습을 머릿속에 그려 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#5','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C5',1,'mc','auto','「꽃집」에서 하는 일은 어느 것인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":5,"concept":"K1-1-u4-C5","difficulty":1,"kind":"mc","stem":"「꽃집」에서 하는 일은 어느 것인가요?","options":[{"t":"꽃을 사요","correct":true},{"t":"편지를 보내요","mis":"K1-1-u4-X10"},{"t":"책을 빌려요","mis":"K1-1-u4-X10"}],"explanation":["「꽃집」에서는 꽃을 사요.","「편지를 보내요」·「책을 빌려요」는 다른 곳에서 하는 일이에요.","장소 이름과 그곳에서 하는 일을 짝 지어 떠올려요."],"variant_rule":{"wlink":{"ask":"place","mis":{"link":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#6','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C6',1,'mc','auto','동네에서 볼 수 있는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X11']::text[],true,'{"seq":6,"concept":"K1-1-u4-C6","difficulty":1,"kind":"mc","stem":"동네에서 볼 수 있는 낱말은 어느 것인가요?","options":[{"t":"시장","correct":true},{"t":"부엌","mis":"K1-1-u4-X11"},{"t":"교실","mis":"K1-1-u4-X11"}],"explanation":["「시장」은 동네에서 볼 수 있는 낱말이에요.","「부엌」·「교실」은 동네에서 볼 수 있는 낱말이 아니에요.","낱말이 무엇을 나타내는지 떠올려 묶음을 정해요."],"variant_rule":{"wcat":{"ask":"pick","cats":["town"],"mis":{"near":"X11","other":"X11"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#7','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C7',1,'mc','auto','뜻이 맞는 문장은 어느 것인가요?',ARRAY['K1-1-u4-X14']::text[],false,'{"seq":7,"concept":"K1-1-u4-C7","difficulty":1,"kind":"mc","stem":"뜻이 맞는 문장은 어느 것인가요?","options":[{"t":"「약국에서 감기약을 사요.」","correct":true},{"t":"「약국에서 버스를 타요.」","mis":"K1-1-u4-X14"},{"t":"「우체국에서 빵을 사요.」","mis":"K1-1-u4-X14"}],"explanation":["「약국에서 감기약을 사요.」 — 장소와 하는 일이 어울려요.","다른 두 문장은 그곳에서 하지 않는 일이에요.","문장을 읽고 「정말 그럴까?」 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
