INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#9','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C2',2,'mc','auto','「걷다」는 몸의 어느 곳으로 하는 일인가요?',ARRAY['K1-1-u4-X03']::text[],true,'{"seq":9,"concept":"K1-1-u4-C2","difficulty":2,"kind":"mc","stem":"「걷다」는 몸의 어느 곳으로 하는 일인가요?","options":[{"t":"발","correct":true},{"t":"손","mis":"K1-1-u4-X03"},{"t":"코","mis":"K1-1-u4-X03"}],"explanation":["「걷다」는 「발」로 하는 일이에요.","「손」·「코」는 다른 일을 해요.","그 일을 할 때 몸의 어디가 바빠지는지 떠올려요."],"variant_rule":{"wlink":{"ask":"bodyr","mis":{"link":"X03"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#10','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C3',2,'mc','auto','가족을 부르는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X05']::text[],true,'{"seq":10,"concept":"K1-1-u4-C3","difficulty":2,"kind":"mc","stem":"가족을 부르는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"의사","correct":true},{"t":"언니","mis":"K1-1-u4-X05"},{"t":"할머니","mis":"K1-1-u4-X05"}],"explanation":["「의사」는 가족을 부르는 낱말이 아니에요.","「언니」·「할머니」는 가족을 부르는 낱말이에요.","묶음마다 무엇을 모았는지 먼저 떠올리고 하나씩 견주어요."],"variant_rule":{"wcat":{"ask":"odd","cats":["family"],"mis":{"in":"X05","near":"X05"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#11','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C4',2,'mc','auto','꾸며 주는 말을 바르게 넣은 것은 어느 것인가요?',ARRAY['K1-1-u4-X08','K1-1-u4-X09']::text[],false,'{"seq":11,"concept":"K1-1-u4-C4","difficulty":2,"kind":"mc","stem":"꾸며 주는 말을 바르게 넣은 것은 어느 것인가요?","options":[{"t":"커다란 수박","correct":true},{"t":"수박 커다란","mis":"K1-1-u4-X08"},{"t":"꼬불꼬불한 수박","mis":"K1-1-u4-X09"}],"explanation":["꾸며 주는 말 「커다란」은 「수박」 앞에 와요.","뒤에 쓰거나 어울리지 않는 말을 넣으면 안 돼요.","앞에 넣고 소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#12','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C5',2,'mc','auto','「이를 치료받아요」 — 이 일을 하는 곳은 어디인가요?',ARRAY['K1-1-u4-X10']::text[],true,'{"seq":12,"concept":"K1-1-u4-C5","difficulty":2,"kind":"mc","stem":"「이를 치료받아요」 — 이 일을 하는 곳은 어디인가요?","options":[{"t":"치과","correct":true},{"t":"빵집","mis":"K1-1-u4-X10"},{"t":"우체국","mis":"K1-1-u4-X10"}],"explanation":["「치과」에서 이를 치료받아요.","「빵집」·「우체국」은 하는 일이 달라요.","그 일을 하러 어디에 가는지 떠올려요."],"variant_rule":{"wlink":{"ask":"placer","mis":{"link":"X10"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#13','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C6',2,'mc','auto','동네에서 볼 수 있는 낱말이 아닌 것은 어느 것인가요?',ARRAY['K1-1-u4-X11']::text[],true,'{"seq":13,"concept":"K1-1-u4-C6","difficulty":2,"kind":"mc","stem":"동네에서 볼 수 있는 낱말이 아닌 것은 어느 것인가요?","options":[{"t":"욕실","correct":true},{"t":"은행","mis":"K1-1-u4-X11"},{"t":"미용실","mis":"K1-1-u4-X11"}],"explanation":["「욕실」은 동네에서 볼 수 있는 낱말이 아니에요.","「은행」·「미용실」은 동네에서 볼 수 있는 낱말이에요.","묶음마다 무엇을 모았는지 먼저 떠올리고 하나씩 견주어요."],"variant_rule":{"wcat":{"ask":"odd","cats":["town"],"mis":{"in":"X11","near":"X11"}}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#14','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C8',2,'mc','auto','초성이 「ㅇ ㅅ」인 물건은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":14,"concept":"K1-1-u4-C8","difficulty":2,"kind":"mc","stem":"초성이 「ㅇ ㅅ」인 물건은 어느 것인가요?","options":[{"t":"우산","correct":true},{"t":"우유","mis":"K1-1-u4-X16"},{"t":"안경","mis":"K1-1-u4-X16"}],"explanation":["우산 = ㅇ + ㅅ.","「우유」·「안경」은 초성이 달라요.","글자마다 첫 자음자를 차례대로, 칸 수까지 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#15','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C8',2,'mc','auto','글자판에서 가로(→)나 세로(↓)로 숨어 있는 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":15,"concept":"K1-1-u4-C8","difficulty":2,"kind":"mc","stem":"글자판에서 가로(→)나 세로(↓)로 숨어 있는 낱말은 어느 것인가요?","options":[{"t":"구두","correct":true},{"t":"구슬","mis":"K1-1-u4-X16"},{"t":"두더지","mis":"K1-1-u4-X16"}],"explanation":["「구두」는 왼쪽 첫째 줄을 위에서 아래로 읽으면 나와요.","「구슬」·「두더지」는 글자판에 없어요.","왼쪽 → 오른쪽, 위 → 아래로만 이어 읽어요."],"asset":{"type":"word_grid","rows":["구름비","두부누","다리개"],"ask":"find"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
