INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#17','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C4',3,'error','auto','도윤이가 쓴 글이에요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#18','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C6',3,'mc','auto','「학교 · 동네 · 둘 다」 표를 만들었어요. 「미용실」은 어느 칸에 넣으면 좋을까요?',ARRAY['K1-1-u4-X11']::text[],false,'{"seq":18,"concept":"K1-1-u4-C6","difficulty":3,"kind":"mc","stem":"「학교 · 동네 · 둘 다」 표를 만들었어요. 「미용실」은 어느 칸에 넣으면 좋을까요?","options":[{"t":"동네만","correct":true},{"t":"학교만","mis":"K1-1-u4-X11"},{"t":"둘 다","mis":"K1-1-u4-X11"}],"explanation":["미용실은 동네에서 머리를 자르는 곳이에요.","한 칸에만 넣거나 엉뚱한 칸에 넣으면 안 돼요.","어디에서 볼 수 있는지 떠올려 칸을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#19','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C7',3,'error','auto','하린이가 「학교 가는 길」을 듣고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#20','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C8',3,'error','auto','친구들이 「동네에 가면」 놀이를 했어요. 잘못 이어 말한 친구와 그 까닭은 어느 것인가요?',ARRAY['K1-1-u4-X15']::text[],false,'{"seq":20,"concept":"K1-1-u4-C8","difficulty":3,"kind":"error","stem":"친구들이 「동네에 가면」 놀이를 했어요. 잘못 이어 말한 친구와 그 까닭은 어느 것인가요?","options":[{"t":"도윤 — 앞에서 말한 「약국」을 빠뜨렸어요","correct":true,"mis_target":"K1-1-u4-X15"},{"t":"서윤 — 낱말을 두 개나 말했어요","mis":"K1-1-u4-X15"},{"t":"로아 — 낱말을 하나만 말했어요","mis":"K1-1-u4-X15"}],"explanation":["도윤이는 「약국」을 빼고 말했어요.","둘째 친구는 앞 말 + 새 낱말로 바르게, 첫째 친구는 처음이라 하나만 말해요.","앞 말을 손가락으로 꼽으며 그대로 말해요."],"asset":{"type":"speech","turns":[{"who":"로아","text":"동네에 가면 약국도 있고"},{"who":"서윤","text":"동네에 가면 약국도 있고, 시장도 있고"},{"who":"도윤","text":"동네에 가면 시장도 있고, 은행도 있고"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#21','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C9',3,'mc','auto','「없다」와 뜻이 반대인 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X17']::text[],false,'{"seq":21,"concept":"K1-1-u4-C9","difficulty":3,"kind":"mc","stem":"「없다」와 뜻이 반대인 낱말은 어느 것인가요?","options":[{"t":"있다","correct":true},{"t":"읽다","mis":"K1-1-u4-X17"},{"t":"차례","mis":"K1-1-u4-X17"}],"explanation":["「없다」의 반대는 「있다」예요.","「읽다」·「차례」는 반대말이 아니에요.","낱말을 몸으로 해 보며 뜻을 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#22','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C1',3,'mc','auto','그림을 보고 「추워서 이거 신었어요.」를 낱말을 넣어 바르게 고쳐 말한 것은 어느 것인가요?',ARRAY['K1-1-u4-X01','K1-1-u4-X14']::text[],false,'{"seq":22,"concept":"K1-1-u4-C1","difficulty":3,"kind":"mc","stem":"그림을 보고 「추워서 이거 신었어요.」를 낱말을 넣어 바르게 고쳐 말한 것은 어느 것인가요?","options":[{"t":"「추워서 양말 신었어요.」","correct":true},{"t":"「추워서 이것 신었어요.」","mis":"K1-1-u4-X01"},{"t":"「추워서 모자 신었어요.」","mis":"K1-1-u4-X14"}],"explanation":["그림은 「양말」이에요.","「이것」은 이름이 아니라 뜻이 흐리고, 다른 낱말을 넣으면 그림과 달라요.","가리키는 말 자리에 그림의 이름을 넣어 말해요."],"asset":{"type":"scene","icon":"🧦"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#23','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C3',4,'mc','auto','예린이의 아빠에게 여동생이 있어요. 예린이는 그분을 무엇이라고 부르나요?',ARRAY['K1-1-u4-X04']::text[],false,'{"seq":23,"concept":"K1-1-u4-C3","difficulty":4,"kind":"mc","stem":"예린이의 아빠에게 여동생이 있어요. 예린이는 그분을 무엇이라고 부르나요?","options":[{"t":"고모","correct":true},{"t":"이모","mis":"K1-1-u4-X04"},{"t":"언니","mis":"K1-1-u4-X04"}],"explanation":["아빠의 여동생은 예린이에게 「고모」예요.","「이모」·「언니」는 다른 관계를 부르는 말이에요.","누가 누구를 부르는지 자리를 바꿔 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#24','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C5',4,'mc','auto','「소방서에서 이를 치료받아요.」를 장소와 하는 일이 맞게 고친 것은 어느 것인가요?',ARRAY['K1-1-u4-X10']::text[],false,'{"seq":24,"concept":"K1-1-u4-C5","difficulty":4,"kind":"mc","stem":"「소방서에서 이를 치료받아요.」를 장소와 하는 일이 맞게 고친 것은 어느 것인가요?","options":[{"t":"치과에서 이를 치료받아요.","correct":true},{"t":"소방서에서 약을 사요.","mis":"K1-1-u4-X10"},{"t":"치과에서 불을 끄러 출동해요.","mis":"K1-1-u4-X10"}],"explanation":["「치과에서 이를 치료받아요.」 — 장소와 하는 일이 어울려요.","다른 두 문장도 장소와 하는 일이 어긋나요.","고친 뒤 「정말 그곳에서 할까?」 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_kor_u4_review_d#25','kor',1,1,'u4','','g1_1_kor_u4_review_d','unit_review','K1-1-u4-C8',4,'mc','auto','글자판에서 가로(→)나 세로(↓)로 숨어 있지 않은 낱말은 어느 것인가요?',ARRAY['K1-1-u4-X16']::text[],false,'{"seq":25,"concept":"K1-1-u4-C8","difficulty":4,"kind":"mc","stem":"글자판에서 가로(→)나 세로(↓)로 숨어 있지 않은 낱말은 어느 것인가요?","options":[{"t":"우산","correct":true},{"t":"우유","mis":"K1-1-u4-X16"},{"t":"비누","mis":"K1-1-u4-X16"}],"explanation":["「우산」은 아래에서 위로 거꾸로 읽어야 나와서 숨은 낱말로 치지 않아요.","「우유」·「비누」는 가로나 세로로 숨어 있어요.","왼쪽 → 오른쪽, 위 → 아래로만 이어 읽어요."],"asset":{"type":"word_grid","rows":["산책길","우유리","비누컵"],"ask":"find"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
